:root {
  --ink: #080b10;
  --ink-soft: #0e141d;
  --panel: rgba(12, 17, 25, 0.82);
  --panel-heavy: rgba(9, 13, 19, 0.94);
  --line: rgba(226, 192, 120, 0.28);
  --line-soft: rgba(226, 192, 120, 0.12);
  --gold: #e4bf78;
  --gold-bright: #ffe6ab;
  --gold-deep: #9b7233;
  --cream: #f6eddb;
  --muted: #a9a28f;
  --cyan: #92e7df;
  --cyan-deep: #2b8d8a;
  --red: #e25f55;
  --green: #7fcf93;
  --blue: #7bb8eb;
  --violet: #bca3ee;
  --shadow: 0 24px 80px rgba(0, 0, 0, 0.55);
  --serif: "Cinzel", "Times New Roman", serif;
  --sans: "Alegreya Sans", "Trebuchet MS", sans-serif;
}

* { box-sizing: border-box; }
html, body { width: 100%; height: 100%; margin: 0; padding: 0; overflow: hidden; background: var(--ink); }
body {
  font-family: var(--sans);
  color: var(--cream);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overscroll-behavior: none;
  user-select: none;
}
button, input { font: inherit; }
button { color: inherit; cursor: pointer; border: 0; background: none; }
button:focus-visible, input:focus-visible { outline: 2px solid var(--gold-bright); outline-offset: 3px; }
p, h1, h2, h3, h4 { margin: 0; }

#app { position: fixed; inset: 0; isolation: isolate; background: #080b10; }
#game-canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; }
.screen-shade {
  position: absolute; inset: 0; pointer-events: none; z-index: 2;
  background: linear-gradient(180deg, rgba(3, 5, 8, 0.12) 0%, transparent 24%, transparent 66%, rgba(3, 5, 8, 0.46) 100%);
}
.vignette {
  position: absolute; inset: 0; pointer-events: none; z-index: 3;
  background: radial-gradient(ellipse at 50% 48%, transparent 42%, rgba(4, 6, 10, 0.38) 82%, rgba(4, 6, 10, 0.82) 100%);
  mix-blend-mode: multiply;
}
.grain {
  position: absolute; inset: -20%; pointer-events: none; z-index: 4; opacity: 0.055;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.55'/%3E%3C/svg%3E");
  animation: grainShift 0.45s steps(2) infinite;
}
@keyframes grainShift { 0% { transform: translate(0,0); } 50% { transform: translate(1.5%,-1%); } 100% { transform: translate(-1%,1%); } }

.screen {
  position: absolute; inset: 0; z-index: 20; display: none;
  opacity: 0; pointer-events: none; transition: opacity 0.55s ease;
}
.screen.is-active { display: flex; opacity: 1; pointer-events: auto; }
.screen.is-leaving { opacity: 0; pointer-events: none; }

.eyebrow {
  font-family: var(--sans); font-size: 0.7rem; font-weight: 700; letter-spacing: 0.28em;
  color: var(--gold); text-transform: uppercase;
}
kbd {
  display: inline-flex; min-width: 1.65em; min-height: 1.65em; align-items: center; justify-content: center;
  padding: 0 0.42em; border: 1px solid rgba(255, 231, 178, 0.36); border-radius: 4px;
  background: rgba(255,255,255,0.06); color: var(--gold-bright);
  font-family: var(--sans); font-size: 0.7rem; font-weight: 700; letter-spacing: 0.04em;
}

/* ---------- Loading ---------- */
.loading-screen {
  flex-direction: column; align-items: center; justify-content: center; gap: 0.65rem;
  background: radial-gradient(ellipse at center, #101b25 0%, #080b10 65%);
}
.loading-screen .eyebrow { margin-top: 2rem; }
.loading-sigil { position: relative; width: 124px; height: 124px; display: grid; place-items: center; }
.sigil-ring { position: absolute; inset: 0; border-radius: 50%; border: 1px solid rgba(228,191,120,0.45); }
.sigil-ring::before, .sigil-ring::after { content: ""; position: absolute; inset: 9px; border: 1px solid rgba(146,231,223,0.16); border-radius: 50%; }
.ring-a { animation: spin 8s linear infinite; border-style: dashed; }
.ring-b { inset: 17px; animation: spinBack 5s linear infinite; border-color: rgba(146,231,223,0.45); }
.sigil-core {
  width: 20px; height: 44px; background: linear-gradient(180deg, var(--gold-bright), var(--gold-deep));
  clip-path: polygon(50% 0, 100% 35%, 72% 100%, 28% 100%, 0 35%);
  box-shadow: 0 0 28px rgba(255,226,160,0.75);
  animation: corePulse 2s ease-in-out infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }
@keyframes spinBack { to { transform: rotate(-360deg); } }
@keyframes corePulse { 50% { filter: brightness(1.4); transform: scale(1.06); } }
.loading-copy { font-family: var(--serif); font-size: 1.15rem; letter-spacing: 0.12em; }
.loading-track { width: min(320px, 70vw); height: 2px; background: rgba(255,255,255,0.08); margin-top: 0.8rem; overflow: hidden; }
.loading-track i { display: block; width: 0%; height: 100%; background: linear-gradient(90deg, transparent, var(--gold), var(--gold-bright)); transition: width 0.4s ease; box-shadow: 0 0 18px var(--gold); }
.loading-detail { font-size: 0.75rem; color: var(--muted); letter-spacing: 0.12em; }

/* ---------- Title ---------- */
.title-screen {
  flex-direction: column; justify-content: center; padding: clamp(1.5rem, 4vw, 4rem) clamp(1.5rem, 6vw, 7rem);
  background: linear-gradient(90deg, rgba(5,8,12,0.88) 0%, rgba(5,8,12,0.48) 37%, rgba(5,8,12,0.03) 65%, rgba(5,8,12,0.32) 100%);
}
.title-screen::after {
  content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: 25%;
  background: linear-gradient(0deg, rgba(4,6,9,0.85), transparent); pointer-events: none;
}
.title-top { position: absolute; top: clamp(1.2rem, 3vh, 2.4rem); left: clamp(1.5rem, 6vw, 7rem); display: flex; gap: 0.75rem; align-items: center; font-size: 0.63rem; font-weight: 700; letter-spacing: 0.32em; color: rgba(246,237,219,0.62); }
.title-mark { color: var(--gold); font-size: 1rem; text-shadow: 0 0 20px var(--gold); }
.title-lockup { position: relative; z-index: 2; max-width: 700px; animation: riseIn 1s cubic-bezier(.2,.8,.2,1) both; }
.title-kicker { color: var(--gold); font-size: 0.68rem; font-weight: 700; letter-spacing: 0.38em; margin-bottom: 0.9rem; }
.title-lockup h1 {
  font-family: var(--serif); font-weight: 900; font-size: clamp(3rem, 7.4vw, 7.3rem); line-height: 0.88;
  letter-spacing: 0.01em; text-shadow: 0 8px 48px rgba(0,0,0,0.8); margin-left: -0.04em;
}
.title-lockup h1 em { font-style: normal; color: var(--gold-bright); display: inline-block; padding-left: 0.1em; text-shadow: 0 0 60px rgba(228,191,120,0.25), 0 8px 48px rgba(0,0,0,0.8); }
.title-rule { display: flex; align-items: center; gap: 1rem; width: min(460px, 80%); margin: 1.4rem 0 1rem; color: var(--gold); }
.title-rule span { flex: 1; height: 1px; background: linear-gradient(90deg, transparent, rgba(228,191,120,0.65)); }
.title-rule span:last-child { background: linear-gradient(90deg, rgba(228,191,120,0.65), transparent); }
.title-rule i { font-style: normal; font-size: 0.85rem; }
.title-sub { max-width: 440px; color: rgba(246,237,219,0.68); font-size: clamp(0.9rem, 1.15vw, 1.1rem); line-height: 1.55; }
.title-menu { position: relative; z-index: 3; width: min(420px, 90vw); margin-top: clamp(1.7rem, 4.5vh, 3.6rem); display: flex; flex-direction: column; gap: 0.32rem; animation: riseIn 1s 0.2s cubic-bezier(.2,.8,.2,1) both; }
.menu-btn {
  position: relative; display: flex; align-items: center; gap: 1rem; width: 100%; padding: 0.78rem 0.9rem;
  border: 1px solid transparent; border-left: 1px solid rgba(228,191,120,0.16); text-align: left;
  background: linear-gradient(90deg, rgba(255,255,255,0.035), transparent 80%);
  transition: background 0.25s, border-color 0.25s, transform 0.25s;
}
.menu-btn:hover, .menu-btn:focus-visible { background: linear-gradient(90deg, rgba(228,191,120,0.14), rgba(228,191,120,0.02) 80%); border-color: rgba(228,191,120,0.34); border-left-color: var(--gold); transform: translateX(5px); outline: none; }
.menu-btn.primary { border-color: rgba(228,191,120,0.3); background: linear-gradient(90deg, rgba(228,191,120,0.17), rgba(228,191,120,0.015)); }
.menu-btn.primary::before { content: ""; position: absolute; left: -1px; top: 20%; bottom: 20%; width: 2px; background: var(--gold-bright); box-shadow: 0 0 16px var(--gold); }
.menu-btn:disabled { opacity: 0.38; cursor: default; transform: none; }
.menu-btn .menu-index { font-family: var(--serif); color: var(--gold); font-size: 0.72rem; width: 1.2rem; opacity: 0.8; }
.menu-btn b { display: block; font-family: var(--serif); font-size: clamp(0.95rem, 1.25vw, 1.14rem); font-weight: 700; letter-spacing: 0.03em; }
.menu-btn small { display: block; color: rgba(246,237,219,0.48); font-size: 0.72rem; letter-spacing: 0.03em; margin-top: 0.08rem; }
.menu-btn > i { margin-left: auto; font-style: normal; color: var(--gold); font-size: 1.4rem; opacity: 0; transform: translateX(-5px); transition: 0.25s; }
.menu-btn:hover > i { opacity: 1; transform: none; }
.title-footer { position: absolute; z-index: 3; left: clamp(1.5rem, 6vw, 7rem); right: clamp(1.5rem, 6vw, 7rem); bottom: 1.25rem; display: flex; justify-content: space-between; gap: 1rem; font-size: 0.56rem; font-weight: 700; letter-spacing: 0.22em; color: rgba(246,237,219,0.34); }
.title-footer-mid { color: rgba(228,191,120,0.5); }
.title-aside { position: absolute; right: clamp(1.5rem, 5vw, 5rem); bottom: 18%; z-index: 3; max-width: 260px; text-align: right; animation: fadeIn 1.4s 0.8s both; }
.title-aside .aside-line { display: block; width: 80px; height: 1px; margin-left: auto; margin-bottom: 0.8rem; background: linear-gradient(90deg, transparent, var(--gold)); }
.title-aside p { font-family: var(--serif); font-style: italic; font-size: clamp(0.95rem, 1.4vw, 1.2rem); line-height: 1.5; color: rgba(246,237,219,0.78); }
.title-aside small { display: block; margin-top: 0.6rem; font-size: 0.64rem; letter-spacing: 0.12em; color: var(--gold); }

/* ---------- Creator ---------- */
.creator-screen { flex-direction: column; background: radial-gradient(ellipse at 73% 38%, rgba(40,59,68,0.35), transparent 45%), linear-gradient(110deg, rgba(5,9,13,0.97) 0%, rgba(5,9,13,0.91) 52%, rgba(5,9,13,0.68) 100%); backdrop-filter: blur(8px); padding: clamp(1rem, 2.4vw, 2.2rem) clamp(1.2rem, 4vw, 4.5rem); overflow: hidden; }
.creator-head { display: flex; justify-content: space-between; align-items: flex-start; flex: 0 0 auto; }
.creator-head h2 { font-family: var(--serif); font-size: clamp(1.5rem, 2.6vw, 2.5rem); font-weight: 700; margin-top: 0.25rem; }
.ghost-btn { border: 1px solid rgba(228,191,120,0.24); padding: 0.55rem 1rem; font-size: 0.76rem; letter-spacing: 0.08em; color: var(--muted); background: rgba(255,255,255,0.02); transition: 0.2s; }
.ghost-btn:hover { color: var(--gold-bright); border-color: var(--gold); }
.creator-grid { flex: 1 1 auto; min-height: 0; display: grid; grid-template-columns: minmax(0, 1.15fr) minmax(300px, 0.85fr); gap: clamp(1.2rem, 3vw, 3.5rem); margin-top: clamp(0.8rem, 1.8vh, 1.5rem); }
.creator-form { overflow-y: auto; padding-right: 1rem; scrollbar-width: thin; scrollbar-color: rgba(228,191,120,0.3) transparent; }
.creator-form::-webkit-scrollbar { width: 4px; }
.creator-form::-webkit-scrollbar-thumb { background: rgba(228,191,120,0.3); }
.form-section { padding: 0.9rem 0; border-top: 1px solid rgba(228,191,120,0.1); }
.form-section:first-child { border-top: 0; padding-top: 0; }
.field-label { display: block; font-size: 0.64rem; font-weight: 700; letter-spacing: 0.22em; color: var(--gold); text-transform: uppercase; margin-bottom: 0.65rem; }
.name-input { width: 100%; max-width: 420px; padding: 0.55rem 0.7rem; font-family: var(--serif); font-size: 1.35rem; letter-spacing: 0.06em; color: var(--cream); background: rgba(255,255,255,0.035); border: 0; border-bottom: 1px solid rgba(228,191,120,0.45); outline: none; }
.name-input:focus { border-color: var(--gold-bright); background: rgba(228,191,120,0.04); }
.origin-list { display: grid; grid-template-columns: repeat(3, 1fr); gap: 0.55rem; }
.origin-card { position: relative; padding: 0.7rem 0.75rem; text-align: left; border: 1px solid rgba(255,255,255,0.1); background: rgba(255,255,255,0.02); transition: 0.2s; min-height: 80px; }
.origin-card:hover { border-color: rgba(228,191,120,0.4); background: rgba(228,191,120,0.05); }
.origin-card.is-selected { border-color: var(--gold); background: linear-gradient(135deg, rgba(228,191,120,0.14), rgba(228,191,120,0.02)); box-shadow: inset 0 0 24px rgba(228,191,120,0.04); }
.origin-card .origin-glyph { font-size: 1.05rem; color: var(--gold); display: block; margin-bottom: 0.2rem; }
.origin-card b { display: block; font-family: var(--serif); font-size: 0.8rem; line-height: 1.2; }
.origin-card small { display: block; color: var(--muted); font-size: 0.63rem; margin-top: 0.25rem; line-height: 1.25; }
.appearance-section { display: grid; gap: 0.55rem; }
.appearance-row { display: flex; align-items: center; gap: 1rem; min-height: 30px; }
.appearance-label { flex: 0 0 72px; font-size: 0.72rem; color: var(--muted); letter-spacing: 0.05em; }
.chip-list { display: flex; gap: 0.35rem; flex-wrap: wrap; }
.chip { padding: 0.26rem 0.62rem; border: 1px solid rgba(255,255,255,0.11); background: rgba(255,255,255,0.025); font-size: 0.7rem; color: var(--muted); transition: 0.15s; }
.chip:hover { border-color: rgba(228,191,120,0.4); color: var(--cream); }
.chip.is-selected { border-color: var(--gold); color: var(--gold-bright); background: rgba(228,191,120,0.1); }
.swatch-list { display: flex; gap: 0.4rem; }
.swatch { width: 21px; height: 21px; border-radius: 50%; border: 2px solid rgba(255,255,255,0.12); box-shadow: inset 0 0 0 2px rgba(0,0,0,0.25); transition: 0.15s; }
.swatch:hover { transform: scale(1.12); }
.swatch.is-selected { border-color: var(--gold-bright); box-shadow: 0 0 0 2px rgba(228,191,120,0.25), inset 0 0 0 2px rgba(0,0,0,0.2); }
.attr-head { display: flex; align-items: center; justify-content: space-between; }
.attr-head .field-label { margin: 0; }
.points-left { font-size: 0.7rem; color: var(--cyan); }
.attribute-list { display: grid; grid-template-columns: 1fr 1fr; gap: 0.24rem 1.3rem; margin-top: 0.6rem; }
.attr-row { display: flex; align-items: center; gap: 0.45rem; padding: 0.18rem 0; border-bottom: 1px solid rgba(255,255,255,0.04); }
.attr-name { flex: 1; font-size: 0.76rem; color: var(--muted); }
.attr-name small { color: rgba(146,231,223,0.65); font-size: 0.58rem; margin-left: 0.3rem; }
.attr-value { width: 1.3rem; text-align: center; font-family: var(--serif); font-size: 0.92rem; color: var(--cream); }
.attr-btn { width: 20px; height: 20px; border: 1px solid rgba(255,255,255,0.15); font-size: 0.8rem; line-height: 1; color: var(--muted); display: grid; place-items: center; }
.attr-btn:hover:not(:disabled) { border-color: var(--gold); color: var(--gold-bright); }
.attr-btn:disabled { opacity: 0.22; cursor: default; }
.creator-preview { display: flex; flex-direction: column; min-height: 0; }
.preview-stage { position: relative; flex: 1 1 auto; min-height: 210px; display: flex; align-items: center; justify-content: center; overflow: hidden; border: 1px solid rgba(228,191,120,0.12); background: radial-gradient(ellipse at 50% 62%, rgba(74,111,108,0.28), transparent 55%), linear-gradient(180deg, rgba(10,18,24,0.4), rgba(5,8,12,0.7)); }
#creator-canvas { position: relative; z-index: 2; width: 100%; height: 100%; object-fit: contain; }
.preview-glow { position: absolute; z-index: 1; width: 55%; height: 14%; bottom: 10%; border-radius: 50%; background: rgba(228,191,120,0.12); filter: blur(22px); }
.preview-rune { position: absolute; z-index: 1; color: rgba(228,191,120,0.36); font-size: 0.8rem; animation: floatRune 5s ease-in-out infinite; }
.rune-one { top: 16%; left: 14%; }
.rune-two { top: 26%; right: 12%; animation-delay: -2.5s; }
@keyframes floatRune { 50% { transform: translateY(-10px); opacity: 0.65; } }
.preview-caption { position: absolute; z-index: 3; bottom: 0.55rem; left: 0; right: 0; text-align: center; font-size: 0.55rem; letter-spacing: 0.28em; color: rgba(228,191,120,0.6); }
.preview-card { padding: 0.8rem 0 0.7rem; }
.preview-title-row { display: flex; justify-content: space-between; align-items: flex-start; }
.preview-title-row span { font-size: 0.64rem; letter-spacing: 0.13em; color: var(--gold); text-transform: uppercase; }
.preview-title-row h3 { font-family: var(--serif); font-size: 1.45rem; font-weight: 700; margin-top: 0.08rem; }
.level-gem { display: grid; place-items: center; width: 40px; height: 40px; border: 1px solid rgba(228,191,120,0.45); color: var(--gold-bright); font-family: var(--serif); font-size: 0.72rem; transform: rotate(45deg); }
.level-gem > * { transform: rotate(-45deg); }
.derived-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 0.4rem; margin-top: 0.6rem; }
.derived-stat { border-left: 1px solid rgba(228,191,120,0.18); padding-left: 0.5rem; }
.derived-stat small { display: block; color: var(--muted); font-size: 0.56rem; letter-spacing: 0.06em; text-transform: uppercase; }
.derived-stat b { font-family: var(--serif); font-size: 0.9rem; color: var(--cream); font-weight: 700; }
.preview-perk { margin-top: 0.6rem; padding: 0.5rem 0.6rem; border: 1px solid rgba(146,231,223,0.14); background: rgba(146,231,223,0.035); font-size: 0.7rem; color: rgba(246,237,219,0.68); line-height: 1.35; }
.preview-perk b { color: var(--cyan); font-weight: 700; }
.forge-btn { position: relative; display: flex; flex-direction: column; align-items: center; justify-content: center; width: 100%; min-height: 58px; padding: 0.55rem 1rem; border: 1px solid rgba(228,191,120,0.6); background: linear-gradient(135deg, rgba(228,191,120,0.22), rgba(228,191,120,0.05)); overflow: hidden; transition: 0.25s; }
.forge-btn::before { content: ""; position: absolute; inset: 0; background: linear-gradient(100deg, transparent 20%, rgba(255,236,186,0.18) 50%, transparent 80%); transform: translateX(-120%); transition: transform 0.7s; }
.forge-btn:hover { background: linear-gradient(135deg, rgba(228,191,120,0.32), rgba(228,191,120,0.09)); box-shadow: 0 0 36px rgba(228,191,120,0.14); }
.forge-btn:hover::before { transform: translateX(120%); }
.forge-btn span { font-family: var(--serif); font-weight: 700; font-size: 0.9rem; letter-spacing: 0.14em; color: var(--gold-bright); }
.forge-btn small { font-size: 0.61rem; color: rgba(246,237,219,0.52); letter-spacing: 0.08em; margin-top: 0.12rem; }

/* ---------- Intro ---------- */
.intro-screen { align-items: center; justify-content: center; flex-direction: column; background: rgba(3,5,8,0.3); }
.intro-bars span { position: absolute; left: 0; right: 0; height: 10vh; background: #05070a; z-index: 2; }
.intro-bars span:first-child { top: 0; }
.intro-bars span:last-child { bottom: 0; }
.intro-content { position: relative; z-index: 3; max-width: min(780px, 82vw); text-align: center; animation: introReveal 1.1s ease both; }
.intro-content .eyebrow { margin-bottom: 1rem; }
.intro-content h2 { font-family: var(--serif); font-size: clamp(2rem, 4.2vw, 4rem); line-height: 1.06; font-weight: 700; text-shadow: 0 10px 60px rgba(0,0,0,0.8); }
.intro-content p { margin-top: 1rem; font-size: clamp(1rem, 1.4vw, 1.25rem); color: rgba(246,237,219,0.72); line-height: 1.6; }
.intro-content p.intro-em { color: var(--gold-bright); font-family: var(--serif); font-style: italic; }
.intro-progress { display: flex; gap: 0.4rem; justify-content: center; margin-top: 2.2rem; }
.intro-progress i { width: 28px; height: 1px; background: rgba(255,255,255,0.18); transition: 0.4s; }
.intro-progress i.is-on { background: var(--gold); box-shadow: 0 0 10px var(--gold); }
.intro-next { position: absolute; z-index: 4; right: clamp(1.5rem, 5vw, 5rem); bottom: 13vh; font-size: 0.7rem; letter-spacing: 0.2em; color: var(--gold); }
.intro-next span { font-size: 1.2rem; margin-left: 0.5rem; }
.intro-skip { position: absolute; z-index: 4; right: clamp(1.5rem, 5vw, 5rem); top: 13vh; font-size: 0.63rem; letter-spacing: 0.12em; color: rgba(246,237,219,0.38); border-bottom: 1px solid rgba(255,255,255,0.16); padding-bottom: 0.15rem; }
@keyframes introReveal { from { opacity: 0; transform: translateY(16px); } to { opacity: 1; transform: none; } }

/* ---------- HUD ---------- */
.hud { position: absolute; inset: 0; z-index: 10; pointer-events: none; opacity: 0; transition: opacity 0.7s ease; }
body.is-playing .hud { opacity: 1; }
body.is-menu .hud, body.is-dialogue .hud { opacity: 0.18; }
.hud-top-left { position: absolute; top: max(1rem, env(safe-area-inset-top)); left: max(1.2rem, env(safe-area-inset-left)); display: flex; flex-direction: column; gap: 0.7rem; width: min(330px, 27vw); }
.player-plate { display: flex; gap: 0.7rem; align-items: center; }
.portrait-medallion { position: relative; flex: 0 0 auto; width: 54px; height: 54px; border-radius: 50%; border: 1px solid rgba(228,191,120,0.55); padding: 3px; background: rgba(5,8,12,0.8); box-shadow: 0 0 24px rgba(228,191,120,0.08); }
.hud-portrait { width: 100%; height: 100%; border-radius: 50%; overflow: hidden; background: radial-gradient(circle at 50% 35%, #334957, #101821); }
.hud-portrait svg { width: 100%; height: 100%; }
.hud-level { position: absolute; right: -6px; bottom: -4px; display: grid; place-items: center; width: 22px; height: 22px; border-radius: 50%; background: var(--gold); color: #1a1308; font-size: 0.65rem; font-weight: 700; border: 2px solid #0b1016; }
.player-vitals { flex: 1; min-width: 0; }
.player-name-row { display: flex; align-items: baseline; justify-content: space-between; gap: 0.5rem; margin-bottom: 0.22rem; }
.player-name-row strong { font-family: var(--serif); font-size: 0.95rem; font-weight: 700; letter-spacing: 0.03em; text-shadow: 0 2px 8px #000; }
.player-name-row span { font-size: 0.55rem; color: var(--gold); letter-spacing: 0.09em; text-transform: uppercase; opacity: 0.8; }
.bar { position: relative; height: 10px; background: rgba(2,5,8,0.72); border: 1px solid rgba(255,255,255,0.1); overflow: hidden; }
.bar i { position: absolute; inset: 0 auto 0 0; display: block; width: 100%; transition: width 0.22s ease; }
.hp-bar { height: 14px; border-color: rgba(228,191,120,0.25); }
.hp-bar i { background: linear-gradient(90deg, #8d2f2c, #dc5b4e 65%, #f08c75); box-shadow: inset 0 1px rgba(255,255,255,0.25); }
.hp-bar span { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; font-size: 0.55rem; font-weight: 700; letter-spacing: 0.05em; text-shadow: 0 1px 3px #000; }
.bar-row { display: flex; gap: 0.3rem; margin-top: 0.25rem; }
.bar-row .bar { flex: 1; height: 4px; border: 0; }
.stamina-bar i { background: linear-gradient(90deg, #6d9c52, #b4dc77); }
.mana-bar i { background: linear-gradient(90deg, #347c9e, #80d4e6); }
.xp-bar { position: relative; height: 3px; margin-top: 0.3rem; background: rgba(255,255,255,0.06); overflow: hidden; }
.xp-bar i { display: block; height: 100%; width: 0%; background: linear-gradient(90deg, var(--gold-deep), var(--gold-bright)); }
.xp-bar span { display: none; }
.quest-card { padding: 0.6rem 0.7rem; border-left: 2px solid var(--gold); background: linear-gradient(90deg, rgba(6,10,15,0.78), rgba(6,10,15,0.2)); backdrop-filter: blur(5px); }
.quest-eyebrow { font-size: 0.52rem; font-weight: 700; letter-spacing: 0.2em; color: var(--gold); }
.quest-card p { font-family: var(--serif); font-size: 0.82rem; font-weight: 700; margin-top: 0.2rem; }
.quest-card small { display: block; color: rgba(246,237,219,0.62); font-size: 0.68rem; line-height: 1.35; margin-top: 0.15rem; }
.quest-progress { height: 2px; margin-top: 0.45rem; background: rgba(255,255,255,0.08); }
.quest-progress i { display: block; width: 0%; height: 100%; background: var(--gold); transition: width 0.4s; }
.compass-wrap { position: absolute; top: max(1rem, env(safe-area-inset-top)); left: 50%; transform: translateX(-50%); width: 260px; display: flex; flex-direction: column; align-items: center; }
.compass { position: relative; width: 100%; display: flex; justify-content: space-between; font-family: var(--serif); font-size: 0.52rem; letter-spacing: 0.06em; color: rgba(246,237,219,0.44); padding: 0 0.2rem; }
.compass span:nth-child(3) { color: var(--gold-bright); font-size: 0.66rem; }
.compass::after { content: ""; position: absolute; left: 0; right: 0; bottom: -5px; height: 1px; background: linear-gradient(90deg, transparent, rgba(228,191,120,0.4), transparent); }
.compass-pointer { width: 0; height: 0; margin-top: 7px; border-left: 4px solid transparent; border-right: 4px solid transparent; border-top: 5px solid var(--gold); filter: drop-shadow(0 0 4px var(--gold)); }
.hud-top-right { position: absolute; top: max(1rem, env(safe-area-inset-top)); right: max(1.2rem, env(safe-area-inset-right)); display: flex; flex-direction: column; align-items: flex-end; gap: 0.45rem; width: min(180px, 16vw); }
.region-chip { display: flex; align-items: center; gap: 0.45rem; text-align: right; }
.region-dot { width: 5px; height: 5px; border-radius: 50%; background: var(--gold); box-shadow: 0 0 9px var(--gold); }
.region-chip strong { display: block; font-family: var(--serif); font-size: 0.72rem; letter-spacing: 0.12em; }
.region-chip small { display: block; font-size: 0.57rem; color: var(--muted); letter-spacing: 0.03em; }
.minimap-frame { position: relative; width: 128px; height: 128px; border-radius: 50%; border: 1px solid rgba(228,191,120,0.38); overflow: hidden; background: rgba(5,8,12,0.72); box-shadow: 0 0 0 5px rgba(4,7,10,0.25), 0 12px 36px rgba(0,0,0,0.3); }
#minimap { width: 100%; height: 100%; display: block; }
.minimap-ring { position: absolute; inset: 7px; border: 1px solid rgba(228,191,120,0.16); border-radius: 50%; pointer-events: none; }
.minimap-ring::before, .minimap-ring::after { content: ""; position: absolute; background: rgba(228,191,120,0.14); }
.minimap-ring::before { left: 50%; top: 0; bottom: 0; width: 1px; }
.minimap-ring::after { top: 50%; left: 0; right: 0; height: 1px; }
.minimap-n { position: absolute; top: 3px; left: 50%; transform: translateX(-50%); font-family: var(--serif); font-size: 0.5rem; color: var(--gold); }
.minimap-label { text-align: right; font-size: 0.54rem; letter-spacing: 0.08em; color: rgba(246,237,219,0.45); }
.clock-chip { display: flex; gap: 0.4rem; align-items: center; font-size: 0.58rem; letter-spacing: 0.08em; color: var(--muted); }
.clock-chip span:first-child { color: var(--gold); }
.target-wrap { position: absolute; top: max(4.4rem, calc(env(safe-area-inset-top) + 4rem)); left: 50%; transform: translateX(-50%); width: min(280px, 30vw); opacity: 0; transition: opacity 0.2s; }
.target-wrap.is-visible { opacity: 1; }
.target-name-row { display: flex; align-items: baseline; justify-content: center; gap: 0.4rem; font-size: 0.62rem; }
.target-name-row span { color: var(--muted); font-size: 0.53rem; letter-spacing: 0.08em; }
.target-name-row strong { font-family: var(--serif); font-size: 0.75rem; font-weight: 700; }
.target-bar { height: 4px; margin-top: 0.28rem; background: rgba(2,4,7,0.7); border: 1px solid rgba(255,255,255,0.08); }
.target-bar i { display: block; height: 100%; width: 100%; background: linear-gradient(90deg, #8c302e, #df6252); transition: width 0.15s; }
.boss-wrap { position: absolute; top: max(4.4rem, calc(env(safe-area-inset-top) + 4rem)); left: 50%; transform: translateX(-50%); width: min(520px, 52vw); text-align: center; opacity: 0; pointer-events: none; transition: opacity 0.5s; }
.boss-wrap.is-visible { opacity: 1; }
.boss-title span { font-size: 0.52rem; letter-spacing: 0.28em; color: var(--gold); }
.boss-title h3 { font-family: var(--serif); font-size: clamp(1rem, 1.7vw, 1.5rem); font-weight: 700; letter-spacing: 0.05em; margin-top: 0.1rem; text-shadow: 0 3px 18px #000; }
.boss-bar { position: relative; height: 8px; margin-top: 0.4rem; background: rgba(2,4,7,0.75); border: 1px solid rgba(228,191,120,0.28); overflow: hidden; }
.boss-bar i { display: block; width: 100%; height: 100%; background: linear-gradient(90deg, #6f1f22, #c9463e 60%, #ef8a67); box-shadow: inset 0 1px rgba(255,255,255,0.2); transition: width 0.18s; }
.boss-bar b { position: absolute; top: -1px; height: 8px; width: 1px; background: rgba(255,236,186,0.7); left: 50%; }
.boss-cast { margin-top: 0.3rem; font-size: 0.62rem; letter-spacing: 0.16em; color: #ffb18b; opacity: 0; }
.boss-cast.is-visible { opacity: 1; animation: castPulse 0.8s ease-in-out infinite; }
@keyframes castPulse { 50% { opacity: 0.55; } }
.hud-bottom-left { position: absolute; left: max(1.2rem, env(safe-area-inset-left)); bottom: max(1.1rem, env(safe-area-inset-bottom)); display: flex; flex-direction: column; gap: 0.4rem; width: min(290px, 24vw); }
.companion-card { display: flex; align-items: center; gap: 0.55rem; padding: 0.5rem 0.6rem; border: 1px solid rgba(146,231,223,0.16); background: linear-gradient(90deg, rgba(8,15,20,0.8), rgba(8,15,20,0.3)); position: relative; overflow: hidden; }
.companion-card.is-empty { opacity: 0.55; }
.companion-orb { flex: 0 0 auto; display: grid; place-items: center; width: 30px; height: 30px; border-radius: 50%; border: 1px solid rgba(146,231,223,0.4); color: var(--cyan); font-size: 0.85rem; box-shadow: inset 0 0 12px rgba(146,231,223,0.12); }
.companion-card span { display: block; font-size: 0.48rem; letter-spacing: 0.14em; color: var(--cyan); opacity: 0.8; }
.companion-card strong { display: block; font-family: var(--serif); font-size: 0.74rem; margin-top: 0.06rem; }
.companion-card small { display: block; font-size: 0.56rem; color: var(--muted); margin-top: 0.05rem; }
.companion-cooldown { position: absolute; bottom: 0; left: 0; height: 2px; width: 0%; background: var(--cyan); transition: width 0.2s; }
.potion-chip { display: flex; align-items: center; gap: 0.5rem; padding: 0.35rem 0.55rem; width: fit-content; background: rgba(5,9,13,0.5); border-left: 1px solid rgba(228,191,120,0.3); }
.potion-icon { color: var(--gold); font-size: 0.85rem; }
.potion-chip strong { display: block; font-size: 0.64rem; letter-spacing: 0.04em; }
.potion-chip small { display: block; font-size: 0.52rem; color: var(--muted); }
.hud-bottom-right { position: absolute; right: max(1.2rem, env(safe-area-inset-right)); bottom: max(1.1rem, env(safe-area-inset-bottom)); }
.ability-cluster { display: flex; align-items: flex-end; gap: 0.35rem; }
.ability-btn { pointer-events: auto; display: flex; flex-direction: column; align-items: center; justify-content: center; width: 48px; height: 48px; border-radius: 50%; border: 1px solid rgba(228,191,120,0.3); background: radial-gradient(circle at 40% 30%, rgba(35,44,50,0.95), rgba(6,10,14,0.9)); box-shadow: 0 4px 20px rgba(0,0,0,0.35), inset 0 0 16px rgba(255,255,255,0.03); transition: 0.16s; }
.ability-btn:hover { border-color: var(--gold); transform: translateY(-2px); }
.ability-btn:active { transform: scale(0.94); }
.ability-btn small { display: none; }
.ability-icon { font-size: 1rem; color: var(--gold-bright); line-height: 1; }
.attack-btn { width: 60px; height: 60px; border-color: rgba(228,191,120,0.6); }
.attack-btn .ability-icon { font-size: 1.35rem; }
.resonance-btn { border-color: rgba(146,231,223,0.45); }
.resonance-btn .ability-icon { color: var(--cyan); }
.companion-btn { border-color: rgba(188,163,238,0.4); }
.companion-btn .ability-icon { color: var(--violet); }
.ability-btn.is-disabled { opacity: 0.3; }
.interact-prompt { position: absolute; left: 50%; bottom: 18%; transform: translate(-50%, 12px); display: flex; align-items: center; gap: 0.5rem; padding: 0.38rem 0.7rem; background: rgba(4,7,10,0.82); border: 1px solid rgba(228,191,120,0.36); font-size: 0.72rem; letter-spacing: 0.04em; opacity: 0; transition: 0.2s; backdrop-filter: blur(6px); }
.interact-prompt.is-visible { opacity: 1; transform: translate(-50%, 0); }
.resonance-ring { position: absolute; left: 50%; top: 50%; width: 108px; height: 108px; transform: translate(-50%, -50%); opacity: 0; pointer-events: none; transition: opacity 0.2s; }
.resonance-ring.is-visible { opacity: 1; }
.resonance-ring svg { width: 100%; height: 100%; transform: rotate(-90deg); }
.resonance-ring circle { fill: none; stroke-width: 2.2; }
.resonance-track { stroke: rgba(146,231,223,0.16); }
.resonance-fill { stroke: var(--cyan); stroke-linecap: round; stroke-dasharray: 276.46; stroke-dashoffset: 276.46; filter: drop-shadow(0 0 6px var(--cyan)); transition: stroke-dashoffset 0.08s linear; }
.resonance-ring span { position: absolute; inset: 0; display: grid; place-items: center; font-size: 0.5rem; letter-spacing: 0.16em; color: var(--cyan); }
.subtitle { position: absolute; left: 50%; bottom: 12%; transform: translateX(-50%); width: min(720px, 72vw); text-align: center; font-size: 0.9rem; line-height: 1.4; text-shadow: 0 2px 8px #000; color: rgba(255,247,231,0.9); opacity: 0; transition: opacity 0.2s; }
.subtitle.is-visible { opacity: 1; }
.damage-layer { position: absolute; inset: 0; overflow: hidden; }
.damage-number { position: absolute; font-family: var(--serif); font-weight: 700; font-size: 1.05rem; color: #ffd9a0; text-shadow: 0 2px 6px #000; animation: dmgFloat 0.9s ease-out forwards; pointer-events: none; }
.damage-number.crit { color: #ffb24d; font-size: 1.5rem; }
.damage-number.heal { color: #9ce7ac; }
.damage-number.player { color: #ff7d72; }
@keyframes dmgFloat { 0% { opacity: 0; transform: translate(-50%, 0) scale(0.7); } 18% { opacity: 1; transform: translate(-50%, -12px) scale(1.08); } 100% { opacity: 0; transform: translate(-50%, -56px) scale(0.92); } }
.controls-hint { position: absolute; left: 50%; bottom: 0.55rem; transform: translateX(-50%); display: flex; gap: 0.85rem; font-size: 0.55rem; color: rgba(246,237,219,0.32); letter-spacing: 0.04em; white-space: nowrap; }
.controls-hint span { display: flex; gap: 0.25rem; align-items: center; }
.controls-hint kbd { font-size: 0.5rem; min-width: 1.4em; min-height: 1.4em; opacity: 0.7; }
.toast-layer { position: absolute; top: 22%; right: 1.5rem; display: flex; flex-direction: column; gap: 0.45rem; align-items: flex-end; }
.toast { min-width: 240px; max-width: 320px; padding: 0.6rem 0.75rem; border-left: 2px solid var(--gold); background: linear-gradient(90deg, rgba(7,11,16,0.95), rgba(7,11,16,0.55)); backdrop-filter: blur(8px); animation: toastIn 0.35s ease both; }
.toast.is-out { animation: toastOut 0.4s ease forwards; }
.toast span { display: block; font-size: 0.5rem; letter-spacing: 0.2em; color: var(--gold); }
.toast strong { display: block; font-family: var(--serif); font-size: 0.82rem; margin-top: 0.08rem; }
.toast small { display: block; font-size: 0.62rem; color: var(--muted); margin-top: 0.08rem; line-height: 1.3; }
@keyframes toastIn { from { opacity: 0; transform: translateX(18px); } }
@keyframes toastOut { to { opacity: 0; transform: translateX(18px); } }
.region-banner { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; background: radial-gradient(ellipse at center, rgba(4,7,10,0.7), rgba(4,7,10,0.3) 45%, transparent 70%); opacity: 0; pointer-events: none; }
.region-banner.is-visible { animation: regionReveal 4.5s ease both; }
.region-banner span { font-size: 0.58rem; letter-spacing: 0.36em; color: var(--gold); }
.region-banner h2 { font-family: var(--serif); font-size: clamp(2.5rem, 5.5vw, 5rem); font-weight: 900; letter-spacing: 0.1em; margin: 0.3rem 0 0.2rem; text-shadow: 0 10px 50px #000; }
.region-banner p { font-family: var(--serif); font-style: italic; color: rgba(246,237,219,0.72); font-size: 0.95rem; letter-spacing: 0.08em; }
@keyframes regionReveal { 0% { opacity: 0; transform: scale(1.03); } 14%, 72% { opacity: 1; transform: none; } 100% { opacity: 0; } }

/* ---------- Dialogue ---------- */
.dialogue-screen { align-items: flex-end; justify-content: center; padding: 0 5vw 5vh; background: linear-gradient(0deg, rgba(2,4,6,0.72), transparent 45%); }
.dialogue-screen::before { content: ""; position: absolute; inset: 0; background: linear-gradient(180deg, transparent 55%, rgba(2,4,6,0.75)); pointer-events: none; }
.dialogue-box { position: relative; z-index: 2; display: flex; gap: 1.1rem; width: min(1000px, 88vw); padding: 1.1rem 1.2rem; border: 1px solid rgba(228,191,120,0.3); background: linear-gradient(110deg, rgba(9,13,19,0.97), rgba(9,13,19,0.86)); box-shadow: var(--shadow); backdrop-filter: blur(12px); animation: dialogueIn 0.35s ease both; }
.dialogue-box::before { content: ""; position: absolute; inset: 5px; border: 1px solid rgba(228,191,120,0.08); pointer-events: none; }
@keyframes dialogueIn { from { opacity: 0; transform: translateY(12px); } }
.dialogue-portrait { flex: 0 0 auto; width: 116px; height: 116px; border: 1px solid rgba(228,191,120,0.35); background: radial-gradient(circle at 50% 35%, #2a3a40, #0b1116); overflow: hidden; }
.dialogue-portrait svg { width: 100%; height: 100%; }
.dialogue-copy { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.dialogue-name-row { display: flex; align-items: baseline; gap: 0.65rem; }
.dialogue-name-row h3 { font-family: var(--serif); font-size: 1.05rem; font-weight: 700; color: var(--gold-bright); }
.dialogue-name-row span { font-size: 0.58rem; letter-spacing: 0.14em; color: var(--muted); text-transform: uppercase; }
.dialogue-copy > p { margin-top: 0.45rem; font-size: clamp(0.9rem, 1.2vw, 1.08rem); line-height: 1.48; color: rgba(246,237,219,0.9); min-height: 3.5em; }
.dialogue-choices { display: flex; flex-direction: column; gap: 0.3rem; margin-top: 0.55rem; }
.dialogue-choice { align-self: flex-start; text-align: left; font-size: 0.78rem; color: var(--cream); padding: 0.3rem 0.6rem; border-left: 1px solid rgba(228,191,120,0.35); background: rgba(228,191,120,0.05); transition: 0.15s; }
.dialogue-choice:hover { border-left-color: var(--gold-bright); background: rgba(228,191,120,0.13); transform: translateX(3px); }
.dialogue-next { align-self: flex-end; margin-top: 0.3rem; font-size: 0.6rem; letter-spacing: 0.16em; color: var(--gold); opacity: 0; }
.dialogue-next.is-visible { opacity: 1; animation: nextBlink 1.4s ease-in-out infinite; }
.dialogue-next i { font-style: normal; font-size: 1rem; }
@keyframes nextBlink { 50% { opacity: 0.45; } }

/* ---------- Menu ---------- */
.menu-screen { background: rgba(3,6,9,0.72); backdrop-filter: blur(12px); align-items: center; justify-content: center; padding: clamp(0.8rem, 2.5vw, 2rem); }
.menu-shell { width: min(1120px, 94vw); height: min(760px, 92vh); display: flex; flex-direction: column; border: 1px solid rgba(228,191,120,0.28); background: linear-gradient(135deg, rgba(10,15,21,0.97), rgba(6,10,14,0.98)); box-shadow: var(--shadow); }
.menu-head { display: flex; justify-content: space-between; align-items: flex-start; padding: 1rem 1.3rem 0.7rem; border-bottom: 1px solid rgba(228,191,120,0.1); }
.menu-head h2 { font-family: var(--serif); font-size: clamp(1.3rem, 2.3vw, 2rem); font-weight: 700; margin-top: 0.1rem; }
.menu-head > div > span { font-size: 0.68rem; color: var(--muted); }
.close-btn { width: 32px; height: 32px; border: 1px solid rgba(255,255,255,0.14); color: var(--muted); display: grid; place-items: center; transition: 0.18s; }
.close-btn:hover { border-color: var(--gold); color: var(--gold-bright); }
.menu-tabs { display: flex; gap: 0; padding: 0 1.3rem; border-bottom: 1px solid rgba(255,255,255,0.07); overflow-x: auto; scrollbar-width: none; }
.menu-tabs::-webkit-scrollbar { display: none; }
.menu-tabs button { flex: 0 0 auto; padding: 0.65rem 0.9rem; font-size: 0.7rem; letter-spacing: 0.08em; color: var(--muted); border-bottom: 2px solid transparent; transition: 0.16s; }
.menu-tabs button:hover { color: var(--cream); }
.menu-tabs button.is-active { color: var(--gold-bright); border-bottom-color: var(--gold); }
.menu-content { flex: 1; min-height: 0; overflow-y: auto; padding: 1rem 1.3rem; scrollbar-width: thin; scrollbar-color: rgba(228,191,120,0.3) transparent; }
.menu-content::-webkit-scrollbar { width: 4px; }
.menu-content::-webkit-scrollbar-thumb { background: rgba(228,191,120,0.3); }
.menu-footer { display: flex; justify-content: space-between; padding: 0.55rem 1.3rem; border-top: 1px solid rgba(255,255,255,0.07); font-size: 0.58rem; color: var(--muted); letter-spacing: 0.06em; }
.menu-grid { display: grid; grid-template-columns: 1.15fr 0.85fr; gap: 1rem; }
.menu-panel { border: 1px solid rgba(255,255,255,0.07); background: rgba(255,255,255,0.018); padding: 0.8rem; }
.menu-panel h3 { font-family: var(--serif); font-size: 0.85rem; color: var(--gold); font-weight: 700; margin-bottom: 0.6rem; letter-spacing: 0.06em; }
.stat-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 0.35rem 1rem; }
.stat-line { display: flex; justify-content: space-between; padding: 0.22rem 0; border-bottom: 1px solid rgba(255,255,255,0.045); font-size: 0.74rem; }
.stat-line span { color: var(--muted); }
.stat-line b { font-family: var(--serif); font-weight: 700; }
.derived-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 0.4rem; margin-top: 0.6rem; }
.derived-box { padding: 0.45rem; border: 1px solid rgba(228,191,120,0.1); background: rgba(228,191,120,0.025); }
.derived-box small { display: block; font-size: 0.52rem; color: var(--muted); text-transform: uppercase; letter-spacing: 0.06em; }
.derived-box b { font-family: var(--serif); font-size: 0.95rem; }
.equipment-slots { display: grid; grid-template-columns: repeat(3, 1fr); gap: 0.5rem; }
.equip-slot { min-height: 86px; padding: 0.5rem; border: 1px dashed rgba(228,191,120,0.18); background: rgba(255,255,255,0.015); }
.equip-slot span { display: block; font-size: 0.5rem; letter-spacing: 0.12em; color: var(--muted); text-transform: uppercase; }
.equip-slot b { display: block; font-family: var(--serif); font-size: 0.76rem; margin-top: 0.2rem; color: var(--gold-bright); }
.equip-slot small { display: block; font-size: 0.58rem; color: var(--muted); margin-top: 0.15rem; line-height: 1.3; }
.item-list { display: flex; flex-direction: column; gap: 0.35rem; }
.item-row { display: flex; align-items: center; gap: 0.6rem; padding: 0.5rem 0.6rem; border: 1px solid rgba(255,255,255,0.06); background: rgba(255,255,255,0.018); }
.item-icon { display: grid; place-items: center; width: 30px; height: 30px; border: 1px solid rgba(228,191,120,0.25); color: var(--gold); font-size: 0.8rem; }
.item-copy { flex: 1; }
.item-copy b { display: block; font-size: 0.74rem; font-family: var(--serif); }
.item-copy small { display: block; font-size: 0.58rem; color: var(--muted); line-height: 1.3; }
.item-action { padding: 0.25rem 0.55rem; border: 1px solid rgba(228,191,120,0.25); font-size: 0.58rem; letter-spacing: 0.06em; color: var(--gold); }
.item-action:hover { border-color: var(--gold); color: var(--gold-bright); }
.item-action:disabled { opacity: 0.35; }
.creature-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); gap: 0.6rem; }
.creature-card { position: relative; padding: 0.7rem; border: 1px solid rgba(146,231,223,0.15); background: linear-gradient(145deg, rgba(146,231,223,0.06), rgba(255,255,255,0.01)); overflow: hidden; }
.creature-card.is-locked { opacity: 0.35; filter: grayscale(1); }
.creature-glyph { display: grid; place-items: center; width: 42px; height: 42px; border-radius: 50%; border: 1px solid rgba(146,231,223,0.3); color: var(--cyan); font-size: 1.15rem; margin-bottom: 0.5rem; box-shadow: inset 0 0 18px rgba(146,231,223,0.08); }
.creature-card h4 { font-family: var(--serif); font-size: 0.85rem; }
.creature-card .creature-meta { font-size: 0.54rem; letter-spacing: 0.1em; color: var(--cyan); text-transform: uppercase; margin-top: 0.1rem; }
.creature-card p { font-size: 0.64rem; color: var(--muted); line-height: 1.35; margin-top: 0.35rem; }
.creature-card .creature-passive { margin-top: 0.35rem; padding-top: 0.35rem; border-top: 1px solid rgba(255,255,255,0.06); font-size: 0.58rem; color: rgba(246,237,219,0.68); }
.journal-list { display: flex; flex-direction: column; gap: 0.5rem; }
.journal-entry { padding: 0.6rem 0.7rem; border-left: 2px solid rgba(228,191,120,0.4); background: rgba(255,255,255,0.018); }
.journal-entry.is-done { border-left-color: var(--cyan-deep); opacity: 0.65; }
.journal-entry span { font-size: 0.5rem; letter-spacing: 0.16em; color: var(--gold); }
.journal-entry b { display: block; font-family: var(--serif); font-size: 0.8rem; margin-top: 0.1rem; }
.journal-entry p { font-size: 0.66rem; color: var(--muted); line-height: 1.4; margin-top: 0.2rem; }
.lore-list { display: grid; grid-template-columns: 1fr 1fr; gap: 0.4rem; }
.lore-entry { padding: 0.55rem 0.6rem; border: 1px solid rgba(255,255,255,0.06); background: rgba(255,255,255,0.018); }
.lore-entry span { font-size: 0.48rem; letter-spacing: 0.14em; color: var(--gold); }
.lore-entry b { display: block; font-family: var(--serif); font-size: 0.74rem; margin-top: 0.12rem; }
.lore-entry p { font-size: 0.6rem; color: var(--muted); line-height: 1.35; margin-top: 0.15rem; }
.map-wrap { position: relative; height: 100%; min-height: 420px; display: grid; place-items: center; }
#world-map { width: min(100%, 680px); aspect-ratio: 1; border: 1px solid rgba(228,191,120,0.2); background: #0b1117; }
.map-legend { display: flex; gap: 1rem; justify-content: center; margin-top: 0.6rem; font-size: 0.58rem; color: var(--muted); }
.map-legend span { display: flex; align-items: center; gap: 0.3rem; }
.map-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--gold); }
.map-dot.cyan { background: var(--cyan); }
.map-dot.red { background: var(--red); }
.settings-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 0.6rem 1.2rem; }
.setting-row { display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: 0.45rem 0; border-bottom: 1px solid rgba(255,255,255,0.05); }
.setting-row label { font-size: 0.72rem; color: var(--muted); }
.setting-row label small { display: block; font-size: 0.56rem; color: rgba(246,237,219,0.38); margin-top: 0.1rem; }
.toggle { position: relative; width: 34px; height: 18px; border: 1px solid rgba(255,255,255,0.16); background: rgba(255,255,255,0.04); border-radius: 20px; flex: 0 0 auto; }
.toggle::after { content: ""; position: absolute; width: 12px; height: 12px; left: 2px; top: 2px; border-radius: 50%; background: var(--muted); transition: 0.2s; }
.toggle.is-on { border-color: rgba(228,191,120,0.55); background: rgba(228,191,120,0.18); }
.toggle.is-on::after { left: 18px; background: var(--gold-bright); box-shadow: 0 0 8px var(--gold); }
.range-row { display: flex; align-items: center; gap: 0.5rem; }
input[type="range"] { width: 100px; accent-color: var(--gold); }
.setting-select { background: #0b1117; color: var(--cream); border: 1px solid rgba(228,191,120,0.22); padding: 0.25rem 0.4rem; font-size: 0.66rem; }

/* ---------- Modal ---------- */
.modal-screen { align-items: center; justify-content: center; background: rgba(3,6,9,0.8); backdrop-filter: blur(8px); }
.modal-card { position: relative; width: min(680px, 90vw); max-height: 82vh; overflow-y: auto; padding: 1.8rem; border: 1px solid rgba(228,191,120,0.32); background: linear-gradient(135deg, rgba(12,17,24,0.98), rgba(7,11,15,0.98)); box-shadow: var(--shadow); }
.modal-card .close-btn { position: absolute; top: 0.8rem; right: 0.8rem; }
.modal-card h2 { font-family: var(--serif); font-size: 1.7rem; margin: 0.2rem 0 0.8rem; }
.modal-card h3 { font-family: var(--serif); color: var(--gold); font-size: 1rem; margin: 1rem 0 0.3rem; }
.modal-card p { color: rgba(246,237,219,0.72); font-size: 0.8rem; line-height: 1.6; }
.modal-card .control-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 0.4rem 1rem; margin-top: 0.7rem; }
.modal-card .control-line { display: flex; justify-content: space-between; border-bottom: 1px solid rgba(255,255,255,0.06); padding: 0.3rem 0; font-size: 0.72rem; color: var(--muted); }
.credit-block { margin-top: 1rem; padding-top: 0.8rem; border-top: 1px solid rgba(228,191,120,0.14); }
.credit-block span { font-size: 0.55rem; letter-spacing: 0.18em; color: var(--gold); }
.credit-block b { display: block; font-family: var(--serif); font-size: 0.95rem; margin-top: 0.15rem; }

/* ---------- Ending ---------- */
.ending-screen { align-items: center; justify-content: center; background: radial-gradient(ellipse at center, rgba(9,15,21,0.72), rgba(3,6,9,0.94)); text-align: center; }
.ending-inner { max-width: 760px; padding: 2rem; }
.ending-inner h2 { font-family: var(--serif); font-size: clamp(2rem, 4vw, 3.8rem); line-height: 1.1; margin: 0.8rem 0 1.2rem; }
.ending-inner h2 em { font-style: italic; color: var(--gold-bright); }
.ending-inner > p { max-width: 560px; margin: 0 auto; color: rgba(246,237,219,0.68); line-height: 1.65; font-size: 0.95rem; }
