export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.started = false;
    this.mood = 'title';
    this.volumes = { master: 0.8, music: 0.55, sfx: 0.75 };
    this.nextChord = 0;
    this.nextMelody = 0;
    this.nextPulse = 0;
    this.chordIndex = 0;
    this.combat = false;
    this._muted = false;
    this._ambientTimer = 0;
    this._lastHurt = 0;
  }

  async init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') await this.ctx.resume();
      return;
    }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    this.ctx = new Ctx();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.volumes.master;
    this.master.connect(this.ctx.destination);
    const comp = this.ctx.createDynamicsCompressor();
    comp.threshold.value = -18;
    comp.knee.value = 18;
    comp.ratio.value = 3;
    comp.attack.value = 0.01;
    comp.release.value = 0.3;
    comp.connect(this.master);
    this.bus = comp;

    this.reverb = this.ctx.createConvolver();
    this.reverb.buffer = this.makeImpulse(3.2, 2.4);
    this.reverbGain = this.ctx.createGain();
    this.reverbGain.gain.value = 0.28;
    this.reverb.connect(this.reverbGain);
    this.reverbGain.connect(this.bus);

    this.music = this.ctx.createGain();
    this.music.gain.value = this.volumes.music;
    this.music.connect(this.bus);
    this.music.connect(this.reverb);

    this.sfx = this.ctx.createGain();
    this.sfx.gain.value = this.volumes.sfx;
    this.sfx.connect(this.bus);
    this.sfxReverb = this.ctx.createGain();
    this.sfxReverb.gain.value = 0.12;
    this.sfxReverb.connect(this.reverb);

    this.noise = this.makeNoise(2.0);
    this.started = true;
    this.nextChord = this.ctx.currentTime + 0.1;
    this.nextMelody = this.ctx.currentTime + 0.8;
    this.nextPulse = this.ctx.currentTime + 0.3;
    this.scheduleAmbient();
  }

  makeImpulse(seconds, decay) {
    const rate = this.ctx.sampleRate;
    const length = Math.floor(rate * seconds);
    const buffer = this.ctx.createBuffer(2, length, rate);
    for (let c = 0; c < 2; c++) {
      const data = buffer.getChannelData(c);
      for (let i = 0; i < length; i++) {
        data[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / length, decay) * (1 - Math.random() * 0.2);
      }
    }
    return buffer;
  }

  makeNoise(seconds) {
    const rate = this.ctx.sampleRate;
    const buffer = this.ctx.createBuffer(1, Math.floor(rate * seconds), rate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
    return buffer;
  }

  setVolume(kind, value) {
    this.volumes[kind] = value;
    if (!this.ctx) return;
    const target = kind === 'master' ? this.master : kind === 'music' ? this.music : this.sfx;
    target?.gain.setTargetAtTime(value, this.ctx.currentTime, 0.08);
  }

  setMood(mood) {
    if (!mood || this.mood === mood) return;
    this.mood = mood;
    this.combat = mood === 'combat' || mood === 'boss';
    this.chordIndex = 0;
    if (this.ctx) this.nextChord = this.ctx.currentTime + 0.1;
  }

  update(dt) {
    if (!this.started || !this.ctx) return;
    const now = this.ctx.currentTime;
    const prog = PROGRESSIONS[this.mood] || PROGRESSIONS.valdoria;
    const chordLen = this.mood === 'boss' ? 3.2 : this.mood === 'combat' ? 3.5 : 4.8;
    while (this.nextChord < now + 0.2) {
      const chord = prog[this.chordIndex % prog.length];
      this.playPad(chord, chordLen, this.nextChord);
      if (this.mood === 'boss') this.playBossOstinato(chord[0], this.nextChord, chordLen);
      this.chordIndex++;
      this.nextChord += chordLen;
    }
    const melodyGap = this.mood === 'combat' ? 0.62 : this.mood === 'boss' ? 0.5 : 1.35;
    while (this.nextMelody < now + 0.2) {
      if (Math.random() < (this.combat ? 0.72 : 0.58)) {
        const scale = SCALES[this.mood] || SCALES.valdoria;
        const note = scale[Math.floor(Math.random() * scale.length)];
        this.playPluck(note, this.nextMelody, this.combat ? 0.09 : 0.075);
      }
      this.nextMelody += melodyGap * (0.75 + Math.random() * 0.6);
    }
    if (this.combat) {
      while (this.nextPulse < now + 0.15) {
        this.playPulse(this.nextPulse, this.mood === 'boss' ? 0.16 : 0.1);
        this.nextPulse += this.mood === 'boss' ? 0.54 : 0.72;
      }
    }
    this._ambientTimer += dt;
    if (this._ambientTimer > 7) {
      this._ambientTimer = 0;
      this.playAmbient();
    }
  }

  scheduleAmbient() {
    if (!this.ctx) return;
    this.nextChord = this.ctx.currentTime + 0.1;
    this.nextMelody = this.ctx.currentTime + 1.0;
    this.nextPulse = this.ctx.currentTime + 0.5;
  }

  playPad(freqs, duration, time) {
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = this.mood === 'drakmore' ? 620 : this.mood === 'boss' ? 520 : 950;
    filter.Q.value = 0.5;
    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(0, time);
    gain.gain.linearRampToValueAtTime(this.mood === 'boss' ? 0.03 : 0.022, time + 0.9);
    gain.gain.setValueAtTime(this.mood === 'boss' ? 0.03 : 0.022, time + duration - 1.2);
    gain.gain.linearRampToValueAtTime(0, time + duration);
    filter.connect(gain);
    gain.connect(this.music);
    for (const f of freqs) {
      for (const detune of [-6, 5]) {
        const o = this.ctx.createOscillator();
        o.type = 'sawtooth';
        o.frequency.value = f;
        o.detune.value = detune;
        o.connect(filter);
        o.start(time);
        o.stop(time + duration + 0.1);
      }
    }
  }

  playPluck(freq, time, vol = 0.08) {
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    const f = this.ctx.createBiquadFilter();
    o.type = 'triangle';
    o.frequency.value = freq;
    f.type = 'lowpass';
    f.frequency.value = 2200;
    g.gain.setValueAtTime(0, time);
    g.gain.linearRampToValueAtTime(vol, time + 0.02);
    g.gain.exponentialRampToValueAtTime(0.0001, time + 1.4);
    o.connect(f); f.connect(g); g.connect(this.music);
    o.start(time); o.stop(time + 1.45);
  }

  playPulse(time, vol) {
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = 'sine';
    o.frequency.setValueAtTime(62, time);
    o.frequency.exponentialRampToValueAtTime(38, time + 0.18);
    g.gain.setValueAtTime(vol, time);
    g.gain.exponentialRampToValueAtTime(0.0001, time + 0.22);
    o.connect(g); g.connect(this.music);
    o.start(time); o.stop(time + 0.25);
  }

  playBossOstinato(root, time, duration) {
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0, time);
    g.gain.linearRampToValueAtTime(0.025, time + 0.2);
    g.gain.linearRampToValueAtTime(0, time + duration);
    g.connect(this.music);
    const o = this.ctx.createOscillator();
    o.type = 'sawtooth';
    o.frequency.value = root / 2;
    const f = this.ctx.createBiquadFilter();
    f.type = 'lowpass'; f.frequency.value = 180;
    o.connect(f); f.connect(g);
    o.start(time); o.stop(time + duration);
  }

  playAmbient() {
    if (!this.ctx || this.mood === 'boss') return;
    const now = this.ctx.currentTime;
    if (this.mood === 'drakmore') {
      this.noiseBurst(0.5, 180, 0.018, now, 'lowpass');
      return;
    }
    if (Math.random() < 0.65) {
      const base = this.mood === 'kansordore' ? 880 : 620;
      const o = this.ctx.createOscillator();
      const g = this.ctx.createGain();
      o.type = 'sine';
      o.frequency.setValueAtTime(base * (0.85 + Math.random() * 0.4), now);
      o.frequency.exponentialRampToValueAtTime(base * (1.2 + Math.random() * 0.3), now + 0.22);
      g.gain.setValueAtTime(0, now);
      g.gain.linearRampToValueAtTime(0.012, now + 0.04);
      g.gain.exponentialRampToValueAtTime(0.0001, now + 0.5);
      o.connect(g); g.connect(this.sfx);
      o.start(now); o.stop(now + 0.55);
    }
  }

  noiseBurst(duration, cutoff, vol, time, type = 'bandpass') {
    if (!this.ctx) return;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noise;
    src.playbackRate.value = 1;
    const f = this.ctx.createBiquadFilter();
    f.type = type; f.frequency.value = cutoff; f.Q.value = 0.8;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(vol, time);
    g.gain.exponentialRampToValueAtTime(0.0001, time + duration);
    src.connect(f); f.connect(g); g.connect(this.sfx);
    src.start(time, Math.random() * 0.5); src.stop(time + duration + 0.02);
  }

  tone(freq, duration, type, vol, when = 0, slide = 0, bus = this.sfx) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime + when;
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = type;
    o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), t + duration);
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(vol, t + 0.008);
    g.gain.exponentialRampToValueAtTime(0.0001, t + duration);
    o.connect(g); g.connect(bus);
    o.start(t); o.stop(t + duration + 0.02);
  }

  ui() { this.tone(740, 0.08, 'sine', 0.035); this.tone(1100, 0.07, 'sine', 0.018, 0.03); }
  confirm() { this.tone(440, 0.18, 'sine', 0.04); this.tone(660, 0.28, 'sine', 0.035, 0.08); this.tone(880, 0.35, 'sine', 0.025, 0.15); }
  swing() {
    if (!this.ctx) return;
    this.noiseBurst(0.18, 1700, 0.1, this.ctx.currentTime, 'highpass');
    this.tone(190, 0.12, 'sine', 0.025, 0, -70);
  }
  heavySwing() {
    if (!this.ctx) return;
    this.noiseBurst(0.32, 900, 0.13, this.ctx.currentTime, 'bandpass');
    this.tone(110, 0.3, 'sine', 0.045, 0, -50);
  }
  hit(crit = false) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    this.noiseBurst(0.1, 900, 0.08, t, 'bandpass');
    this.tone(crit ? 160 : 120, 0.16, 'square', crit ? 0.045 : 0.03, 0, -40);
    this.tone(crit ? 940 : 660, 0.12, 'triangle', 0.025, 0.01, -200);
  }
  hurt() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    if (now - this._lastHurt < 0.12) return;
    this._lastHurt = now;
    this.tone(85, 0.22, 'sawtooth', 0.06, 0, -30);
    this.noiseBurst(0.14, 420, 0.06, now, 'lowpass');
  }
  dodge() { this.noiseBurst(0.22, 1200, 0.06, this.ctx?.currentTime || 0, 'bandpass'); this.tone(300, 0.12, 'sine', 0.02, 0, 200); }
  block() { this.tone(260, 0.2, 'square', 0.04); this.tone(520, 0.25, 'triangle', 0.025, 0.01); }
  potion() { [523, 659, 784, 1046].forEach((f, i) => this.tone(f, 0.4, 'sine', 0.035, i * 0.06)); }
  capture() {
    if (!this.ctx) return;
    [392, 523, 659, 784, 1046].forEach((f, i) => this.tone(f, 0.9, 'sine', 0.035, i * 0.09));
    this.tone(1568, 1.2, 'sine', 0.018, 0.5);
  }
  quest() { [440, 554, 659, 880].forEach((f, i) => this.tone(f, 0.7, 'triangle', 0.04, i * 0.08)); }
  level() { [523, 659, 784, 1046, 1318].forEach((f, i) => this.tone(f, 1.2, 'sine', 0.045, i * 0.1)); }
  portal() {
    if (!this.ctx) return;
    this.tone(110, 1.2, 'sawtooth', 0.035, 0, 220);
    this.tone(220, 1.4, 'sine', 0.03, 0.1, 440);
    this.noiseBurst(1.2, 600, 0.04, this.ctx.currentTime, 'bandpass');
  }
  death() { this.tone(196, 1.4, 'sawtooth', 0.04, 0, -80); this.tone(98, 2.2, 'sine', 0.05, 0.1, -30); }
  bossRoar() {
    if (!this.ctx) return;
    this.tone(58, 1.4, 'sawtooth', 0.08, 0, -20);
    this.tone(87, 1.1, 'square', 0.04, 0.05, -30);
    this.noiseBurst(0.8, 250, 0.07, this.ctx.currentTime, 'lowpass');
  }
  arrow() { this.noiseBurst(0.16, 2400, 0.035, this.ctx?.currentTime || 0, 'highpass'); }
  chest() { this.tone(660, 0.25, 'triangle', 0.04); this.tone(990, 0.5, 'sine', 0.03, 0.1); }
}

import { clamp } from './utils.js';

export class Input {
  constructor(canvas) {
    this.canvas = canvas;
    this.keys = new Set();
    this.enabled = false;
    this.held = new Set();
    this.listeners = { action: [], camera: [], zoom: [], pause: [], any: [] };
    this.dragging = false;
    this.dragMoved = false;
    this.lastPointer = { x: 0, y: 0 };
    this.dragStart = { x: 0, y: 0 };
    this.joystick = { active: false, x: 0, y: 0, id: null };
    this.isTouch = matchMedia('(pointer: coarse)').matches || navigator.maxTouchPoints > 0;
    if (this.isTouch) document.body.classList.add('touch');
    this.bind();
  }

  on(type, fn) { this.listeners[type]?.push(fn); return this; }
  emit(type, ...args) { for (const fn of this.listeners[type] || []) fn(...args); }

  setEnabled(v) {
    this.enabled = v;
    if (!v) {
      this.held.clear();
      this.joystick.active = false;
      this.joystick.x = 0; this.joystick.y = 0;
      this.resetJoystickVisual();
    }
  }

  bind() {
    window.addEventListener('keydown', (e) => {
      if (['Tab', 'Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.code)) e.preventDefault();
      if (e.repeat) return;
      this.keys.add(e.code);
      this.emit('any', e.code);
      if (!this.enabled) {
        if (e.code === 'Escape') this.emit('pause');
        return;
      }
      const action = this.keyAction(e.code);
      if (action) {
        this.held.add(action);
        this.emit('action', action, 'down');
      }
      if (e.code === 'Tab' || e.code === 'Escape') this.emit('pause');
      if (e.code === 'KeyM') this.emit('action', 'map', 'down');
      if (e.code === 'KeyT') this.emit('action', 'lock', 'down');
    });
    window.addEventListener('keyup', (e) => {
      this.keys.delete(e.code);
      const action = this.keyAction(e.code);
      if (action) {
        this.held.delete(action);
        this.emit('action', action, 'up');
      }
    });
    window.addEventListener('blur', () => {
      this.keys.clear();
      this.held.clear();
    });

    this.canvas.addEventListener('pointerdown', (e) => {
      if (!this.enabled) return;
      if (e.pointerType === 'touch' && e.clientX < window.innerWidth * 0.36 && e.clientY > window.innerHeight * 0.55) return;
      if (e.button === 2) {
        this.held.add('block');
        this.emit('action', 'block', 'down');
        return;
      }
      if (e.button !== 0) return;
      this.dragging = true;
      this.dragMoved = false;
      this.lastPointer = { x: e.clientX, y: e.clientY };
      this.dragStart = { x: e.clientX, y: e.clientY };
      this.canvas.setPointerCapture?.(e.pointerId);
    });
    window.addEventListener('pointermove', (e) => {
      if (!this.dragging) return;
      const dx = e.clientX - this.lastPointer.x;
      const dy = e.clientY - this.lastPointer.y;
      this.lastPointer = { x: e.clientX, y: e.clientY };
      if (Math.hypot(e.clientX - this.dragStart.x, e.clientY - this.dragStart.y) > 5) this.dragMoved = true;
      if (this.dragMoved) this.emit('camera', dx, dy);
    });
    window.addEventListener('pointerup', (e) => {
      if (e.button === 2) {
        this.held.delete('block');
        this.emit('action', 'block', 'up');
      }
      if (!this.dragging) return;
      this.dragging = false;
      if (!this.dragMoved && this.enabled) this.emit('action', 'attack', 'down');
    });
    this.canvas.addEventListener('contextmenu', (e) => e.preventDefault());
    this.canvas.addEventListener('wheel', (e) => {
      if (!this.enabled) return;
      e.preventDefault();
      this.emit('zoom', clamp(e.deltaY * 0.002, -0.4, 0.4));
    }, { passive: false });

    document.addEventListener('pointerdown', (e) => {
      const btn = e.target.closest?.('[data-action]');
      if (!btn || !this.enabled) return;
      if (btn.closest('#mobile-controls') || btn.closest('.ability-cluster')) {
        e.preventDefault();
        e.stopPropagation();
        const action = btn.dataset.action;
        this.held.add(action);
        this.emit('action', action, 'down');
      }
    }, { capture: true });
    document.addEventListener('pointerup', (e) => {
      const btn = e.target.closest?.('[data-action]');
      if (!btn) return;
      const action = btn.dataset.action;
      if (this.held.has(action)) {
        this.held.delete(action);
        this.emit('action', action, 'up');
      }
    });
    document.addEventListener('pointercancel', () => {
      for (const a of [...this.held]) {
        this.held.delete(a);
        this.emit('action', a, 'up');
      }
    });

    this.bindJoystick();
  }

  keyAction(code) {
    return {
      Space: 'dodge', ShiftLeft: 'sprint', ShiftRight: 'sprint',
      KeyE: 'interact', KeyQ: 'resonance', KeyF: 'companion', KeyH: 'potion',
      KeyR: 'heavy', KeyT: 'lock', Tab: 'menu', Escape: 'pause',
    }[code] || null;
  }

  getMove() {
    let x = 0, z = 0;
    if (this.keys.has('KeyW') || this.keys.has('ArrowUp')) z -= 1;
    if (this.keys.has('KeyS') || this.keys.has('ArrowDown')) z += 1;
    if (this.keys.has('KeyA') || this.keys.has('ArrowLeft')) x -= 1;
    if (this.keys.has('KeyD') || this.keys.has('ArrowRight')) x += 1;
    if (this.joystick.active) { x += this.joystick.x; z += this.joystick.y; }
    const len = Math.hypot(x, z);
    if (len > 1) { x /= len; z /= len; }
    return { x, z };
  }

  isSprinting() { return this.held.has('sprint') || this.keys.has('ShiftLeft') || this.keys.has('ShiftRight'); }
  isBlocking() { return this.held.has('block'); }

  bindJoystick() {
    const zone = document.getElementById('joystick-zone');
    const knob = document.getElementById('joystick-knob');
    if (!zone || !knob) return;
    const reset = () => {
      this.joystick.active = false; this.joystick.id = null;
      this.joystick.x = 0; this.joystick.y = 0;
      knob.style.transform = 'translate(-50%, -50%)';
    };
    zone.addEventListener('pointerdown', (e) => {
      if (!this.enabled) return;
      e.preventDefault(); e.stopPropagation();
      this.joystick.active = true; this.joystick.id = e.pointerId;
      zone.setPointerCapture?.(e.pointerId);
      this.updateJoystick(e, zone, knob);
    });
    zone.addEventListener('pointermove', (e) => {
      if (!this.joystick.active || e.pointerId !== this.joystick.id) return;
      e.preventDefault();
      this.updateJoystick(e, zone, knob);
    });
    zone.addEventListener('pointerup', reset);
    zone.addEventListener('pointercancel', reset);
    zone.addEventListener('lostpointercapture', reset);
  }

  updateJoystick(e, zone, knob) {
    const rect = zone.getBoundingClientRect();
    const cx = rect.left + rect.width / 2;
    const cy = rect.top + rect.height / 2;
    const max = rect.width * 0.32;
    let dx = e.clientX - cx, dy = e.clientY - cy;
    const len = Math.hypot(dx, dy);
    if (len > max) { dx = dx / len * max; dy = dy / len * max; }
    this.joystick.x = dx / max;
    this.joystick.y = dy / max;
    knob.style.transform = `translate(calc(-50% + ${dx}px), calc(-50% + ${dy}px))`;
  }

  resetJoystickVisual() {
    const knob = document.getElementById('joystick-knob');
    if (knob) knob.style.transform = 'translate(-50%, -50%)';
  }
}

import * as THREE from 'three';
import { clamp, lerp, damp } from '../core/utils.js';

const mat = (color, opts = {}) => new THREE.MeshStandardMaterial({
  color: new THREE.Color(color),
  roughness: opts.roughness ?? 0.72,
  metalness: opts.metalness ?? 0.08,
  emissive: new THREE.Color(opts.emissive || '#000000'),
  emissiveIntensity: opts.emissiveIntensity ?? 1,
  flatShading: opts.flat ?? false,
  transparent: opts.transparent ?? false,
  opacity: opts.opacity ?? 1,
  side: opts.side ?? THREE.FrontSide,
});

const geo = {
  sphere: (r, w = 12, h = 10) => new THREE.SphereGeometry(r, w, h),
  capsule: (r, l, c = 6, rSeg = 8) => new THREE.CapsuleGeometry(r, l, c, rSeg),
  cylinder: (rt, rb, h, s = 8) => new THREE.CylinderGeometry(rt, rb, h, s),
  box: (w, h, d) => new THREE.BoxGeometry(w, h, d),
  cone: (r, h, s = 6) => new THREE.ConeGeometry(r, h, s),
};

function add(parent, geometry, material, position = [0, 0, 0], rotation = [0, 0, 0], scale = [1, 1, 1]) {
  const m = new THREE.Mesh(geometry, material);
  m.position.set(...position);
  m.rotation.set(...rotation);
  m.scale.set(...scale);
  m.castShadow = true;
  m.receiveShadow = true;
  parent.add(m);
  return m;
}

function taperedBlade(length, width, thickness, material) {
  const shape = new THREE.Shape();
  shape.moveTo(-width / 2, 0);
  shape.lineTo(width / 2, 0);
  shape.lineTo(width * 0.36, length * 0.86);
  shape.lineTo(0, length);
  shape.lineTo(-width * 0.36, length * 0.86);
  shape.closePath();
  const extrude = new THREE.ExtrudeGeometry(shape, { depth: thickness, bevelEnabled: true, bevelSize: 0.006, bevelThickness: 0.006, bevelSegments: 1, steps: 1 });
  extrude.translate(0, 0, -thickness / 2);
  const mesh = new THREE.Mesh(extrude, material);
  mesh.castShadow = true;
  return mesh;
}

function makeCape(color, trim, scale = 1) {
  const w = 0.56 * scale, h = 1.05 * scale;
  const segX = 5, segY = 7;
  const g = new THREE.PlaneGeometry(w, h, segX, segY);
  g.translate(0, -h / 2, 0);
  const m = mat(color, { roughness: 0.92, side: THREE.DoubleSide });
  const cape = new THREE.Mesh(g, m);
  cape.castShadow = true;
  cape.position.set(0, 1.48, -0.16);
  cape.rotation.x = -0.08;
  const base = g.attributes.position.array.slice();
  cape.userData.base = base;
  cape.userData.trimMat = mat(trim, { metalness: 0.5, roughness: 0.4 });
  const hem = new THREE.Mesh(new THREE.BoxGeometry(w * 0.95, 0.035, 0.018), cape.userData.trimMat);
  hem.position.set(0, -h + 0.02, 0.012);
  cape.add(hem);
  return cape;
}

function hairStyle(style, color) {
  const g = new THREE.Group();
  const hairMat = mat(color, { roughness: 0.8, flat: true });
  const cap = add(g, new THREE.SphereGeometry(0.205, 12, 8, 0, Math.PI * 2, 0, Math.PI * 0.63), hairMat, [0, 1.735, 0], [0, 0, 0], [1.02, 0.98, 1.04]);
  cap.castShadow = true;
  if (style === 'long') {
    add(g, geo.capsule(0.1, 0.42, 4, 8), hairMat, [-0.14, 1.45, -0.11], [0.12, 0, 0.15], [0.7, 1, 0.5]);
    add(g, geo.capsule(0.1, 0.42, 4, 8), hairMat, [0.14, 1.45, -0.11], [0.12, 0, -0.15], [0.7, 1, 0.5]);
    add(g, geo.capsule(0.12, 0.34, 4, 8), hairMat, [0, 1.44, -0.18], [0.2, 0, 0], [0.9, 1, 0.45]);
  } else if (style === 'braid') {
    add(g, geo.capsule(0.095, 0.32, 4, 8), hairMat, [0.15, 1.46, -0.13], [0.15, 0, -0.2], [0.8, 1, 0.55]);
    for (let i = 0; i < 4; i++) {
      add(g, geo.sphere(0.075 - i * 0.009, 8, 6), hairMat, [0.2 + i * 0.03, 1.26 - i * 0.12, -0.2], [0, 0, 0], [1, 1.2, 0.8]);
    }
    add(g, geo.cone(0.045, 0.12, 6), hairMat, [0.31, 0.79, -0.2], [0, 0, -0.25]);
  } else if (style === 'wild') {
    const spikes = [
      [-0.13, 1.88, 0.03, -0.2, 0, 0.55], [0.12, 1.9, 0.03, 0.2, 0, -0.55],
      [-0.18, 1.79, -0.04, -0.1, 0, 0.9], [0.18, 1.79, -0.04, 0.1, 0, -0.9],
      [0, 1.93, -0.07, -0.4, 0, 0], [-0.06, 1.88, 0.15, 0.6, 0, 0.1],
      [0.07, 1.87, 0.16, 0.5, 0, -0.1],
    ];
    for (const [x, y, z, rx, ry, rz] of spikes) add(g, geo.cone(0.06, 0.24, 5), hairMat, [x, y, z], [rx, ry, rz]);
  } else {
    add(g, geo.cone(0.1, 0.25, 5), hairMat, [-0.12, 1.85, 0.02], [0.2, 0, 0.55]);
    add(g, geo.cone(0.1, 0.22, 5), hairMat, [0.13, 1.86, 0.01], [0.2, 0, -0.5]);
    add(g, geo.cone(0.08, 0.2, 5), hairMat, [0, 1.9, -0.03], [-0.35, 0, 0]);
    add(g, geo.cone(0.065, 0.2, 5), hairMat, [-0.19, 1.76, 0.02], [0.1, 0, 0.9]);
    add(g, geo.cone(0.065, 0.2, 5), hairMat, [0.19, 1.76, 0.02], [0.1, 0, -0.9]);
  }
  return g;
}

function makeSword(appearance = {}) {
  const group = new THREE.Group();
  const bladeMat = new THREE.MeshStandardMaterial({ color: appearance.blade || '#d8ecf1', metalness: 0.85, roughness: 0.24, emissive: appearance.edge || '#ffe5a8', emissiveIntensity: 0.22 });
  const edgeMat = new THREE.MeshBasicMaterial({ color: appearance.edge || '#ffe5a8', transparent: true, opacity: 0.75, blending: THREE.AdditiveBlending });
  const goldMat = mat('#c9a45d', { metalness: 0.85, roughness: 0.3 });
  const leather = mat('#3c2b25', { roughness: 0.9 });
  const blade = taperedBlade(1.03 * (appearance.scale || 1), 0.105, 0.025, bladeMat);
  blade.position.y = 0.08;
  group.add(blade);
  const glow = new THREE.Mesh(new THREE.PlaneGeometry(0.025, 0.85 * (appearance.scale || 1)), edgeMat);
  glow.position.set(0, 0.52, 0.016);
  group.add(glow);
  const cross = add(group, geo.box(0.34, 0.045, 0.075), goldMat, [0, 0.06, 0]);
  cross.rotation.z = 0;
  add(group, geo.cylinder(0.03, 0.035, 0.22, 8), leather, [0, -0.07, 0]);
  add(group, geo.sphere(0.055, 8, 6), goldMat, [0, -0.2, 0]);
  add(group, new THREE.TorusGeometry(0.055, 0.012, 6, 12), goldMat, [0, 0.055, 0], [Math.PI / 2, 0, 0]);
  group.userData.glow = glow;
  return group;
}

export function createHero(options = {}) {
  const outfit = options.outfit || { primary: '#3e7d78', secondary: '#d6b16e', trim: '#f5e3b4', metal: '#c6a45f' };
  const skin = options.skin || '#e9c9a8';
  const hairColor = options.hairColor || '#d9d5cc';
  const hair = options.hairStyle || 'short';
  const root = new THREE.Group();
  const body = new THREE.Group();
  root.add(body);

  const cloth = mat(outfit.primary, { roughness: 0.82 });
  const clothDark = mat(outfit.secondary, { roughness: 0.78 });
  const trimMat = mat(outfit.trim, { metalness: 0.45, roughness: 0.42 });
  const metal = mat(outfit.metal || '#c6a45f', { metalness: 0.85, roughness: 0.28 });
  const leather = mat('#3b2a23', { roughness: 0.9 });
  const skinMat = mat(skin, { roughness: 0.78 });
  const dark = mat('#252129', { roughness: 0.8 });
  const eyeMat = new THREE.MeshStandardMaterial({ color: '#2b2226', emissive: '#3f7f78', emissiveIntensity: 0.4, roughness: 0.4 });
  const glowMat = new THREE.MeshBasicMaterial({ color: '#a8f0e6', transparent: true, opacity: 0.85, blending: THREE.AdditiveBlending });

  // legs
  const leftLeg = new THREE.Group();
  leftLeg.position.set(-0.13, 0.86, 0);
  add(leftLeg, geo.capsule(0.1, 0.46, 4, 8), leather, [0, -0.3, 0]);
  add(leftLeg, geo.capsule(0.082, 0.28, 4, 8), clothDark, [0, -0.7, 0.01]);
  add(leftLeg, geo.box(0.17, 0.12, 0.3), metal, [0, -0.9, 0.07]);
  body.add(leftLeg);
  const rightLeg = new THREE.Group();
  rightLeg.position.set(0.13, 0.86, 0);
  add(rightLeg, geo.capsule(0.1, 0.46, 4, 8), leather, [0, -0.3, 0]);
  add(rightLeg, geo.capsule(0.082, 0.28, 4, 8), clothDark, [0, -0.7, 0.01]);
  add(rightLeg, geo.box(0.17, 0.12, 0.3), metal, [0, -0.9, 0.07]);
  body.add(rightLeg);

  // hips / belt
  add(body, geo.cylinder(0.22, 0.2, 0.18, 10), leather, [0, 0.88, 0]);
  add(body, geo.box(0.46, 0.06, 0.26), metal, [0, 0.92, 0]);
  add(body, geo.box(0.09, 0.09, 0.03), trimMat, [0, 0.92, 0.145]);

  // torso
  const torso = new THREE.Group();
  torso.position.set(0, 1.18, 0);
  body.add(torso);
  add(torso, geo.cylinder(0.24, 0.18, 0.52, 8), cloth, [0, 0, 0], [0, 0, 0], [1, 1, 0.78]);
  add(torso, geo.box(0.34, 0.36, 0.2), clothDark, [0, 0.03, 0.02]);
  const chest = add(torso, geo.box(0.27, 0.3, 0.07), metal, [0, 0.06, 0.16]);
  chest.rotation.x = -0.04;
  add(torso, geo.box(0.06, 0.3, 0.075), trimMat, [0, 0.06, 0.205]);
  add(torso, geo.box(0.3, 0.045, 0.08), trimMat, [0, -0.09, 0.17]);
  add(torso, new THREE.TorusGeometry(0.11, 0.012, 5, 12), trimMat, [0, 0.15, 0.21], [0, 0, 0]);
  add(torso, geo.sphere(0.032, 8, 6), glowMat, [0, 0.15, 0.225]);
  // shoulder pads
  add(torso, geo.sphere(0.16, 10, 7), metal, [-0.32, 0.16, 0], [0, 0, 0.18], [1, 0.7, 0.9]);
  add(torso, geo.sphere(0.16, 10, 7), metal, [0.32, 0.16, 0], [0, 0, -0.18], [1, 0.7, 0.9]);
  add(torso, geo.cone(0.055, 0.16, 5), trimMat, [-0.38, 0.23, 0], [0, 0, 0.4]);
  add(torso, geo.cone(0.055, 0.16, 5), trimMat, [0.38, 0.23, 0], [0, 0, -0.4]);
  // collar
  add(torso, geo.cylinder(0.19, 0.14, 0.13, 8), clothDark, [0, 0.3, -0.01], [0, 0, 0], [1, 1, 0.8]);

  // neck & head
  add(body, geo.cylinder(0.065, 0.075, 0.11, 8), skinMat, [0, 1.48, 0]);
  const head = new THREE.Group();
  head.position.set(0, 1.72, 0.01);
  body.add(head);
  add(head, geo.sphere(0.19, 16, 12), skinMat, [0, 0, 0], [0, 0, 0], [1, 1.03, 0.94]);
  // jaw
  add(head, geo.sphere(0.13, 10, 8), skinMat, [0, -0.09, 0.055], [0, 0, 0], [1, 0.8, 0.8]);
  // eyes
  add(head, geo.sphere(0.026, 8, 6), eyeMat, [-0.068, 0.015, 0.172], [0, 0, 0], [1, 1.15, 0.5]);
  add(head, geo.sphere(0.026, 8, 6), eyeMat, [0.068, 0.015, 0.172], [0, 0, 0], [1, 1.15, 0.5]);
  add(head, geo.sphere(0.008, 6, 4), glowMat, [-0.068, 0.022, 0.19], [0, 0, 0], [1, 1, 0.4]);
  add(head, geo.sphere(0.008, 6, 4), glowMat, [0.068, 0.022, 0.19], [0, 0, 0], [1, 1, 0.4]);
  add(head, geo.box(0.055, 0.012, 0.012), mat('#8b5f55', { roughness: 0.8 }), [0, -0.07, 0.175]);
  // ears
  add(head, geo.sphere(0.032, 8, 6), skinMat, [-0.185, 0, 0], [0, 0, 0], [0.5, 1, 0.8]);
  add(head, geo.sphere(0.032, 8, 6), skinMat, [0.185, 0, 0], [0, 0, 0], [0.5, 1, 0.8]);
  const hairGroup = hairStyle(hair, hairColor);
  head.add(hairGroup);
  // circlet
  add(head, new THREE.TorusGeometry(0.195, 0.01, 4, 16), trimMat, [0, 0.06, 0], [Math.PI / 2, 0, 0], [1, 1, 0.9]);
  add(head, geo.cone(0.024, 0.06, 4), glowMat, [0, 0.25, 0.01], [0, 0, 0]);

  // arms
  const leftArm = new THREE.Group();
  leftArm.position.set(-0.33, 1.42, 0);
  add(leftArm, geo.capsule(0.075, 0.28, 4, 8), cloth, [0, -0.2, 0]);
  add(leftArm, geo.capsule(0.06, 0.22, 4, 8), leather, [0, -0.46, 0]);
  add(leftArm, geo.box(0.12, 0.14, 0.12), metal, [0, -0.6, 0]);
  add(leftArm, geo.sphere(0.075, 8, 6), skinMat, [0, -0.68, 0]);
  body.add(leftArm);
  const rightArm = new THREE.Group();
  rightArm.position.set(0.33, 1.42, 0);
  add(rightArm, geo.capsule(0.075, 0.28, 4, 8), cloth, [0, -0.2, 0]);
  add(rightArm, geo.capsule(0.06, 0.22, 4, 8), leather, [0, -0.46, 0]);
  add(rightArm, geo.box(0.12, 0.14, 0.12), metal, [0, -0.6, 0]);
  add(rightArm, geo.sphere(0.075, 8, 6), skinMat, [0, -0.68, 0]);
  body.add(rightArm);

  // sword
  const sword = makeSword(options.weaponAppearance || {});
  sword.position.set(0, -0.7, 0.02);
  sword.rotation.x = Math.PI;
  sword.rotation.z = 0.04;
  rightArm.add(sword);

  // cape
  const cape = makeCape(outfit.primary, outfit.trim);
  body.add(cape);

  // floating rune / aura
  const aura = new THREE.Mesh(new THREE.TorusGeometry(0.45, 0.008, 4, 32), new THREE.MeshBasicMaterial({ color: outfit.trim, transparent: true, opacity: 0.15, blending: THREE.AdditiveBlending }));
  aura.rotation.x = Math.PI / 2;
  aura.position.y = 0.04;
  root.add(aura);

  root.userData.rig = {
    body, torso, head, hairGroup, leftLeg, rightLeg, leftArm, rightArm, sword, cape, aura,
    materials: { cloth, clothDark, trimMat, metal, leather, skinMat, eyeMat, glowMat },
  };
  root.userData.type = 'hero';
  root.userData.height = 1.9;
  return root;
}

export function updateHeroAppearance(hero, options) {
  const r = hero.userData.rig;
  if (!r) return;
  if (options.outfit) {
    r.materials.cloth.color.set(options.outfit.primary);
    r.materials.clothDark.color.set(options.outfit.secondary);
    r.materials.trimMat.color.set(options.outfit.trim);
    r.materials.metal.color.set(options.outfit.metal || '#c6a45f');
    if (r.cape) {
      r.cape.material.color.set(options.outfit.primary);
      r.cape.userData.trimMat.color.set(options.outfit.trim);
    }
  }
  if (options.weaponAppearance && r.sword) {
    const sword = makeSword(options.weaponAppearance);
    sword.position.copy(r.sword.position);
    sword.rotation.copy(r.sword.rotation);
    r.rightArm.remove(r.sword);
    r.rightArm.add(sword);
    r.sword = sword;
  }
}

export function poseHero(hero, state, dt, time) {
  const r = hero.userData.rig;
  if (!r) return;
  const speed = clamp(state.speed || 0, 0, 1.5);
  const run = speed > 0.04;
  const phase = state.runPhase || 0;
  const attack = state.attack || 0;
  const attackType = state.attackType || 'light';
  const combo = state.combo || 0;
  const blocking = state.blocking;
  const dodging = state.dodge || 0;
  const hurt = state.hurt || 0;
  const dead = state.dead || 0;

  const breathe = Math.sin(time * 1.7) * 0.012;
  const runSin = Math.sin(phase);
  const runCos = Math.cos(phase);

  r.body.position.y = run ? Math.abs(Math.sin(phase * 2)) * 0.025 : breathe;
  r.body.rotation.x = run ? -0.07 * clamp(speed, 0, 1) : 0;
  r.body.rotation.z = dodging ? Math.sin(clamp(dodging, 0, 1) * Math.PI) * 0.35 : 0;
  r.body.rotation.y = attack ? (attackType === 'heavy' ? -0.25 : 0.1) : 0;

  if (run) {
    r.leftLeg.rotation.x = runSin * 0.75 * clamp(speed, 0, 1.25);
    r.rightLeg.rotation.x = -runSin * 0.75 * clamp(speed, 0, 1.25);
    r.leftArm.rotation.x = -runSin * 0.5 * clamp(speed, 0, 1.2);
    r.rightArm.rotation.x = runSin * 0.45 * clamp(speed, 0, 1.2);
    r.leftArm.rotation.z = 0.04;
    r.rightArm.rotation.z = -0.04;
    r.torso.rotation.y = runSin * 0.07;
    r.torso.rotation.x = 0.05;
  } else {
    r.leftLeg.rotation.x = damp(r.leftLeg.rotation.x, 0, 10, dt);
    r.rightLeg.rotation.x = damp(r.rightLeg.rotation.x, 0, 10, dt);
    r.leftArm.rotation.x = damp(r.leftArm.rotation.x, Math.sin(time * 1.3) * 0.025, 8, dt);
    r.rightArm.rotation.x = damp(r.rightArm.rotation.x, Math.sin(time * 1.3 + 1) * 0.025, 8, dt);
    r.leftArm.rotation.z = damp(r.leftArm.rotation.z, 0.06, 8, dt);
    r.rightArm.rotation.z = damp(r.rightArm.rotation.z, -0.06, 8, dt);
    r.torso.rotation.y = damp(r.torso.rotation.y, 0, 8, dt);
    r.torso.rotation.x = damp(r.torso.rotation.x, 0, 8, dt);
  }

  if (blocking) {
    r.rightArm.rotation.x = damp(r.rightArm.rotation.x, -1.25, 16, dt);
    r.rightArm.rotation.z = damp(r.rightArm.rotation.z, -0.25, 16, dt);
    r.leftArm.rotation.x = damp(r.leftArm.rotation.x, -1.4, 16, dt);
    r.leftArm.rotation.z = damp(r.leftArm.rotation.z, 0.38, 16, dt);
    r.sword.rotation.x = damp(r.sword.rotation.x, Math.PI - 0.2, 16, dt);
    r.body.rotation.x = damp(r.body.rotation.x, 0.08, 12, dt);
  }

  if (attack > 0) {
    const t = clamp(attack, 0, 1);
    const swing = attackType === 'heavy'
      ? Math.sin(t * Math.PI) * 2.4
      : Math.sin(t * Math.PI) * 1.9;
    const dir = combo % 2 === 0 ? 1 : -1;
    r.rightArm.rotation.x = -0.45 - swing * 0.9;
    r.rightArm.rotation.z = -0.2 + dir * swing * 0.45;
    r.rightArm.rotation.y = dir * swing * 0.55;
    r.sword.rotation.x = Math.PI - 0.7 + Math.sin(t * Math.PI) * 1.2;
    r.torso.rotation.y = -dir * Math.sin(t * Math.PI) * 0.5;
    r.leftArm.rotation.x = -0.2 - Math.sin(t * Math.PI) * 0.5;
    r.leftArm.rotation.z = 0.25;
    r.body.rotation.x = -Math.sin(t * Math.PI) * 0.08;
  }

  if (dodging > 0) {
    const t = clamp(dodging, 0, 1);
    r.body.rotation.x = Math.sin(t * Math.PI) * 0.8;
    r.body.position.y = Math.sin(t * Math.PI) * 0.25;
    r.leftArm.rotation.x = -0.8;
    r.rightArm.rotation.x = -0.8;
    r.leftLeg.rotation.x = -0.6;
    r.rightLeg.rotation.x = -0.6;
  }

  if (hurt > 0) {
    r.body.rotation.x = Math.sin(hurt * Math.PI) * -0.2;
    r.torso.rotation.z = Math.sin(hurt * Math.PI) * 0.12;
  }
  if (dead > 0) {
    const t = clamp(dead, 0, 1);
    r.body.rotation.x = t * 1.25;
    r.body.position.y = -t * 0.3;
    r.leftLeg.rotation.x = -t * 0.4;
    r.rightLeg.rotation.x = -t * 0.4;
  }

  // cape physics-ish
  if (r.cape) {
    const pos = r.cape.geometry.attributes.position;
    const base = r.cape.userData.base;
    const sway = Math.sin(time * 2.2) * 0.025 + speed * 0.06;
    for (let i = 0; i < pos.count; i++) {
      const x = base[i * 3];
      const y = base[i * 3 + 1];
      const z = base[i * 3 + 2];
      const depth = clamp((-y) / 1.05, 0, 1);
      pos.setZ(i, z + Math.sin(time * 3.4 + y * 6 + x * 2) * 0.035 * depth + depth * (0.08 + speed * 0.22));
      pos.setX(i, x + Math.sin(time * 2.3 + y * 4) * 0.018 * depth);
    }
    pos.needsUpdate = true;
    r.cape.geometry.computeVertexNormals();
  }
  if (r.aura) {
    r.aura.rotation.z = time * 0.18;
    r.aura.material.opacity = 0.12 + Math.sin(time * 2) * 0.035;
  }
  if (r.sword?.userData?.glow) {
    r.sword.userData.glow.material.opacity = 0.55 + Math.sin(time * 4) * 0.12;
  }
}

/* ----------------------------- Creatures ----------------------------- */

function creatureMat(color, emissiveIntensity = 0.8) {
  return new THREE.MeshStandardMaterial({
    color: new THREE.Color(color), roughness: 0.45, metalness: 0.15,
    emissive: new THREE.Color(color), emissiveIntensity,
    transparent: true, opacity: 0.94,
  });
}

export function createCreature(id, scale = 1) {
  const group = new THREE.Group();
  const data = {
    lumin: { c1: '#ffe0a0', c2: '#d6a94d', glow: '#fff2c4' },
    bruma: { c1: '#a99bd6', c2: '#574a86', glow: '#d9ccff' },
    terravok: { c1: '#9cc08b', c2: '#506344', glow: '#d7f0bd' },
    chispa: { c1: '#ff9b57', c2: '#b5362e', glow: '#ffd0a0' },
    aeris: { c1: '#a7e3dc', c2: '#427c85', glow: '#d9fffb' },
    astral: { c1: '#bca3ee', c2: '#514b9f', glow: '#eadfff' },
    seraph: { c1: '#f2e7bd', c2: '#c59b52', glow: '#fff8d9' },
  }[id] || { c1: '#ffe0a0', c2: '#d6a94d', glow: '#fff2c4' };
  const c1 = creatureMat(data.c1, 0.75);
  const c2 = creatureMat(data.c2, 0.35);
  const glow = new THREE.MeshBasicMaterial({ color: data.glow, transparent: true, opacity: 0.85, blending: THREE.AdditiveBlending, depthWrite: false });
  const dark = new THREE.MeshStandardMaterial({ color: '#22202a', roughness: 0.8 });
  const body = new THREE.Group();
  group.add(body);

  if (id === 'lumin' || id === 'chispa') {
    add(body, geo.sphere(0.26, 12, 9), c1, [0, 0.42, 0], [0, 0, 0], [1.35, 0.9, 0.8]);
    add(body, geo.sphere(0.2, 12, 9), c1, [0, 0.66, 0.17], [0, 0, 0], [1, 1, 0.95]);
    add(body, geo.sphere(0.07, 8, 6), c2, [0, 0.48, 0.34], [0, 0, 0], [1, 0.8, 0.8]);
    add(body, geo.cone(0.12, 0.25, 5), c1, [-0.13, 0.85, 0.12], [0, 0, 0.18]);
    add(body, geo.cone(0.12, 0.25, 5), c1, [0.13, 0.85, 0.12], [0, 0, -0.18]);
    for (const s of [-1, 1]) {
      add(body, geo.sphere(0.04, 6, 4), dark, [s * 0.085, 0.69, 0.34]);
      add(body, geo.sphere(0.014, 5, 4), glow, [s * 0.085, 0.7, 0.375]);
      add(body, geo.capsule(0.045, 0.18, 3, 6), c2, [s * 0.16, 0.18, 0], [0, 0, 0], [1, 1, 0.7]);
      add(body, geo.sphere(0.06, 6, 4), c2, [s * 0.16, 0.04, 0.02]);
    }
    const tail = new THREE.Group();
    tail.position.set(0, 0.4, -0.25);
    body.add(tail);
    add(tail, geo.capsule(0.08, 0.35, 4, 7), c1, [0, 0.08, -0.18], [0.9, 0, 0], [1, 1, 0.8]);
    add(tail, geo.sphere(0.12, 8, 6), glow, [0, 0.2, -0.43]);
    group.userData.tail = tail;
  } else if (id === 'bruma') {
    add(body, geo.cone(0.34, 0.9, 7), c2, [0, 0.38, 0], [0, 0, 0], [1, 1, 0.7]);
    add(body, geo.sphere(0.23, 12, 9), c1, [0, 0.78, 0]);
    add(body, geo.sphere(0.06, 6, 4), glow, [-0.09, 0.82, 0.2]);
    add(body, geo.sphere(0.06, 6, 4), glow, [0.09, 0.82, 0.2]);
    for (const s of [-1, 1]) add(body, geo.cone(0.08, 0.34, 5), c1, [s * 0.24, 0.65, 0], [0, 0, s * 0.8]);
    add(body, new THREE.TorusGeometry(0.28, 0.012, 4, 20), glow, [0, 0.45, 0], [Math.PI / 2, 0, 0]);
  } else if (id === 'terravok') {
    add(body, geo.sphere(0.38, 10, 8), c2, [0, 0.36, 0], [0, 0, 0], [1.2, 0.8, 1]);
    add(body, geo.sphere(0.28, 10, 8), c1, [0, 0.48, 0.02], [0, 0, 0], [1, 0.7, 0.9]);
    for (const s of [-1, 1]) {
      add(body, geo.sphere(0.06, 6, 4), glow, [s * 0.11, 0.55, 0.29]);
      for (let i = 0; i < 2; i++) add(body, geo.capsule(0.055, 0.12, 3, 6), c2, [s * 0.25, 0.16, -0.1 + i * 0.18], [0.3, 0, 0]);
    }
    add(body, geo.cone(0.08, 0.2, 5), c1, [-0.12, 0.7, 0.02], [0, 0, 0.2]);
    add(body, geo.cone(0.08, 0.2, 5), c1, [0.12, 0.7, 0.02], [0, 0, -0.2]);
    add(body, geo.sphere(0.1, 7, 5), c1, [0, 0.45, 0.36], [0, 0, 0], [1, 0.7, 0.8]);
  } else if (id === 'aeris') {
    add(body, geo.sphere(0.22, 12, 9), c1, [0, 0.65, 0], [0, 0, 0], [1, 1.2, 0.8]);
    for (const s of [-1, 1]) {
      add(body, geo.sphere(0.16, 8, 6), glow, [s * 0.3, 0.72, 0], [0, 0, s * 0.4], [1.5, 0.16, 0.5]);
      add(body, geo.sphere(0.03, 6, 4), dark, [s * 0.08, 0.72, 0.18]);
    }
    for (let i = 0; i < 5; i++) add(body, geo.capsule(0.02, 0.25 + i * 0.03, 3, 5), c1, [(i - 2) * 0.08, 0.28 - i * 0.02, 0], [0, 0, (i - 2) * 0.12]);
    add(body, new THREE.TorusGeometry(0.3, 0.008, 4, 20), glow, [0, 0.64, 0], [Math.PI / 2, 0, 0]);
  } else if (id === 'astral') {
    add(body, geo.sphere(0.27, 12, 9), c1, [0, 0.66, 0], [0, 0, 0], [1, 1.05, 0.9]);
    add(body, geo.cone(0.07, 0.18, 5), c2, [-0.12, 0.9, 0], [0, 0, 0.2]);
    add(body, geo.cone(0.07, 0.18, 5), c2, [0.12, 0.9, 0], [0, 0, -0.2]);
    for (const s of [-1, 1]) {
      add(body, geo.sphere(0.06, 6, 4), glow, [s * 0.1, 0.69, 0.2]);
      add(body, geo.sphere(0.18, 8, 6), glow, [s * 0.33, 0.62, -0.02], [0, 0, s * 0.3], [1.3, 0.18, 0.6]);
    }
    add(body, new THREE.TorusGeometry(0.32, 0.012, 4, 24), glow, [0, 0.98, 0], [Math.PI / 2, 0, 0]);
    add(body, new THREE.TorusGeometry(0.4, 0.006, 4, 24), glow, [0, 0.98, 0], [Math.PI / 2, 0.4, 0]);
    add(body, geo.sphere(0.06, 6, 4), c2, [0, 0.52, 0.2]);
  } else {
    add(body, geo.sphere(0.2, 10, 8), c1, [0, 0.7, 0]);
    for (const s of [-1, 1]) {
      add(body, geo.sphere(0.3, 8, 6), glow, [s * 0.34, 0.78, -0.04], [0, 0, s * 0.5], [1.4, 0.2, 0.7]);
      add(body, geo.sphere(0.035, 6, 4), dark, [s * 0.07, 0.75, 0.18]);
    }
    add(body, new THREE.TorusGeometry(0.27, 0.01, 4, 20), glow, [0, 0.98, 0], [Math.PI / 2, 0, 0]);
    add(body, geo.cone(0.18, 0.5, 7), c2, [0, 0.3, 0]);
  }

  group.scale.setScalar(scale);
  group.userData.type = 'creature';
  group.userData.id = id;
  group.userData.baseY = 0;
  group.userData.body = body;
  group.traverse((o) => { if (o.isMesh) { o.castShadow = true; o.receiveShadow = false; } });
  return group;
}

export function animateCreature(creature, t, active = true) {
  const body = creature.userData.body;
  if (!body) return;
  body.position.y = Math.sin(t * 2.2) * 0.06 + (active ? 0 : 0.08);
  body.rotation.y = Math.sin(t * 0.8) * 0.12;
  if (creature.userData.tail) creature.userData.tail.rotation.y = Math.sin(t * 2.8) * 0.25;
  body.rotation.z = Math.sin(t * 1.4) * 0.025;
}

import * as THREE from 'three';
import { REGIONS } from './data.js';
import { createHero, poseHero, createCreature, animateCreature } from './character.js';
import {
  clamp, lerp, smoothstep, mulberry32, fbm, noise2D, dist2D,
  radialTexture, runeTexture, textureFromCanvas, makeCanvas, disposeObject,
} from '../core/utils.js';

const UP = new THREE.Vector3(0, 1, 0);

const PALETTE = {
  valdoria: {
    trunk: '#5b4735', trunkDark: '#443428', canopy: ['#3f6a3e', '#527b45', '#628a4c', '#759d59'],
    rock: '#73786a', flower: ['#f1d48a', '#e8a4b0', '#c4b2ed', '#f3f0df'], grass: ['#6d9255', '#7ba15e', '#8aac69'],
    accent: '#e6c37d', mist: '#c1d4c6',
  },
  drakmor: {
    trunk: '#332827', trunkDark: '#211b1c', canopy: ['#3c2a27', '#4b302a', '#5b372d'],
    rock: '#2b2728', flower: ['#ff7b3e', '#d94a32'], grass: ['#4b3b32', '#5b4236'],
    accent: '#ff8a4a', mist: '#6d3b35',
  },
  kansordore: {
    trunk: '#6c6688', trunkDark: '#4e4968', canopy: ['#8e87b5', '#a49bc7', '#b8abd3'],
    rock: '#8d88a5', flower: ['#d9cfff', '#9ee7e2', '#f3e1a8'], grass: ['#a7a2ba', '#bab3c8'],
    accent: '#bca3ee', mist: '#8b87b5',
  },
};

function makeMat(color, opts = {}) {
  return new THREE.MeshStandardMaterial({
    color: new THREE.Color(color),
    roughness: opts.roughness ?? 0.86,
    metalness: opts.metalness ?? 0.03,
    emissive: new THREE.Color(opts.emissive || '#000000'),
    emissiveIntensity: opts.emissiveIntensity ?? 1,
    flatShading: opts.flat ?? false,
    transparent: opts.transparent ?? false,
    opacity: opts.opacity ?? 1,
    side: opts.side ?? THREE.FrontSide,
  });
}

function mesh(geometry, material, pos = [0, 0, 0], rot = [0, 0, 0], scale = [1, 1, 1], shadow = true) {
  const m = new THREE.Mesh(geometry, material);
  m.position.set(...pos);
  m.rotation.set(...rot);
  m.scale.set(...scale);
  m.castShadow = shadow;
  m.receiveShadow = shadow;
  return m;
}

function distToSegment(px, pz, ax, az, bx, bz) {
  const vx = bx - ax, vz = bz - az;
  const wx = px - ax, wz = pz - az;
  const len2 = vx * vx + vz * vz;
  const t = len2 > 0 ? clamp((wx * vx + wz * vz) / len2, 0, 1) : 0;
  return Math.hypot(px - (ax + vx * t), pz - (az + vz * t));
}

function pathDistance(x, z, paths) {
  let min = Infinity;
  for (const seg of paths) min = Math.min(min, distToSegment(x, z, seg[0], seg[1], seg[2], seg[3]));
  return min;
}

function flatten(h, x, z, cx, cz, radius, target, blend = 7) {
  const d = Math.hypot(x - cx, z - cz);
  if (d > radius + blend) return h;
  const t = 1 - smoothstep(radius, radius + blend, d);
  return lerp(h, target, t);
}

function makeSky(region) {
  const group = new THREE.Group();
  const sunDir = new THREE.Vector3(...region.sun.position).normalize();
  const mat = new THREE.ShaderMaterial({
    side: THREE.BackSide,
    depthWrite: false,
    fog: false,
    uniforms: {
      uTop: { value: new THREE.Color(region.sky.top) },
      uMid: { value: new THREE.Color(region.sky.mid) },
      uLow: { value: new THREE.Color(region.sky.low) },
      uSun: { value: new THREE.Color(region.sky.sun) },
      uSunDir: { value: sunDir },
      uTime: { value: 0 },
    },
    vertexShader: `
      varying vec3 vWorld;
      void main() {
        vec4 wp = modelMatrix * vec4(position, 1.0);
        vWorld = wp.xyz;
        gl_Position = projectionMatrix * viewMatrix * wp;
      }
    `,
    fragmentShader: `
      uniform vec3 uTop, uMid, uLow, uSun, uSunDir;
      uniform float uTime;
      varying vec3 vWorld;
      float hash(vec2 p){ return fract(sin(dot(p, vec2(127.1,311.7))) * 43758.5453); }
      void main() {
        vec3 dir = normalize(vWorld);
        float h = clamp(dir.y * 0.5 + 0.5, 0.0, 1.0);
        vec3 col = mix(uLow, uMid, smoothstep(0.42, 0.62, h));
        col = mix(col, uTop, smoothstep(0.58, 0.98, h));
        float sun = max(dot(dir, normalize(uSunDir)), 0.0);
        col += uSun * pow(sun, 150.0) * 1.9;
        col += uSun * pow(sun, 8.0) * 0.16;
        float band = sin(dir.y * 22.0 + sin(dir.x * 8.0 + uTime * 0.015) * 2.0) * 0.5 + 0.5;
        col += uLow * band * 0.018;
        gl_FragColor = vec4(col, 1.0);
      }
    `,
  });
  const sky = new THREE.Mesh(new THREE.SphereGeometry(400, 40, 24), mat);
  sky.renderOrder = -10;
  group.add(sky);
  group.userData.skyMat = mat;
  return group;
}

function makeWater(region, isLava = false) {
  const mat = new THREE.ShaderMaterial({
    transparent: true,
    depthWrite: false,
    uniforms: {
      uTime: { value: 0 },
      uColor: { value: new THREE.Color(region.water.color) },
      uEmissive: { value: new THREE.Color(region.water.emissive) },
      uLava: { value: isLava ? 1 : 0 },
    },
    vertexShader: `
      uniform float uTime;
      varying vec2 vUv;
      varying float vWave;
      void main() {
        vUv = uv;
        vec3 p = position;
        float wave = sin(p.x * 0.45 + uTime * 0.8) * 0.06 + cos(p.y * 0.4 + uTime * 0.55) * 0.05;
        p.z += wave;
        vWave = wave;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(p, 1.0);
      }
    `,
    fragmentShader: `
      uniform vec3 uColor, uEmissive;
      uniform float uTime, uLava;
      varying vec2 vUv;
      varying float vWave;
      float hash(vec2 p){ return fract(sin(dot(p, vec2(127.1,311.7))) * 43758.5453); }
      void main() {
        vec2 p = vUv * vec2(90.0, 90.0);
        float n = sin(p.x * 0.7 + uTime * 0.3) * sin(p.y * 0.9 - uTime * 0.2);
        float n2 = sin((p.x + p.y) * 1.7 + uTime * 0.7) * 0.5 + 0.5;
        vec3 col = uColor + uEmissive * (0.2 + n2 * 0.16);
        float sparkle = smoothstep(0.88, 1.0, n2 + n * 0.3);
        col += vec3(1.0, 0.82, 0.5) * sparkle * (0.55 + uLava * 1.5);
        float alpha = mix(0.72, 0.92, uLava) + vWave * 0.4;
        gl_FragColor = vec4(col, alpha);
      }
    `,
  });
  const geo = new THREE.PlaneGeometry(190, 190, 1, 1);
  const water = new THREE.Mesh(geo, mat);
  water.rotation.x = -Math.PI / 2;
  water.position.y = region.water.level;
  water.receiveShadow = false;
  water.userData.mat = mat;
  return water;
}

function makeClouds(region, seed) {
  const group = new THREE.Group();
  const tex = radialTexture(128, 'rgba(255,255,255,0.72)', 'rgba(255,255,255,0)');
  const rng = mulberry32(seed);
  for (let i = 0; i < 22; i++) {
    const mat = new THREE.SpriteMaterial({ map: tex, transparent: true, opacity: 0.1 + rng() * 0.12, depthWrite: false, color: new THREE.Color(region.sky.mid), fog: false });
    const s = new THREE.Sprite(mat);
    const angle = rng() * Math.PI * 2;
    const r = 80 + rng() * 130;
    s.position.set(Math.cos(angle) * r, 32 + rng() * 42, Math.sin(angle) * r);
    s.scale.set(38 + rng() * 55, 14 + rng() * 22, 1);
    s.userData.drift = 0.1 + rng() * 0.25;
    group.add(s);
  }
  return group;
}

function makeMountainRing(region, seed) {
  const group = new THREE.Group();
  const rng = mulberry32(seed);
  const colors = [region.sky.mid, region.sky.fog, region.sky.top];
  for (let i = 0; i < 28; i++) {
    const angle = (i / 28) * Math.PI * 2 + rng() * 0.15;
    const r = 100 + rng() * 38;
    const h = 16 + rng() * 28;
    const width = 15 + rng() * 18;
    const mat = new THREE.MeshStandardMaterial({ color: new THREE.Color(colors[i % 3]), roughness: 1, metalness: 0, flatShading: true });
    const m = new THREE.Mesh(new THREE.ConeGeometry(width, h, 5 + Math.floor(rng() * 3)), mat);
    m.position.set(Math.cos(angle) * r, h / 2 - 3, Math.sin(angle) * r);
    m.rotation.y = rng() * Math.PI;
    m.receiveShadow = false;
    group.add(m);
  }
  return group;
}

function makeParticles(region, seed) {
  const group = new THREE.Group();
  const rng = mulberry32(seed);
  const count = region.weather === 'embers' ? 170 : 150;
  const positions = new Float32Array(count * 3);
  const sizes = new Float32Array(count);
  const phases = new Float32Array(count);
  for (let i = 0; i < count; i++) {
    positions[i * 3] = (rng() - 0.5) * 165;
    positions[i * 3 + 1] = 0.3 + rng() * 16;
    positions[i * 3 + 2] = (rng() - 0.5) * 165;
    sizes[i] = 0.4 + rng() * 1.2;
    phases[i] = rng() * Math.PI * 2;
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  geo.setAttribute('aSize', new THREE.BufferAttribute(sizes, 1));
  geo.setAttribute('aPhase', new THREE.BufferAttribute(phases, 1));
  const color = region.weather === 'embers' ? '#ff8b4a' : region.weather === 'motes' ? '#c9b9ff' : '#ffe7a8';
  const mat = new THREE.ShaderMaterial({
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    uniforms: { uTime: { value: 0 }, uColor: { value: new THREE.Color(color) }, uPixelRatio: { value: Math.min(devicePixelRatio, 2) } },
    vertexShader: `
      attribute float aSize;
      attribute float aPhase;
      uniform float uTime, uPixelRatio;
      varying float vAlpha;
      void main() {
        vec3 p = position;
        p.y += sin(uTime * 0.45 + aPhase) * 1.2;
        p.x += cos(uTime * 0.23 + aPhase * 2.0) * 0.8;
        vec4 mv = modelViewMatrix * vec4(p, 1.0);
        gl_PointSize = aSize * uPixelRatio * (170.0 / -mv.z);
        gl_Position = projectionMatrix * mv;
        vAlpha = 0.35 + 0.65 * (sin(uTime * 1.5 + aPhase) * 0.5 + 0.5);
      }
    `,
    fragmentShader: `
      uniform vec3 uColor;
      varying float vAlpha;
      void main() {
        vec2 c = gl_PointCoord - 0.5;
        float d = length(c);
        float a = smoothstep(0.5, 0.05, d) * vAlpha;
        gl_FragColor = vec4(uColor, a);
      }
    `,
  });
  const points = new THREE.Points(geo, mat);
  points.frustumCulled = false;
  group.add(points);
  group.userData.mat = mat;
  return group;
}

function makeGrass(regionId, heightAt, count, seed, isClear) {
  const rng = mulberry32(seed);
  const pal = PALETTE[regionId];
  const geo = new THREE.ConeGeometry(0.045, 0.52, 3, 1);
  geo.translate(0, 0.26, 0);
  const mat = new THREE.MeshStandardMaterial({ color: '#ffffff', roughness: 0.95, metalness: 0, side: THREE.DoubleSide });
  const uniforms = { uTime: { value: 0 } };
  mat.onBeforeCompile = (shader) => {
    shader.uniforms.uTime = uniforms.uTime;
    shader.vertexShader = 'uniform float uTime;\n' + shader.vertexShader;
    shader.vertexShader = shader.vertexShader.replace('#include <begin_vertex>', `
      vec3 transformed = vec3(position);
      #ifdef USE_INSTANCING
        float sway = sin(uTime * 1.35 + instanceMatrix[3].x * 0.31 + instanceMatrix[3].z * 0.22) * 0.075 * max(position.y, 0.0);
        transformed.x += sway;
        transformed.z += sway * 0.35;
      #endif
    `);
  };
  const inst = new THREE.InstancedMesh(geo, mat, count);
  inst.castShadow = false;
  inst.receiveShadow = true;
  const dummy = new THREE.Object3D();
  const color = new THREE.Color();
  let placed = 0;
  for (let i = 0; i < count * 3 && placed < count; i++) {
    const x = (rng() - 0.5) * 168;
    const z = (rng() - 0.5) * 168;
    if (!isClear(x, z, 0.7) || pathDistance(x, z, PATHS[regionId]) < 3.4) continue;
    const y = heightAt(x, z);
    if (y < regionId === 'valdoria' ? -1.1 : -1.5) continue;
    dummy.position.set(x, y, z);
    dummy.rotation.y = rng() * Math.PI;
    const s = 0.55 + rng() * 1.1;
    dummy.scale.set(s, s * (0.7 + rng() * 0.9), s);
    dummy.updateMatrix();
    inst.setMatrixAt(placed, dummy.matrix);
    color.set(pal.grass[Math.floor(rng() * pal.grass.length)]);
    color.offsetHSL(0, 0, (rng() - 0.5) * 0.08);
    inst.setColorAt(placed, color);
    placed++;
  }
  inst.count = placed;
  inst.instanceMatrix.needsUpdate = true;
  if (inst.instanceColor) inst.instanceColor.needsUpdate = true;
  inst.userData.uniforms = uniforms;
  return inst;
}

function makeTrees(regionId, heightAt, count, seed, isClear) {
  const rng = mulberry32(seed);
  const pal = PALETTE[regionId];
  const group = new THREE.Group();
  const dummy = new THREE.Object3D();
  const color = new THREE.Color();
  const trunkGeo = new THREE.CylinderGeometry(0.19, 0.32, 4.2, 7);
  trunkGeo.translate(0, 2.1, 0);
  const trunkMat = makeMat(pal.trunk, { roughness: 1 });
  const trunks = new THREE.InstancedMesh(trunkGeo, trunkMat, count);
  trunks.castShadow = true; trunks.receiveShadow = true;
  const canopyGeo = new THREE.IcosahedronGeometry(1.45, 1);
  const canopyMat = makeMat('#ffffff', { roughness: 0.95, flat: true });
  const canopy = new THREE.InstancedMesh(canopyGeo, canopyMat, count * 3);
  canopy.castShadow = true; canopy.receiveShadow = true;
  let n = 0, c = 0;
  for (let attempt = 0; attempt < count * 12 && n < count; attempt++) {
    const x = (rng() - 0.5) * 168;
    const z = (rng() - 0.5) * 168;
    if (!isClear(x, z, 3.2) || pathDistance(x, z, PATHS[regionId]) < 4.5) continue;
    const y = heightAt(x, z);
    if (y < -1.3) continue;
    const scale = 0.7 + rng() * 1.1;
    dummy.position.set(x, y, z);
    dummy.rotation.y = rng() * Math.PI * 2;
    dummy.scale.set(scale, scale * (0.9 + rng() * 0.35), scale);
    dummy.updateMatrix();
    trunks.setMatrixAt(n, dummy.matrix);
    for (let k = 0; k < 3; k++) {
      const a = rng() * Math.PI * 2;
      const rr = 0.45 + rng() * 0.55;
      dummy.position.set(x + Math.cos(a) * rr * scale, y + (4.1 + rng() * 1.25) * scale, z + Math.sin(a) * rr * scale);
      dummy.rotation.set(rng() * 0.3, rng() * Math.PI, rng() * 0.3);
      const cs = (0.72 + rng() * 0.55) * scale;
      dummy.scale.set(cs * (0.9 + rng() * 0.3), cs * (0.8 + rng() * 0.4), cs);
      dummy.updateMatrix();
      canopy.setMatrixAt(c, dummy.matrix);
      color.set(pal.canopy[Math.floor(rng() * pal.canopy.length)]);
      color.offsetHSL(0, 0, (rng() - 0.5) * 0.07);
      canopy.setColorAt(c, color);
      c++;
    }
    n++;
    group.userData.colliders ??= [];
    group.userData.colliders.push({ x, z, r: 0.55 * scale });
  }
  trunks.count = n; canopy.count = c;
  trunks.instanceMatrix.needsUpdate = true; canopy.instanceMatrix.needsUpdate = true;
  if (canopy.instanceColor) canopy.instanceColor.needsUpdate = true;
  group.add(trunks, canopy);
  return group;
}

function makeRocks(regionId, heightAt, count, seed, isClear) {
  const rng = mulberry32(seed);
  const pal = PALETTE[regionId];
  const geo = new THREE.DodecahedronGeometry(1, 0);
  const mat = makeMat(pal.rock, { roughness: 0.98, flat: true });
  const inst = new THREE.InstancedMesh(geo, mat, count);
  inst.castShadow = true; inst.receiveShadow = true;
  const dummy = new THREE.Object3D();
  let n = 0;
  const colliders = [];
  for (let attempt = 0; attempt < count * 10 && n < count; attempt++) {
    const x = (rng() - 0.5) * 170;
    const z = (rng() - 0.5) * 170;
    if (!isClear(x, z, 2.4) || pathDistance(x, z, PATHS[regionId]) < 3.2) continue;
    const y = heightAt(x, z);
    const s = 0.45 + rng() * 2.2;
    dummy.position.set(x, y + s * 0.22, z);
    dummy.rotation.set(rng() * Math.PI, rng() * Math.PI, rng() * Math.PI);
    dummy.scale.set(s * (0.8 + rng() * 0.5), s * (0.55 + rng() * 0.45), s);
    dummy.updateMatrix();
    inst.setMatrixAt(n, dummy.matrix);
    if (s > 1.2) colliders.push({ x, z, r: s * 0.5 });
    n++;
  }
  inst.count = n;
  inst.instanceMatrix.needsUpdate = true;
  inst.userData.colliders = colliders;
  return inst;
}

function makeFlowers(regionId, heightAt, count, seed, isClear) {
  const rng = mulberry32(seed);
  const pal = PALETTE[regionId];
  const geo = new THREE.IcosahedronGeometry(0.065, 0);
  const mat = new THREE.MeshStandardMaterial({ color: '#ffffff', emissive: '#ffffff', emissiveIntensity: 0.25, roughness: 0.5 });
  const inst = new THREE.InstancedMesh(geo, mat, count);
  const dummy = new THREE.Object3D();
  const color = new THREE.Color();
  let n = 0;
  for (let attempt = 0; attempt < count * 8 && n < count; attempt++) {
    const x = (rng() - 0.5) * 150;
    const z = (rng() - 0.5) * 150;
    if (!isClear(x, z, 1) || pathDistance(x, z, PATHS[regionId]) < 2.7) continue;
    const y = heightAt(x, z);
    if (y < -1) continue;
    dummy.position.set(x, y + 0.35 + rng() * 0.25, z);
    const s = 0.65 + rng() * 1.3;
    dummy.scale.setScalar(s);
    dummy.updateMatrix();
    inst.setMatrixAt(n, dummy.matrix);
    color.set(pal.flower[Math.floor(rng() * pal.flower.length)]);
    inst.setColorAt(n, color);
    n++;
  }
  inst.count = n;
  inst.instanceMatrix.needsUpdate = true;
  if (inst.instanceColor) inst.instanceColor.needsUpdate = true;
  return inst;
}

function makeHouse(x, z, rot, scale, y) {
  const group = new THREE.Group();
  const wall = makeMat('#c9b28e', { roughness: 0.95 });
  const wood = makeMat('#5b4030', { roughness: 0.95 });
  const roof = makeMat('#5b3a32', { roughness: 0.92, flat: true });
  const glow = new THREE.MeshBasicMaterial({ color: '#ffd38b' });
  const base = mesh(new THREE.BoxGeometry(4.4, 2.8, 3.7), wall, [0, 1.4, 0]);
  group.add(base);
  // timber frame
  for (const sx of [-2.2, 2.2]) group.add(mesh(new THREE.BoxGeometry(0.16, 2.9, 0.16), wood, [sx, 1.45, 1.86]));
  for (const zz of [-1.85, 1.85]) group.add(mesh(new THREE.BoxGeometry(4.45, 0.14, 0.15), wood, [0, 1.05, zz]));
  group.add(mesh(new THREE.BoxGeometry(4.7, 0.16, 4), wood, [0, 2.82, 0]));
  // roof
  const roofMesh = mesh(new THREE.ConeGeometry(3.7, 2.4, 4), roof, [0, 4, 0], [0, Math.PI / 4, 0]);
  group.add(roofMesh);
  // door
  group.add(mesh(new THREE.BoxGeometry(0.85, 1.65, 0.12), wood, [0, 0.82, 1.89]));
  group.add(mesh(new THREE.SphereGeometry(0.04, 6, 4), makeMat('#d9b56e', { metalness: 0.8 }), [0.27, 0.82, 1.97]));
  // windows
  for (const sx of [-1.3, 1.3]) {
    group.add(mesh(new THREE.BoxGeometry(0.65, 0.55, 0.08), glow, [sx, 1.65, 1.9]));
    group.add(mesh(new THREE.BoxGeometry(0.75, 0.08, 0.13), wood, [sx, 1.65, 1.93]));
    group.add(mesh(new THREE.BoxGeometry(0.08, 0.65, 0.13), wood, [sx, 1.65, 1.93]));
  }
  // chimney
  group.add(mesh(new THREE.BoxGeometry(0.55, 1.8, 0.55), makeMat('#8c7c6c'), [1.25, 4.2, -0.55]));
  group.add(mesh(new THREE.BoxGeometry(0.7, 0.16, 0.7), makeMat('#61554a'), [1.25, 5.05, -0.55]));
  // banner
  group.add(mesh(new THREE.BoxGeometry(0.06, 2.2, 0.06), wood, [-2.65, 1.9, 1.4]));
  const banner = mesh(new THREE.PlaneGeometry(0.75, 1.2), makeMat('#37655e', { side: THREE.DoubleSide }), [-2.3, 2.35, 1.4], [0, 0.1, 0.06]);
  group.add(banner);
  group.add(mesh(new THREE.PlaneGeometry(0.3, 0.3), new THREE.MeshBasicMaterial({ color: '#e5c17c', side: THREE.DoubleSide }), [-2.3, 2.35, 1.405], [0, 0.1, 0.06]));
  group.position.set(x, y, z);
  group.rotation.y = rot;
  group.scale.setScalar(scale);
  group.traverse((o) => { if (o.isMesh) { o.castShadow = true; o.receiveShadow = true; } });
  return group;
}

function makeWindmill(x, z, y) {
  const group = new THREE.Group();
  const stone = makeMat('#b7a98d', { roughness: 0.95 });
  const wood = makeMat('#604535');
