  if (regionId === 'kansordore') spawn.y = heightAt(0, -55);

  const world = {
    id: regionId,
    region,
    group,
    scene,
    heightAt,
    colliders,
    interactables,
    poi,
    creatureSpawns,
    markers,
    spawn,
    portal,
    portalGlows,
    altar,
    rifts,
    seals,
    shards,
    runeRings,
    fires,
    windmills,
    water,
    particles,
    sky,
    clouds,
    terrain,
    bounds: 88,
    bossTrigger: regionId === 'valdoria' ? { x: -32, z: 38, r: 12 } : regionId === 'drakmore' ? { x: 0, z: 44, r: 13 } : { x: 0, z: 22, r: 10 },
    hazardAt: (x, z) => heightAt(x, z) < region.water.level + 0.28,
    setRiftCleansed(index) {
      const rift = rifts[index];
      if (rift) setRiftVisual(rift, true);
      const it = interactables.find((o) => o.id === `rift-${index}`);
      if (it) { it.disabled = true; it.marker.visible = false; }
      const p = poi.find((o) => o.label === `Foco de corrupción ${index + 1}`);
      if (p) p.type = 'done';
    },
    setSealBroken(index) {
      const seal = seals[index];
      if (seal) setSealVisual(seal, true);
      const it = interactables.find((o) => o.id === `seal-${index}` || o.id === `primordial-${index}`);
      if (it) { it.disabled = true; it.marker.visible = false; }
      const p = poi.find((o) => o.label.includes('Sello') && o.label.includes(String(index + 1)));
      if (p) p.type = 'done';
    },
    openPortal() {
      for (const p of portalGlows) {
        p.userData.active = true;
        p.userData.light.intensity = 16;
        p.userData.disc.material.opacity = 0.9;
      }
      const it = interactables.find((o) => o.type === 'portal');
      if (it) { it.disabled = false; it.marker.visible = true; it.label = regionId === 'valdoria' ? 'Atravesar la Puerta de Drakmore' : 'Cruzar a Kansordore'; }
    },
    getNpc(kind) {
      const it = interactables.find((o) => o.id === kind);
      if (!it) return null;
      return group.children.find((c) => c.userData.kind === kind);
    },
    update(dt, time) {
      sky.userData.skyMat.uniforms.uTime.value = time;
      water.userData.mat.uniforms.uTime.value = time;
      particles.userData.mat.uniforms.uTime.value = time;
      grass.userData.uniforms.uTime.value = time;
      clouds.children.forEach((c) => { c.position.x += c.userData.drift * dt; if (c.position.x > 190) c.position.x = -190; });
      for (const f of fires) {
        if (!f) continue;
        const flicker = 0.85 + Math.sin(time * 12 + Math.sin(time * 3)) * 0.15;
        if (f.flame) f.flame.scale.set(0.85 + flicker * 0.15, flicker, 0.85 + flicker * 0.15);
        if (f.light) f.light.intensity = 7 + flicker * 4;
      }
      for (const w of windmills) {
        const blades = w.userData.blades;
        if (blades) blades.rotation.z += dt * 0.35;
      }
      for (const r of rifts) {
        if (!r.userData.cleansed) {
          r.userData.core.rotation.y += dt * 0.6;
          r.userData.core.position.y = 1.35 + Math.sin(time * 2 + r.userData.index) * 0.12;
          r.userData.ring.rotation.z += dt * 0.4;
        }
      }
      for (const s of seals) {
        if (!s.userData.broken) {
          s.userData.orb.rotation.y += dt * 0.5;
          s.userData.orb.position.y = 3.8 + Math.sin(time * 2.2 + s.userData.index) * 0.1;
          s.userData.ring.rotation.z += dt * 0.2;
        }
      }
      for (const s of shards) {
        s.position.y = s.userData.baseY + Math.sin(time * 1.2 + s.userData.phase) * 0.35;
        s.rotation.y += dt * 0.4;
      }
      for (const ring of runeRings) {
        if (ring?.userData?.spin) ring.rotation.z += dt * ring.userData.spin;
      }
      for (const p of portalGlows) {
        if (p.userData.active) {
          p.userData.disc.material.opacity = 0.72 + Math.sin(time * 2.2) * 0.14;
          p.userData.swirl.rotation.z += dt * 0.7;
          p.userData.runes.rotation.z += dt * 0.25;
          p.userData.light.intensity = 13 + Math.sin(time * 2.4) * 4;
        }
      }
      if (village?.userData?.shrineCrystal) {
        village.userData.shrineCrystal.rotation.y += dt * 0.7;
        village.userData.shrineCrystal.position.y = 2.35 + Math.sin(time * 2) * 0.1;
      }
      if (temple?.userData?.rings) {
        for (const r of temple.userData.rings) r.rotation.z += dt * r.userData.spin;
      }
      // NPC idle
      const npcGroup = group.children.find((c) => c.userData.actor && c.userData.kind !== 'testigo');
      if (npcGroup?.userData.actor?.userData.rig) poseHero(npcGroup.userData.actor, { speed: 0 }, dt, time);
      const testigo = group.children.find((c) => c.userData.kind === 'testigo');
      if (testigo?.userData.actor) {
        testigo.userData.actor.position.y = Math.sin(time * 1.2) * 0.05;
        testigo.userData.actor.rotation.y = Math.sin(time * 0.4) * 0.15;
      }
      for (const m of markers) {
        m.position.y = m.userData.baseY + Math.sin(time * 1.8 + m.userData.phase) * 0.12;
        m.material.opacity = 0.65 + Math.sin(time * 2 + m.userData.phase) * 0.2;
      }
    },
    dispose() {
      scene.remove(group);
      disposeObject(group);
      scene.fog = null;
    },
  };

  // mark boss trigger POI maybe
  return world;
}

function setRiftVisual(rift, cleansed) {
  rift.userData.cleansed = cleansed;
  if (cleansed) {
    rift.userData.core.material.color.set('#b8f3e8');
    rift.userData.core.material.emissive.set('#7de0d3');
    rift.userData.core.material.emissiveIntensity = 1.2;
    rift.userData.ring.material.color.set('#8fe8dd');
    rift.userData.light.color.set('#8fe8dd');
    rift.userData.light.intensity = 2;
  }
}

function setSealVisual(seal, broken) {
  seal.userData.broken = broken;
  if (broken) {
    seal.userData.orb.material.color.set('#9df1e9');
    seal.userData.orb.material.opacity = 0.2;
    seal.userData.ring.material.color.set('#9df1e9');
    seal.userData.ring.material.opacity = 0.2;
    seal.userData.light.color.set('#9df1e9');
    seal.userData.light.intensity = 1.5;
    seal.userData.orb.scale.setScalar(0.4);
  }
}

export function setWorldQuality(world, quality) {
  // reserved for runtime quality changes; world is rebuilt by the game when needed
  return world;
}

import * as THREE from 'three';
import { createHero, poseHero } from './character.js';
import { clamp, damp, dampAngle, dist2D, mulberry32, noise2D } from '../core/utils.js';

const mat = (color, opts = {}) => new THREE.MeshStandardMaterial({
  color: new THREE.Color(color),
  roughness: opts.roughness ?? 0.78,
  metalness: opts.metalness ?? 0.15,
  emissive: new THREE.Color(opts.emissive || '#000000'),
  emissiveIntensity: opts.emissiveIntensity ?? 1,
  flatShading: opts.flat ?? false,
  transparent: opts.transparent ?? false,
  opacity: opts.opacity ?? 1,
  side: opts.side ?? THREE.FrontSide,
});

function m(geo, material, pos = [0, 0, 0], rot = [0, 0, 0], scale = [1, 1, 1]) {
  const mesh = new THREE.Mesh(geo, material);
  mesh.position.set(...pos);
  mesh.rotation.set(...rot);
  mesh.scale.set(...scale);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  return mesh;
}

const REGION_ENEMY = {
  valdoria: { dark: '#20222b', cloth: '#3a3536', metal: '#4b4d52', glow: '#c58cff', eye: '#e8b7ff', accent: '#7a4f9e' },
  drakmor: { dark: '#241a1b', cloth: '#452520', metal: '#57433c', glow: '#ff7336', eye: '#ffd19a', accent: '#ff5c2d' },
  kansordore: { dark: '#211f33', cloth: '#343052', metal: '#6a6282', glow: '#c7b2ff', eye: '#f0e7ff', accent: '#8b78c9' },
};

function createHumanoid(type, region, boss = false) {
  const pal = REGION_ENEMY[region] || REGION_ENEMY.valdoria;
  const group = new THREE.Group();
  const outfit = { primary: pal.cloth, secondary: pal.dark, trim: pal.metal, metal: pal.metal };
  const actor = createHero({ skin: '#514b50', hairColor: pal.dark, hairStyle: 'wild', outfit });
  actor.scale.setScalar(boss ? 1.85 : 1.04);
  const rig = actor.userData.rig;
  rig.sword.visible = false;
  rig.aura.visible = false;
  // remove heroic circlet glow and face warmth
  rig.materials.eyeMat.color.set('#160f18');
  rig.materials.eyeMat.emissive.set(pal.eye);
  rig.materials.eyeMat.emissiveIntensity = 2.4;
  rig.materials.glowMat.color.set(pal.glow);
  rig.materials.glowMat.opacity = 0.95;
  // darken skin, add cracks
  rig.materials.skinMat.color.set('#4b4148');
  rig.materials.skinMat.roughness = 0.9;
  // horns
  const hornMat = mat('#2d282d', { roughness: 0.7, metalness: 0.2 });
  for (const s of [-1, 1]) {
    const horn = m(new THREE.ConeGeometry(boss ? 0.09 : 0.055, boss ? 0.62 : 0.38, 6), hornMat, [s * 0.15, 0.18, 0.01], [0.1, 0, s * -0.45]);
    rig.head.add(horn);
  }
  // shoulder spikes
  for (const s of [-1, 1]) {
    rig.torso.add(m(new THREE.ConeGeometry(boss ? 0.11 : 0.06, boss ? 0.48 : 0.28, 5), hornMat, [s * 0.38, 0.24, 0], [0, 0, s * -0.4]));
  }
  // glowing chest crack
  const crackMat = new THREE.MeshBasicMaterial({ color: pal.glow, transparent: true, opacity: 0.8, blending: THREE.AdditiveBlending });
  const crack = m(new THREE.BoxGeometry(0.035, boss ? 0.42 : 0.24, 0.02), crackMat, [0.02, 0.05, boss ? 0.25 : 0.205]);
  crack.rotation.z = 0.35;
  rig.torso.add(crack);
  const crack2 = m(new THREE.BoxGeometry(0.025, boss ? 0.2 : 0.14, 0.02), crackMat, [-0.08, -0.02, boss ? 0.25 : 0.205]);
  crack2.rotation.z = -0.6;
  rig.torso.add(crack2);
  // dark sword
  const sword = new THREE.Group();
  const bladeMat = mat(pal.metal, { metalness: 0.8, roughness: 0.28, emissive: pal.glow, emissiveIntensity: 0.4 });
  const blade = m(new THREE.BoxGeometry(boss ? 0.2 : 0.1, boss ? 1.9 : 1.25, boss ? 0.05 : 0.035), bladeMat, [0, boss ? 1.0 : 0.68, 0]);
  sword.add(blade);
  const tip = m(new THREE.ConeGeometry(boss ? 0.1 : 0.05, boss ? 0.35 : 0.25, 4), bladeMat, [0, boss ? 1.95 : 1.3, 0], [0, 0, Math.PI / 4]);
  sword.add(tip);
  sword.add(m(new THREE.BoxGeometry(boss ? 0.65 : 0.42, 0.08, 0.11), mat(pal.metal, { metalness: 0.8 }), [0, boss ? 0.05 : 0.04, 0]));
  sword.add(m(new THREE.CylinderGeometry(0.04, 0.045, 0.35, 6), mat('#2b2020'), [0, boss ? -0.13 : -0.12, 0]));
  sword.position.set(0, -0.7, 0.02);
  sword.rotation.x = Math.PI;
  rig.rightArm.add(sword);
  rig.sword = sword;
  // crown for boss
  if (boss) {
    const crown = new THREE.Group();
    crown.position.y = 0.18;
    for (let i = 0; i < 5; i++) {
      const a = (i / 5) * Math.PI * 2;
      crown.add(m(new THREE.ConeGeometry(0.05, 0.25, 4), mat('#c39b52', { metalness: 0.85, roughness: 0.28 }), [Math.cos(a) * 0.16, 0.1, Math.sin(a) * 0.16]));
    }
    crown.add(m(new THREE.TorusGeometry(0.17, 0.018, 4, 16), mat('#c39b52', { metalness: 0.9, roughness: 0.2 }), [0, 0, 0], [Math.PI / 2, 0, 0]));
    rig.head.add(crown);
  }
  group.add(actor);
  group.userData = { type: 'enemy', kind: type, actor, rig, boss, pal, phase: 0 };
  return group;
}

function createWraith(region, elite = false) {
  const pal = REGION_ENEMY[region] || REGION_ENEMY.valdoria;
  const group = new THREE.Group();
  const body = new THREE.Group();
  group.add(body);
  const cloth = mat(pal.dark, { transparent: true, opacity: 0.9, side: THREE.DoubleSide, roughness: 0.95 });
  const cloth2 = mat(pal.cloth, { transparent: true, opacity: 0.85, side: THREE.DoubleSide });
  const glow = new THREE.MeshBasicMaterial({ color: pal.glow, transparent: true, opacity: 0.8, blending: THREE.AdditiveBlending });
  const eye = new THREE.MeshBasicMaterial({ color: pal.eye, transparent: true, opacity: 0.95, blending: THREE.AdditiveBlending });
  body.add(m(new THREE.ConeGeometry(0.55, 1.8, 7, 1, true), cloth, [0, 1.0, 0]));
  body.add(m(new THREE.ConeGeometry(0.42, 1.35, 7, 1, true), cloth2, [0, 1.15, 0.05], [0, 0.3, 0]));
  body.add(m(new THREE.SphereGeometry(0.26, 12, 9), cloth, [0, 1.9, 0.02]));
  body.add(m(new THREE.SphereGeometry(0.2, 10, 8), mat('#0c0b11'), [0, 1.87, 0.14], [0, 0, 0], [1, 1.1, 0.55]));
  body.add(m(new THREE.SphereGeometry(0.03, 6, 4), eye, [-0.07, 1.91, 0.31]));
  body.add(m(new THREE.SphereGeometry(0.03, 6, 4), eye, [0.07, 1.91, 0.31]));
  body.add(m(new THREE.TorusGeometry(0.34, 0.012, 4, 20), glow, [0, 1.9, 0.02], [Math.PI / 2, 0, 0]));
  for (let i = 0; i < 5; i++) {
    const a = (i / 5) * Math.PI * 2;
    body.add(m(new THREE.ConeGeometry(0.04, 0.45, 4), cloth2, [Math.cos(a) * 0.28, 0.35, Math.sin(a) * 0.28], [Math.sin(a) * 0.4, 0, Math.cos(a) * 0.4]));
  }
  if (elite) {
    body.add(m(new THREE.TorusGeometry(0.5, 0.018, 4, 28), glow, [0, 0.5, 0], [Math.PI / 2, 0, 0]));
    body.scale.setScalar(1.2);
  }
  group.userData = { type: 'enemy', kind: 'wraith', actor: body, boss: false, pal, phase: 0, elite };
  return group;
}

function createGolem(region, elite = false) {
  const pal = REGION_ENEMY[region] || REGION_ENEMY.valdoria;
  const group = new THREE.Group();
  const body = new THREE.Group();
  group.add(body);
  const rock = mat(pal.metal, { roughness: 0.98, flat: true });
  const rockDark = mat(pal.dark, { roughness: 1, flat: true });
  const glow = new THREE.MeshBasicMaterial({ color: pal.glow, transparent: true, opacity: 0.85, blending: THREE.AdditiveBlending });
  body.add(m(new THREE.DodecahedronGeometry(0.65, 0), rock, [0, 1.0, 0], [0, 0.4, 0], [1.1, 1.2, 0.8]));
  body.add(m(new THREE.DodecahedronGeometry(0.36, 0), rockDark, [0, 1.75, 0], [0.2, 0, 0]));
  body.add(m(new THREE.BoxGeometry(0.15, 0.08, 0.05), glow, [-0.12, 1.78, 0.32]));
  body.add(m(new THREE.BoxGeometry(0.15, 0.08, 0.05), glow, [0.12, 1.78, 0.32]));
  for (const s of [-1, 1]) {
    body.add(m(new THREE.DodecahedronGeometry(0.24, 0), rock, [s * 0.75, 1.1, 0], [0, 0, s * 0.3], [1, 1.4, 1]));
    body.add(m(new THREE.DodecahedronGeometry(0.2, 0), rockDark, [s * 0.42, 0.35, 0]));
    body.add(m(new THREE.BoxGeometry(0.08, 0.65, 0.08), glow, [s * 0.55, 0.9, 0.1], [0, 0, s * 0.4]));
  }
  for (let i = 0; i < 4; i++) body.add(m(new THREE.ConeGeometry(0.08, 0.3, 4), glow, [0, 1.3 + i * 0.1, 0.42], [0, 0, 0]));
  if (elite) body.scale.setScalar(1.25);
  group.userData = { type: 'enemy', kind: 'golem', actor: body, boss: false, pal, phase: 0, elite };
  return group;
}

export function createEnemyMesh(type, region, elite = false, boss = false) {
  if (type === 'wraith') return createWraith(region, elite);
  if (type === 'golem') return createGolem(region, elite);
  return createHumanoid(type, region, boss);
}

export class Enemy {
  constructor({ type, region, x, z, elite = false, boss = false, chapter = 0, name, id, y = 0, bossType = null }) {
    this.id = id || `enemy-${Math.random().toString(36).slice(2, 8)}`;
    this.type = type;
    this.region = region;
    this.elite = elite;
    this.boss = boss;
    this.bossType = bossType;
    this.name = name || (boss ? 'Guardián' : type === 'wraith' ? 'Espectro de Ceniza' : type === 'golem' ? 'Gólem del Velo' : 'Corrupto');
    this.level = 1 + chapter * 3 + (elite ? 2 : 0) + (boss ? 5 : 0);
    const scale = 1 + chapter * 0.55;
    const baseHp = type === 'wraith' ? 42 : type === 'golem' ? 88 : 62;
    this.maxHp = Math.round((baseHp + (elite ? 40 : 0) + (boss ? 420 : 0)) * scale);
    this.hp = this.maxHp;
    this.damage = (type === 'wraith' ? 9 : type === 'golem' ? 14 : 11) * (1 + chapter * 0.32) * (elite ? 1.3 : 1) * (boss ? 1.45 : 1);
    this.speed = (type === 'wraith' ? 3.1 : type === 'golem' ? 2.2 : 3.6) * (boss ? 0.95 : 1);
    this.radius = boss ? 1.15 : type === 'golem' ? 0.8 : 0.55;
    this.aggro = boss ? 24 : type === 'wraith' ? 15 : 13;
    this.attackRange = type === 'wraith' ? 9 : boss ? 3.8 : 2.4;
    this.xp = Math.round((elite ? 42 : boss ? 280 : 18) * (1 + chapter * 0.55));
    this.mesh = createEnemyMesh(type, region, elite, boss);
    this.mesh.position.set(x, y, z);
    this.mesh.userData.enemy = this;
    this.spawn = { x, z };
    this.state = 'idle';
    this.stateTimer = 0;
    this.attackCooldown = 1.2 + Math.random();
    this.attackIndex = 0;
    this.stagger = 0;
    this.hitFlash = 0;
    this.deadTime = 0;
    this.phase = 0;
    this.wanderAngle = Math.random() * Math.PI * 2;
    this.wanderTimer = 0;
    this.active = false;
    this.telegraph = null;
    this.facing = Math.random() * Math.PI * 2;
    this.animPhase = 0;
    this.lastDamageSource = null;
    this.captureThreshold = 0.25;
    this.capturable = false;
    this.isBoss = boss;
  }

  get alive() { return this.state !== 'dead'; }
  get hpRatio() { return clamp(this.hp / this.maxHp, 0, 1); }

  update(dt, game) {
    if (this.state === 'dead') {
      this.deadTime += dt;
      this.mesh.position.y -= dt * 0.25;
      this.mesh.rotation.z += dt * 0.25;
      this.mesh.traverse((o) => {
        if (o.isMesh && o.material) {
          o.material.transparent = true;
          o.material.opacity = Math.max(0, 1 - this.deadTime * 0.65);
        }
      });
      if (this.deadTime > 1.8 && this.mesh.parent) game.scene.remove(this.mesh);
      return;
    }
    const player = game.player;
    const px = player.position.x, pz = player.position.z;
    const dist = Math.hypot(px - this.mesh.position.x, pz - this.mesh.position.z);
    this.active = this.active || dist < this.aggro;
    this.attackCooldown -= dt;
    this.hitFlash = Math.max(0, this.hitFlash - dt);
    this.animPhase += dt * (this.state === 'chase' ? this.speed * 1.8 : 1.2);
    if (this.stagger > 0) {
      this.stagger -= dt;
      this.state = 'stagger';
      this.updateVisual(dt, game, 0);
      if (this.stagger <= 0) this.state = 'chase';
      return;
    }

    if (this.state === 'idle') {
      this.wanderTimer -= dt;
      if (this.wanderTimer <= 0) {
        this.wanderTimer = 2 + Math.random() * 3;
        this.wanderAngle = Math.random() * Math.PI * 2;
      }
      if (dist < this.aggro) {
        this.state = 'chase';
        game.onEnemyAggro?.(this);
      } else {
        const tx = this.spawn.x + Math.cos(this.wanderAngle) * 1.5;
        const tz = this.spawn.z + Math.sin(this.wanderAngle) * 1.5;
        if (Math.hypot(tx - this.mesh.position.x, tz - this.mesh.position.z) > 0.5) {
          this.moveTowards(tx, tz, this.speed * 0.22, dt, game);
        }
        this.updateVisual(dt, game, 0.2);
        return;
      }
    }

    if (this.state === 'chase') {
      if (dist > this.aggro * 1.8) {
        this.state = 'idle';
        this.updateVisual(dt, game, 0);
        return;
      }
      this.faceTowards(px, pz, dt, 7);
      if (this.attackCooldown <= 0 && dist <= this.attackRange) {
        this.state = 'windup';
        this.stateTimer = this.boss ? 0.65 : 0.55;
        this.attackIndex++;
        game.audio.arrow?.();
        this.showTelegraph(game, this.boss ? 4.5 : this.attackRange + 0.5);
      } else {
        const stopDistance = this.type === 'wraith' ? 6.5 : this.attackRange * 0.78;
        if (dist > stopDistance) this.moveTowards(px, pz, this.speed, dt, game);
        else if (this.type === 'wraith') this.strafe(dt, game);
        this.updateVisual(dt, game, 1);
      }
    } else if (this.state === 'windup') {
      this.stateTimer -= dt;
      this.faceTowards(px, pz, dt, 5);
      this.updateVisual(dt, game, 0.1);
      if (this.stateTimer <= 0) {
        this.strike(game, dist);
        this.state = 'recover';
        this.stateTimer = this.boss ? 0.9 : 0.65;
        this.attackCooldown = this.boss ? 1.0 + Math.random() * 0.8 : 1.5 + Math.random();
      }
    } else if (this.state === 'recover') {
      this.stateTimer -= dt;
      this.updateVisual(dt, game, 0);
      if (this.stateTimer <= 0) this.state = 'chase';
    }

    // boss phase
    if (this.boss && this.phase === 0 && this.hpRatio < 0.55) {
      this.phase = 1;
      this.speed *= 1.22;
      this.damage *= 1.18;
      game.onBossPhase?.(this);
    }
  }

  moveTowards(tx, tz, speed, dt, game) {
    const dx = tx - this.mesh.position.x, dz = tz - this.mesh.position.z;
    const d = Math.hypot(dx, dz);
    if (d < 0.01) return;
    const nx = dx / d, nz = dz / d;
    let mx = this.mesh.position.x + nx * speed * dt;
    let mz = this.mesh.position.z + nz * speed * dt;
    for (const c of game.world.colliders) {
      const dx2 = mx - c.x, dz2 = mz - c.z;
      const dd = Math.hypot(dx2, dz2);
      if (dd < c.r + this.radius * 0.7) {
        const push = (c.r + this.radius * 0.7 - dd) / Math.max(dd, 0.001);
        mx += dx2 * push;
        mz += dz2 * push;
      }
    }
    const maxR = game.world.bounds;
    if (Math.hypot(mx, mz) > maxR) {
      const k = maxR / Math.hypot(mx, mz);
      mx *= k; mz *= k;
    }
    this.mesh.position.x = mx;
    this.mesh.position.z = mz;
    this.mesh.position.y = game.world.heightAt(mx, mz);
  }

  strafe(dt, game) {
    const a = Math.atan2(game.player.position.x - this.mesh.position.x, game.player.position.z - this.mesh.position.z);
    const side = this.attackIndex % 2 ? 1 : -1;
    this.moveTowards(this.mesh.position.x + Math.cos(a) * side * 4, this.mesh.position.z - Math.sin(a) * side * 4, this.speed * 0.5, dt, game);
  }

  faceTowards(tx, tz, dt, speed) {
    const target = Math.atan2(tx - this.mesh.position.x, tz - this.mesh.position.z);
    this.facing = dampAngle(this.facing, target, speed, dt);
    this.mesh.rotation.y = this.facing;
  }

  showTelegraph(game, radius) {
    const color = this.boss ? '#ff5d4e' : this.type === 'wraith' ? '#c28bff' : '#ff9a62';
    const geo = new THREE.RingGeometry(0.25, radius, 40);
    const material = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.45, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending });
    const ring = new THREE.Mesh(geo, material);
    ring.rotation.x = -Math.PI / 2;
    ring.position.set(this.mesh.position.x, game.world.heightAt(this.mesh.position.x, this.mesh.position.z) + 0.08, this.mesh.position.z);
    game.scene.add(ring);
    this.telegraph = { mesh: ring, life: this.boss ? 0.65 : 0.55, maxLife: this.boss ? 0.65 : 0.55, radius };
  }

  strike(game, dist) {
    const player = game.player;
    const d = dist2D(this.mesh.position, player.position);
    if (this.type === 'wraith') {
      const dir = new THREE.Vector3(player.position.x - this.mesh.position.x, 0, player.position.z - this.mesh.position.z).normalize();
      game.spawnEnemyProjectile({
        x: this.mesh.position.x, y: this.mesh.position.y + 1.45, z: this.mesh.position.z,
        dir, damage: this.damage * 0.85, color: this.boss ? '#ff8a62' : '#c79bff', speed: 10,
        radius: 0.45,
      });
      game.audio.arrow();
    } else if (this.boss) {
      if (this.attackIndex % 3 === 0) {
        game.spawnShockwave({ x: this.mesh.position.x, z: this.mesh.position.z, radius: 5.4, damage: this.damage * 1.25, color: '#ff7b5e', delay: 0.18 });
      } else if (this.attackIndex % 3 === 1) {
        // dash
        const dx = player.position.x - this.mesh.position.x, dz = player.position.z - this.mesh.position.z;
        const len = Math.hypot(dx, dz) || 1;
        const tx = this.mesh.position.x + dx / len * 4.4;
        const tz = this.mesh.position.z + dz / len * 4.4;
        game.spawnSlashTrail(this.mesh.position, this.facing, '#ff7b5e', 1.7);
        this.mesh.position.x = tx; this.mesh.position.z = tz;
        this.mesh.position.y = game.world.heightAt(tx, tz);
        if (Math.hypot(player.position.x - tx, player.position.z - tz) < 2.8) game.damagePlayer(this.damage * 1.1, this);
        game.shake(0.3);
      } else {
        for (let i = -1; i <= 1; i++) {
          const a = this.facing + i * 0.3;
          game.spawnEnemyProjectile({
            x: this.mesh.position.x, y: this.mesh.position.y + 1.8, z: this.mesh.position.z,
            dir: new THREE.Vector3(Math.sin(a), 0, Math.cos(a)), damage: this.damage * 0.7, color: '#ff9a62', speed: 9, radius: 0.55,
          });
        }
      }
      game.audio.bossRoar?.();
    } else if (d < this.attackRange + 0.7) {
      game.damagePlayer(this.damage, this);
      game.spawnSlashTrail(this.mesh.position, this.facing, this.elite ? '#ffb35c' : '#c49bff', 1.1);
    }
    if (this.telegraph) {
      game.scene.remove(this.telegraph.mesh);
      this.telegraph.mesh.geometry.dispose();
      this.telegraph.mesh.material.dispose();
      this.telegraph = null;
    }
  }

  updateVisual(dt, game, move) {
    const kind = this.mesh.userData.kind;
    if (kind === 'wraith' || kind === 'golem') {
      const actor = this.mesh.userData.actor;
      actor.position.y = Math.sin(this.animPhase * 2.1) * 0.08 + (kind === 'wraith' ? 0.22 : 0);
      actor.rotation.z = Math.sin(this.animPhase * 1.3) * 0.04;
      if (this.state === 'windup') actor.rotation.x = -0.22;
      else if (this.state === 'stagger') actor.rotation.x = 0.3;
      if (kind === 'golem' && move > 0) actor.rotation.z = Math.sin(this.animPhase * 4) * 0.07;
    } else if (this.mesh.userData.actor) {
      poseHero(this.mesh.userData.actor, {
        speed: move * (this.state === 'chase' ? 1 : 0),
        runPhase: this.animPhase,
        attack: this.state === 'windup' ? clamp(1 - this.stateTimer / (this.boss ? 0.65 : 0.55), 0, 1) : 0,
        attackType: this.boss ? 'heavy' : 'light',
        combo: this.attackIndex,
        hurt: this.hitFlash,
        dead: 0,
      }, dt, game.time + this.animPhase * 0.1);
    }
    if (this.telegraph) {
      this.telegraph.life -= dt;
      const t = clamp(1 - this.telegraph.life / this.telegraph.maxLife, 0, 1);
      this.telegraph.mesh.scale.setScalar(0.35 + t * 0.75);
      this.telegraph.mesh.material.opacity = 0.15 + t * 0.5;
      if (this.telegraph.life <= 0) {
        game.scene.remove(this.telegraph.mesh);
        this.telegraph.mesh.geometry.dispose();
        this.telegraph.mesh.material.dispose();
        this.telegraph = null;
      }
    }
    if (this.hitFlash > 0 && this.mesh.userData.rig) {
      const rig = this.mesh.userData.rig;
      rig.materials.cloth.emissive.set('#ff8a62');
      rig.materials.cloth.emissiveIntensity = 0.55;
    } else if (this.mesh.userData.rig) {
      this.mesh.userData.rig.materials.cloth.emissiveIntensity = 0;
    }
  }

  takeDamage(amount, game, crit = false) {
    if (this.state === 'dead') return 0;
    this.hp -= amount;
    this.hitFlash = 0.18;
    this.active = true;
    if (this.state === 'idle') this.state = 'chase';
    if (this.boss) {
      this.state = 'stagger';
      this.stagger = 0.18;
    } else if (crit || amount > 30) {
      this.state = 'stagger';
      this.stagger = 0.32;
    }
    game.spawnHitSparks(this.mesh.position, crit ? '#ffd08a' : '#ffb18a', crit ? 18 : 10);
    game.audio.hit(crit);
    game.damageNumber(this.mesh.position, Math.round(amount), crit);
    if (this.hp <= 0) {
      this.hp = 0;
      this.die(game);
      return amount;
    }
    if (this.hpRatio < this.captureThreshold && !this.boss) {
      this.capturable = true;
      game.onEnemyWeakened?.(this);
    }
    return amount;
  }

  die(game) {
    this.state = 'dead';
    this.deadTime = 0;
    this.capturable = false;
    if (this.telegraph) {
      game.scene.remove(this.telegraph.mesh);
      this.telegraph.mesh.geometry.dispose();
      this.telegraph.mesh.material.dispose();
      this.telegraph = null;
    }
    game.onEnemyKilled?.(this);
  }
}

import * as THREE from 'three';
import { createHero, poseHero, updateHeroAppearance } from './character.js';
import { clamp, damp, dampAngle, dist2D } from '../core/utils.js';
import { ATTRIBUTES, ITEMS, OUTFITS } from './data.js';

const BASE_STATS = { vit: 3, mana: 2, res: 3, str: 3, def: 3, spd: 3, int: 2, luck: 2 };

export class Player {
  constructor(game, options) {
    this.game = game;
    this.name = options.name || 'Aster';
    this.origin = options.origin;
    this.appearance = {
      skin: options.skin || '#e9c9a8',
      hairColor: options.hairColor || '#d9d5cc',
      hairStyle: options.hairStyle || 'short',
      outfit: options.outfit || OUTFITS[0],
    };
    this.attributes = { ...BASE_STATS };
    for (const [k, v] of Object.entries(options.origin?.base || {})) this.attributes[k] = (this.attributes[k] || 0) + v;
    for (const [k, v] of Object.entries(options.allocated || {})) this.attributes[k] += v;
    this.level = 1;
    this.xp = 0;
    this.nextXp = 70;
    this.gold = 0;
    this.equipment = {
      weapon: ITEMS.filo_alba,
      armor: ITEMS.tunica_valdoria,
      charm: null,
    };
    this.potions = 3;
    this.position = new THREE.Vector3(0, 0, 0);
    this.spawnPoint = { x: 0, z: 0 };
    this.facing = 0;
    this.velocity = new THREE.Vector3();
    this.state = 'idle';
    this.attackTime = 0;
    this.attackDuration = 0;
    this.attackType = 'light';
    this.combo = 0;
    this.comboTimer = 0;
    this.queuedAttack = null;
    this.hitDone = false;
    this.dodgeTime = 0;
    this.dodgeDir = new THREE.Vector3();
    this.dodgeCooldown = 0;
    this.invuln = 0;
    this.hurtFlash = 0;
    this.blocking = false;
    this.blockStart = 0;
    this.blockBroken = 0;
    this.runPhase = 0;
    this.dead = false;
    this.deadTime = 0;
    this.hazardTimer = 0;
    this.combatTimer = 0;
    this.resonanceCooldown = 0;
    this.companionCooldown = 0;
    this.creatureBuffs = {};
    this.derived = {};
    this.mesh = createHero({ ...this.appearance, weaponAppearance: this.equipment.weapon?.appearance });
    this.mesh.position.copy(this.position);
    this.mesh.rotation.y = this.facing;
    this.mesh.userData.actor = this;
    this.recomputeStats();
    this.hp = this.maxHp;
    this.mana = this.maxMana;
    this.stamina = this.maxStamina;
    this.baseMaxHp = this.maxHp;
    this.baseMaxMana = this.maxMana;
    this.baseMaxStamina = this.maxStamina;
  }

  recomputeStats() {
    const a = this.attributes;
    const gear = {
      hp: 0, mana: 0, def: 0, atk: 0, crit: 0, luck: 0, resonance: 0,
      ...Object.values(this.equipment).filter(Boolean).reduce((acc, item) => {
        acc.hp = (acc.hp || 0) + (item.hp || 0);
        acc.mana = (acc.mana || 0) + (item.mana || 0);
        acc.def = (acc.def || 0) + (item.def || 0);
        acc.atk = (acc.atk || 0) + (item.atk || 0);
        acc.crit = (acc.crit || 0) + (item.crit || 0);
        acc.luck = (acc.luck || 0) + (item.luck || 0);
        acc.resonance = (acc.resonance || 0) + (item.resonance || 0);
        return acc;
      }, {}),
    };
    const buff = this.creatureBuffs || {};
    this.maxHp = Math.round((82 + a.vit * 14 + this.level * 7 + gear.hp) * (1 + (buff.hp || 0)));
    this.maxMana = Math.round((30 + a.mana * 6 + this.level * 2 + gear.mana) * (1 + (buff.mana || 0) * 0.01));
    this.maxStamina = Math.round(48 + a.res * 7 + this.level * 1.5);
    this.damage = (7 + a.str * 2.1 + gear.atk + this.level * 1.45) * (1 + (buff.damage || 0));
    this.defense = 2 + a.def * 1.55 + gear.def + this.level * 0.5;
    this.speed = 4.2 + a.spd * 0.13 + (buff.speed || 0);
    this.critChance = clamp(0.045 + a.luck * 0.009 + gear.crit + (buff.crit || 0), 0, 0.75);
    this.resonancePower = clamp(0.35 + a.int * 0.028 + a.luck * 0.007 + gear.resonance + (buff.resonance || 0), 0.1, 1.5);
    this.manaRegen = 1.0 + a.int * 0.12;
    this.derived = {
      hp: this.maxHp, mana: this.maxMana, stamina: this.maxStamina,
      damage: Math.round(this.damage * 10) / 10, defense: Math.round(this.defense * 10) / 10,
      speed: Math.round(this.speed * 10) / 10, crit: Math.round(this.critChance * 100),
      resonance: Math.round(this.resonancePower * 100),
    };
  }

  applyCreatureBuffs(list) {
    this.creatureBuffs = {};
    for (const c of list || []) {
      const st = c.stats || {};
      for (const [k, v] of Object.entries(st)) this.creatureBuffs[k] = (this.creatureBuffs[k] || 0) + v;
    }
    this.recomputeStats();
    this.hp = Math.min(this.hp, this.maxHp);
    this.mana = Math.min(this.mana, this.maxMana);
    this.stamina = Math.min(this.stamina, this.maxStamina);
  }

  placeAt(x, z) {
    this.position.x = x;
    this.position.z = z;
    this.position.y = this.game.world.heightAt(x, z);
    this.mesh.position.copy(this.position);
    this.spawnPoint = { x, z };
  }

  update(dt) {
    if (this.dead) {
      this.deadTime += dt;
      this.hurtFlash = Math.max(0, this.hurtFlash - dt);
      poseHero(this.mesh, { speed: 0, dead: clamp(this.deadTime / 0.7, 0, 1) }, dt, this.game.time);
      return;
    }
    this.combatTimer += dt;
    this.invuln = Math.max(0, this.invuln - dt);
    this.hurtFlash = Math.max(0, this.hurtFlash - dt);
    this.dodgeCooldown = Math.max(0, this.dodgeCooldown - dt);
    this.comboTimer = Math.max(0, this.comboTimer - dt);
    this.resonanceCooldown = Math.max(0, this.resonanceCooldown - dt);
    this.companionCooldown = Math.max(0, this.companionCooldown - dt);
    if (this.comboTimer <= 0 && this.attackTime <= 0) this.combo = 0;

    const input = this.game.input;
    const move = input.getMove();
    const blocking = input.isBlocking() && this.attackTime <= 0 && this.dodgeTime <= 0 && this.blockBroken <= 0;
    if (blocking && !this.blocking) this.blockStart = this.game.time;
    this.blocking = blocking;
    this.blockBroken = Math.max(0, this.blockBroken - dt);

    // stamina and mana regeneration
    const sprinting = input.isSprinting() && move.z !== 0 || input.isSprinting() && move.x !== 0;
    if (!blocking && this.dodgeTime <= 0) {
      this.stamina = Math.min(this.maxStamina, this.stamina + dt * (this.combatTimer > 5 ? 15 : 8));
    }
    if (this.combatTimer > 4) {
      this.mana = Math.min(this.maxMana, this.mana + dt * this.manaRegen * 1.6);
      this.hp = Math.min(this.maxHp, this.hp + dt * (this.maxHp * 0.008));
    } else {
      this.mana = Math.min(this.maxMana, this.mana + dt * this.manaRegen * 0.65);
    }
    if (blocking) {
      this.stamina -= dt * 10;
      if (this.stamina <= 0) {
        this.stamina = 0;
        this.blockBroken = 1.1;
        this.blocking = false;
        this.game.audio.block();
        this.game.toast('Guardia rota', 'Recupera el aliento antes de volver a bloquear.', 'danger');
      }
    }

    // dodge motion
    if (this.dodgeTime > 0) {
      this.dodgeTime -= dt;
      const t = 1 - this.dodgeTime / 0.42;
      const speed = 10.5 * (1 - t * 0.55);
      this.moveBy(this.dodgeDir.x * speed * dt, this.dodgeDir.z * speed * dt);
      this.invuln = Math.max(this.invuln, 0.1);
    } else {
      const moving = Math.hypot(move.x, move.z) > 0.05 && this.attackTime <= 0;
      let speed = this.speed;
      if (blocking) speed *= 0.32;
      if (sprinting && this.stamina > 1) {
        speed *= 1.55;
        this.stamina = Math.max(0, this.stamina - dt * 12);
      }
      if (moving) {
        const yaw = this.game.cameraYaw;
        const wx = Math.sin(yaw) * -move.z + Math.cos(yaw) * move.x;
        const wz = Math.cos(yaw) * -move.z - Math.sin(yaw) * move.x;
        const len = Math.hypot(wx, wz) || 1;
        const dirX = wx / len, dirZ = wz / len;
        this.moveBy(dirX * speed * dt, dirZ * speed * dt);
        if (!this.blocking) {
          const targetFacing = Math.atan2(dirX, dirZ);
          this.facing = dampAngle(this.facing, targetFacing, 12, dt);
        }
        this.runPhase += dt * (sprinting ? 13 : 9);
        this.state = sprinting ? 'sprint' : 'run';
      } else {
        this.state = 'idle';
      }
      if (this.attackTime > 0) {
        this.attackTime -= dt;
        const t = 1 - this.attackTime / this.attackDuration;
        if (!this.hitDone && t >= 0.3) {
          this.hitDone = true;
          this.performHit();
        }
        if (this.attackTime <= 0) {
          this.attackTime = 0;
          if (this.queuedAttack) {
            const q = this.queuedAttack;
            this.queuedAttack = null;
            this.tryAttack(q);
          }
        }
      }
    }

    // hazard
    this.hazardTimer -= dt;
    if (this.hazardTimer <= 0 && this.game.world.hazardAt(this.position.x, this.position.z)) {
      this.hazardTimer = 0.6;
      this.takeDamage(5 + this.level * 0.5, null, { hazard: true, ignoreBlock: true });
    }

    this.position.y = this.game.world.heightAt(this.position.x, this.position.z);
    this.mesh.position.copy(this.position);
    this.mesh.rotation.y = this.facing;
    poseHero(this.mesh, {
      speed: this.state === 'run' || this.state === 'sprint' ? (this.state === 'sprint' ? 1.4 : 1) : 0,
      runPhase: this.runPhase,
      attack: this.attackTime > 0 ? 1 - this.attackTime / this.attackDuration : 0,
      attackType: this.attackType,
      combo: this.combo,
      blocking: this.blocking,
      dodge: this.dodgeTime > 0 ? 1 - this.dodgeTime / 0.42 : 0,
      hurt: this.hurtFlash,
      dead: 0,
    }, dt, this.game.time);
    if (this.hurtFlash > 0) {
      this.mesh.userData.rig.materials.cloth.emissive.set('#ff7d72');
      this.mesh.userData.rig.materials.cloth.emissiveIntensity = 0.45;
    } else {
      this.mesh.userData.rig.materials.cloth.emissiveIntensity = 0;
    }
  }

  moveBy(dx, dz) {
    let nx = this.position.x + dx;
    let nz = this.position.z + dz;
    const world = this.game.world;
    for (const c of world.colliders) {
      const ddx = nx - c.x, ddz = nz - c.z;
      const d = Math.hypot(ddx, ddz);
      const min = c.r + 0.38;
      if (d < min && d > 0.0001) {
        const push = (min - d) / d;
        nx += ddx * push;
        nz += ddz * push;
      }
    }
    const max = world.bounds;
    const d = Math.hypot(nx, nz);
    if (d > max) { nx *= max / d; nz *= max / d; }
    this.position.x = nx;
    this.position.z = nz;
  }

  tryAttack(type = 'light') {
    if (this.dead || this.dodgeTime > 0) return;
    if (this.attackTime > 0) {
      if (this.attackTime < this.attackDuration * 0.65) this.queuedAttack = type;
      return;
    }
    if (this.stamina < (type === 'heavy' ? 20 : 7)) {
      this.game.toast('Sin aguante', 'Espera un instante y vuelve a intentarlo.', 'danger');
      return;
    }
    this.stamina -= type === 'heavy' ? 20 : 7;
    this.attackType = type;
    this.attackDuration = type === 'heavy' ? 0.72 : 0.42;
    this.attackTime = this.attackDuration;
    this.hitDone = false;
    this.combo = (this.combo + 1) % 3;
    this.comboTimer = 1.1;
    this.combatTimer = 0;
    const target = this.game.findAttackTarget();
    if (target) {
      const dx = target.mesh.position.x - this.position.x;
      const dz = target.mesh.position.z - this.position.z;
      this.facing = Math.atan2(dx, dz);
      this.mesh.rotation.y = this.facing;
    }
    if (type === 'heavy') this.game.audio.heavySwing();
    else this.game.audio.swing();
    this.game.onPlayerAttack?.(type);
  }

  performHit() {
    const heavy = this.attackType === 'heavy';
    const range = heavy ? 3.15 : 2.55;
    const arc = heavy ? Math.PI * 0.95 : Math.PI * 0.72;
    const base = this.damage * (heavy ? 2.15 : [1, 1.12, 1.38][this.combo] || 1);
    const originFacing = this.facing;
    this.game.spawnSlashTrail(this.position, originFacing, heavy ? '#ffcf82' : '#c9f4ea', heavy ? 1.6 : 1);
    const hits = this.game.hitEnemiesInArc(this.position, originFacing, range, arc, base, heavy);
    if (heavy) this.game.shake(0.24);
    if (this.origin?.id === 'blade' && this.combo === 2) {
      this.stamina = Math.min(this.maxStamina, this.stamina + 10);
    }
    if (hits > 0 && this.origin?.id === 'vanguard') {
      this.mana = Math.min(this.maxMana, this.mana + 4);
    }
  }

  tryDodge() {
    if (this.dead || this.dodgeTime > 0 || this.dodgeCooldown > 0) return;
    if (this.stamina < 18) return;
    this.stamina -= 18;
    this.dodgeTime = 0.42;
    this.dodgeCooldown = 0.55;
    this.invuln = 0.36;
    this.attackTime = 0;
    this.combatTimer = 0;
    const move = this.game.input.getMove();
    if (Math.hypot(move.x, move.z) > 0.1) {
      const yaw = this.game.cameraYaw;
      const wx = Math.sin(yaw) * -move.z + Math.cos(yaw) * move.x;
      const wz = Math.cos(yaw) * -move.z - Math.sin(yaw) * move.x;
      this.dodgeDir.set(wx, 0, wz).normalize();
      this.facing = Math.atan2(wx, wz);
    } else {
      this.dodgeDir.set(Math.sin(this.facing), 0, Math.cos(this.facing));
    }
    this.game.audio.dodge();
  }

  usePotion() {
    if (this.dead) return;
    if (this.potions <= 0) {
      this.game.toast('Sin elixires', 'Encuentra más en cofres y santuarios.', 'danger');
      return;
    }
    if (this.hp >= this.maxHp && this.mana >= this.maxMana) return;
    this.potions--;
    this.hp = Math.min(this.maxHp, this.hp + this.maxHp * 0.45);
    this.mana = Math.min(this.maxMana, this.mana + 20);
    this.game.audio.potion();
    this.game.spawnHealEffect(this.position);
    this.game.toast('Elixir de Aurora', 'La luz recorre tus venas.', 'heal');
    this.game.updateHud();
  }

  takeDamage(amount, source = null, opts = {}) {
    if (this.dead) return;
    if (this.invuln > 0 && !opts.hazard) return;
    let final = amount;
    if (this.blocking && !opts.ignoreBlock) {
      const perfect = this.game.time - this.blockStart < 0.22;
      final *= perfect ? 0.05 : 0.28;
      this.stamina -= perfect ? 4 : 12;
      this.game.audio.block();
      this.game.spawnBlockEffect(this.position, this.facing, perfect);
      if (perfect) {
        this.game.perfectBlock?.(source);
        this.mana = Math.min(this.maxMana, this.mana + 12);
      }
    } else {
      final *= clamp(1 - this.defense / (this.defense + 120), 0.35, 0.92);
    }
    final = Math.max(1, Math.round(final));
    this.hp -= final;
    this.invuln = 0.45;
    this.hurtFlash = 0.24;
    this.combatTimer = 0;
    this.game.audio.hurt();
    this.game.damageNumber(this.position, final, false, true);
    this.game.shake(0.22);
    this.game.flashDamage();
    if (source) {
      const dx = this.position.x - source.mesh.position.x;
      const dz = this.position.z - source.mesh.position.z;
      this.moveBy(dx * 0.08, dz * 0.08);
    }
    if (this.hp <= 0) {
      this.hp = 0;
      this.die();
    }
    this.game.updateHud();
  }

  die() {
    this.dead = true;
    this.deadTime = 0;
    this.blocking = false;
    this.attackTime = 0;
    this.game.audio.death();
    this.game.onPlayerDeath();
  }

  reviveAtSpawn() {
    this.dead = false;
    this.deadTime = 0;
    this.hp = this.maxHp;
    this.mana = this.maxMana;
    this.stamina = this.maxStamina;
    this.invuln = 2;
    this.position.set(this.spawnPoint.x, 0, this.spawnPoint.z);
    this.position.y = this.game.world.heightAt(this.position.x, this.position.z);
    this.mesh.position.copy(this.position);
    this.mesh.visible = true;
  }

  addXp(amount) {
    this.xp += amount;
    let leveled = false;
    while (this.xp >= this.nextXp) {
      this.xp -= this.nextXp;
      this.level++;
      this.nextXp = Math.round(70 + this.level * 48);
      leveled = true;
    }
    if (leveled) {
      this.recomputeStats();
      this.hp = this.maxHp;
      this.mana = this.maxMana;
      this.stamina = this.maxStamina;
      this.game.onLevelUp();
    }
    this.game.updateHud();
  }

  equip(item) {
    if (!item) return;
    if (item.type === 'consumable') {
      if (item.id === 'elixir') { this.potions++; this.game.updateHud(); }
      return;
    }
    const slot = item.type === 'weapon' ? 'weapon' : item.type === 'armor' ? 'armor' : 'charm';
    this.equipment[slot] = item;
    this.recomputeStats();
    if (slot === 'weapon') updateHeroAppearance(this.mesh, { weaponAppearance: item.appearance });
    if (slot === 'armor' && item.appearance?.outfit) {
      const outfit = OUTFITS.find((o) => o.id === item.appearance.outfit) || this.appearance.outfit;
      this.appearance.outfit = outfit;
      updateHeroAppearance(this.mesh, { outfit });
    }
    this.game.audio.chest();
    this.game.updateHud();
  }

  getAttribute(id) { return this.attributes[id] || 0; }
}

import * as THREE from 'three';
import { radialTexture, clamp } from '../core/utils.js';

export class VFX {
  constructor(scene) {
    this.scene = scene;
    this.effects = [];
    this.sparkTexture = radialTexture(64, 'rgba(255,255,255,1)', 'rgba(255,255,255,0)');
  }

  clear() {
    for (const e of this.effects) {
      this.scene.remove(e.object);
      e.object.traverse?.((o) => {
        o.geometry?.dispose?.();
        if (o.material) {
          if (o.material.map && o.material.map !== this.sparkTexture) o.material.map.dispose?.();
          o.material.dispose?.();
        }
      });
    }
    this.effects = [];
  }

  slash(position, facing, color = '#c9f4ea', scale = 1) {
    const group = new THREE.Group();
    const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.95, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false });
    const geo = new THREE.RingGeometry(0.55 * scale, 1.45 * scale, 28, 1, -0.95, 1.9);
    const ring = new THREE.Mesh(geo, mat);
    ring.position.set(0, 1.15, 1.05 * scale);
    ring.rotation.z = 0.2;
    group.add(ring);
    const mat2 = new THREE.MeshBasicMaterial({ color: '#fff6d6', transparent: true, opacity: 0.7, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false });
    const ring2 = new THREE.Mesh(new THREE.RingGeometry(0.62 * scale, 0.68 * scale, 28, 1, -0.95, 1.9), mat2);
    ring2.position.copy(ring.position);
    ring2.rotation.z = 0.2;
    group.add(ring2);
    group.position.set(position.x, position.y + 0.2, position.z);
    group.rotation.y = facing;
    this.scene.add(group);
    this.effects.push({ type: 'slash', object: group, life: 0.32, max: 0.32, mats: [mat, mat2] });
  }

  hitSparks(position, color = '#ffb18a', count = 10) {
    const positions = new Float32Array(count * 3);
    const velocities = [];
    for (let i = 0; i < count; i++) {
      positions[i * 3] = position.x + (Math.random() - 0.5) * 0.3;
      positions[i * 3 + 1] = position.y + 1 + (Math.random() - 0.5) * 0.5;
      positions[i * 3 + 2] = position.z + (Math.random() - 0.5) * 0.3;
      velocities.push(new THREE.Vector3((Math.random() - 0.5) * 4, 1.5 + Math.random() * 3, (Math.random() - 0.5) * 4));
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    const mat = new THREE.PointsMaterial({ color, size: 0.12, transparent: true, opacity: 0.95, blending: THREE.AdditiveBlending, depthWrite: false, map: this.sparkTexture });
    const points = new THREE.Points(geo, mat);
    this.scene.add(points);
    this.effects.push({ type: 'sparks', object: points, velocities, life: 0.55, max: 0.55, mat });
  }

  shockwave({ x, z, radius, color = '#ff7b5e', delay = 0, onHit }) {
    const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.6, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false });
    const ring = new THREE.Mesh(new THREE.RingGeometry(0.4, 0.7, 48), mat);
    ring.rotation.x = -Math.PI / 2;
    ring.position.set(x, 0.1, z);
    this.scene.add(ring);
    this.effects.push({ type: 'shockwave', object: ring, life: 0.8 + delay, max: 0.8 + delay, delay, radius, mat, onHit, fired: false, x, z });
  }

  heal(position) {
    const group = new THREE.Group();
    const mat = new THREE.MeshBasicMaterial({ color: '#9ce7ac', transparent: true, opacity: 0.8, blending: THREE.AdditiveBlending, side: THREE.DoubleSide, depthWrite: false });
    for (let i = 0; i < 3; i++) {
      const ring = new THREE.Mesh(new THREE.TorusGeometry(0.45 + i * 0.18, 0.012, 4, 28), mat);
      ring.rotation.x = Math.PI / 2;
      ring.position.y = 0.2 + i * 0.28;
      group.add(ring);
    }
    group.position.set(position.x, position.y, position.z);
    this.scene.add(group);
    this.effects.push({ type: 'heal', object: group, life: 1.0, max: 1.0, mat });
  }

  block(position, facing, perfect = false) {
    const mat = new THREE.MeshBasicMaterial({ color: perfect ? '#fff2be' : '#bceee6', transparent: true, opacity: 0.9, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false });
    const ring = new THREE.Mesh(new THREE.RingGeometry(0.5, 0.62, 20, 1, -0.9, 1.8), mat);
    ring.position.set(position.x + Math.sin(facing) * 0.8, position.y + 1.15, position.z + Math.cos(facing) * 0.8);
    ring.rotation.y = facing;
    ring.rotation.z = 0.2;
    this.scene.add(ring);
    this.effects.push({ type: 'block', object: ring, life: 0.3, max: 0.3, mat });
  }

  capture(position, color = '#91e7df') {
    const group = new THREE.Group();
    const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.8, blending: THREE.AdditiveBlending, side: THREE.DoubleSide, depthWrite: false });
    for (let i = 0; i < 4; i++) {
      const ring = new THREE.Mesh(new THREE.TorusGeometry(0.5 + i * 0.35, 0.018, 4, 32), mat);
      ring.rotation.x = Math.PI / 2 + i * 0.15;
      ring.rotation.z = i * 0.4;
      group.add(ring);
    }
    group.position.set(position.x, position.y + 0.8, position.z);
    this.scene.add(group);
    this.effects.push({ type: 'capture', object: group, life: 1.4, max: 1.4, mat });
  }

  beam(from, to, color = '#91e7df') {
    const start = new THREE.Vector3(from.x, from.y + 1.2, from.z);
    const end = new THREE.Vector3(to.x, to.y + 1.1, to.z);
    const mid = start.clone().add(end).multiplyScalar(0.5);
    mid.y += 1.8;
    const curve = new THREE.QuadraticBezierCurve3(start, mid, end);
    const geo = new THREE.TubeGeometry(curve, 20, 0.045, 5, false);
    const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false });
    const tube = new THREE.Mesh(geo, mat);
    this.scene.add(tube);
    this.effects.push({ type: 'beam', object: tube, life: 0.55, max: 0.55, mat });
  }

  dust(position, color = '#d8c49a', count = 8) {
    const positions = new Float32Array(count * 3);
    const velocities = [];
    for (let i = 0; i < count; i++) {
      positions[i * 3] = position.x + (Math.random() - 0.5) * 0.6;
      positions[i * 3 + 1] = position.y + 0.2;
      positions[i * 3 + 2] = position.z + (Math.random() - 0.5) * 0.6;
      velocities.push(new THREE.Vector3((Math.random() - 0.5) * 2.2, 0.8 + Math.random() * 1.2, (Math.random() - 0.5) * 2.2));
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    const mat = new THREE.PointsMaterial({ color, size: 0.18, transparent: true, opacity: 0.45, depthWrite: false, map: this.sparkTexture });
    const points = new THREE.Points(geo, mat);
    this.scene.add(points);
    this.effects.push({ type: 'dust', object: points, velocities, life: 0.8, max: 0.8, mat });
  }

  update(dt, game) {
    for (let i = this.effects.length - 1; i >= 0; i--) {
      const e = this.effects[i];
      e.life -= dt;
      const t = clamp(1 - e.life / e.max, 0, 1);
      if (e.type === 'slash') {
        e.object.rotation.z += dt * 2.4;
        e.object.scale.setScalar(1 + t * 0.18);
        e.mats.forEach((m) => { m.opacity = (1 - t) * 0.9; });
      } else if (e.type === 'sparks' || e.type === 'dust') {
        const pos = e.object.geometry.attributes.position;
        for (let j = 0; j < e.velocities.length; j++) {
          const v = e.velocities[j];
          v.y -= dt * 9;
          pos.setXYZ(j, pos.getX(j) + v.x * dt, pos.getY(j) + v.y * dt, pos.getZ(j) + v.z * dt);
        }
        pos.needsUpdate = true;
        e.mat.opacity = (1 - t) * 0.9;
      } else if (e.type === 'shockwave') {
        if (t < e.delay / e.max) {
          e.object.visible = false;
        } else {
          e.object.visible = true;
          const st = clamp((t - e.delay / e.max) / (1 - e.delay / e.max), 0, 1);
          e.object.scale.setScalar(1 + st * e.radius / 0.7);
          e.mat.opacity = (1 - st) * 0.65;
          if (!e.fired && st > 0.3) {
            e.fired = true;
            if (e.onHit) e.onHit();
          }
        }
      } else if (e.type === 'heal') {
        e.object.position.y += dt * 0.5;
        e.object.scale.setScalar(0.8 + t * 0.5);
        e.mat.opacity = (1 - t) * 0.8;
      } else if (e.type === 'block') {
        e.object.scale.setScalar(1 + t * 0.5);
        e.mat.opacity = (1 - t) * 0.9;
      } else if (e.type === 'capture') {
        e.object.rotation.y += dt * 3;
        e.object.scale.setScalar(1 + t * 0.6);
        e.mat.opacity = (1 - t) * 0.8;
      } else if (e.type === 'beam') {
        e.mat.opacity = (1 - t) * 0.9;
        e.object.scale.setScalar(1 + t * 0.1);
      }
      if (e.life <= 0) {
        this.scene.remove(e.object);
        e.object.traverse?.((o) => {
          o.geometry?.dispose?.();
          if (o.material && o.material.map !== this.sparkTexture) o.material.dispose?.();
        });
        this.effects.splice(i, 1);
      }
    }
  }
}

export class Projectile {
  constructor(scene, opts) {
    this.scene = scene;
    this.position = new THREE.Vector3(opts.x, opts.y, opts.z);
    this.dir = opts.dir.clone().normalize();
    this.speed = opts.speed || 10;
    this.damage = opts.damage || 10;
    this.color = opts.color || '#c79bff';
    this.radius = opts.radius || 0.4;
    this.life = opts.life || 3.2;
    this.hostile = opts.hostile !== false;
    this.owner = opts.owner || null;
    this.group = new THREE.Group();
    const core = new THREE.Mesh(new THREE.IcosahedronGeometry(this.radius, 1), new THREE.MeshBasicMaterial({ color: this.color }));
    this.group.add(core);
    const glowMat = new THREE.SpriteMaterial({ map: radialTexture(64, 'rgba(255,255,255,0.9)', 'rgba(255,255,255,0)'), color: this.color, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false });
    const glow = new THREE.Sprite(glowMat);
    glow.scale.set(this.radius * 5, this.radius * 5, 1);
    this.group.add(glow);
    this.group.position.copy(this.position);
    scene.add(this.group);
    this.trailTimer = 0;
  }

  update(dt, game) {
    this.life -= dt;
    this.position.addScaledVector(this.dir, this.speed * dt);
    this.group.position.copy(this.position);
    this.group.rotation.y += dt * 6;
    this.trailTimer -= dt;
    if (this.trailTimer <= 0) {
      this.trailTimer = 0.06;
      game.vfx.hitSparks({ x: this.position.x, y: this.position.y - 0.8, z: this.position.z }, this.color, 1);
    }
    if (this.hostile) {
      const p = game.player.position;
      if (Math.hypot(p.x - this.position.x, p.z - this.position.z) < 0.75 + this.radius && Math.abs((p.y + 1.1) - this.position.y) < 1.6) {
        game.player.takeDamage(this.damage, this.owner);
        this.destroy();
        return;
      }
    }
    if (this.position.y < game.world.heightAt(this.position.x, this.position.z) - 0.2) this.destroy();
    if (this.life <= 0) this.destroy();
  }

  destroy() {
    this.dead = true;
    this.scene.remove(this.group);
    this.group.traverse((o) => {
      o.geometry?.dispose?.();
      o.material?.map?.dispose?.();
      o.material?.dispose?.();
    });
  }
}

