5: const mat = (color, opts = {}) => new THREE.MeshStandardMaterial({
6:   color: new THREE.Color(color),
7:   roughness: opts.roughness ?? 0.78,
8:   metalness: opts.metalness ?? 0.15,
9:   emissive: new THREE.Color(opts.emissive || '#000000'),
10:   emissiveIntensity: opts.emissiveIntensity ?? 1,
11:   flatShading: opts.flat ?? false,
12:   transparent: opts.transparent ?? false,
13:   opacity: opts.opacity ?? 1,
14:   side: opts.side ?? THREE.FrontSide,
15: });
