17: function m(geo, material, pos = [0, 0, 0], rot = [0, 0, 0], scale = [1, 1, 1]) {
18:   const mesh = new THREE.Mesh(geo, material);
19:   mesh.position.set(...pos);
20:   mesh.rotation.set(...rot);
21:   mesh.scale.set(...scale);
22:   mesh.castShadow = true;
23:   mesh.receiveShadow = true;
24:   return mesh;
25: }
