29:   drakmor: { dark: '#241a1b', cloth: '#452520', metal: '#57433c', glow: '#ff7336', eye: '#ffd19a', accent: '#ff5c2d' },
30:   kansordore: { dark: '#211f33', cloth: '#343052', metal: '#6a6282', glow: '#c7b2ff', eye: '#f0e7ff', accent: '#8b78c9' },
