33: function createHumanoid(type, region, boss = false) {
34:   const pal = REGION_ENEMY[region] || REGION_ENEMY.valdoria;
35:   const group = new THREE.Group();
36:   const outfit = { primary: pal.cloth, secondary: pal.dark, trim: pal.metal, metal: pal.metal };
37:   const actor = createHero({ skin: '#514b50', hairColor: pal.dark, hairStyle: 'wild', outfit });
38:   actor.scale.setScalar(boss ? 1.85 : 1.04);
39:   const rig = actor.userData.rig;
40:   rig.sword.visible = false;
41:   rig.aura.visible = false;
42:   // remove heroic circlet glow and face warmth
43:   rig.materials.eyeMat.color.set('#160f18');
44:   rig.materials.eyeMat.emissive.set(pal.eye);
45:   rig.materials.eyeMat.emissiveIntensity = 2.4;
46:   rig.materials.glowMat.color.set(pal.glow);
47:   rig.materials.glowMat.opacity = 0.95;
48:   // darken skin, add cracks
49:   rig.materials.skinMat.color.set('#4b4148');
50:   rig.materials.skinMat.roughness = 0.9;
51:   // horns
52:   const hornMat = mat('#2d282d', { roughness: 0.7, metalness: 0.2 });
53:   for (const s of [-1, 1]) {
54:     const horn = m(new THREE.ConeGeometry(boss ? 0.09 : 0.055, boss ? 0.62 : 0.38, 6), hornMat, [s * 0.15, 0.18, 0.01], [0.1, 0, s * -0.45]);
55:     rig.head.add(horn);
56:   }
57:   // shoulder spikes
58:   for (const s of [-1, 1]) {
59:     rig.torso.add(m(new THREE.ConeGeometry(boss ? 0.11 : 0.06, boss ? 0.48 : 0.28, 5), hornMat, [s * 0.38, 0.24, 0], [0, 0, s * -0.4]));
60:   }
61:   // glowing chest crack
62:   const crackMat = new THREE.MeshBasicMaterial({ color: pal.glow, transparent: true, opacity: 0.8, blending: THREE.AdditiveBlending });
63:   const crack = m(new THREE.BoxGeometry(0.035, boss ? 0.42 : 0.24, 0.02), crackMat, [0.02, 0.05, boss ? 0.25 : 0.205]);
64:   crack.rotation.z = 0.35;
65:   rig.torso.add(crack);
66:   const crack2 = m(new THREE.BoxGeometry(0.025, boss ? 0.2 : 0.14, 0.02), crackMat, [-0.08, -0.02, boss ? 0.25 : 0.205]);
67:   crack2.rotation.z = -0.6;
68:   rig.torso.add(crack2);
69:   // dark sword
70:   const sword = new THREE.Group();
71:   const bladeMat = mat(pal.metal, { metalness: 0.8, roughness: 0.28, emissive: pal.glow, emissiveIntensity: 0.4 });
72:   const blade = m(new THREE.BoxGeometry(boss ? 0.2 : 0.1, boss ? 1.9 : 1.25, boss ? 0.05 : 0.035), bladeMat, [0, boss ? 1.0 : 0.68, 0]);
73:   sword.add(blade);
74:   const tip = m(new THREE.ConeGeometry(boss ? 0.1 : 0.05, boss ? 0.35 : 0.25, 4), bladeMat, [0, boss ? 1.95 : 1.3, 0], [0, 0, Math.PI / 4]);
75:   sword.add(tip);
76:   sword.add(m(new THREE.BoxGeometry(boss ? 0.65 : 0.42, 0.08, 0.11), mat(pal.metal, { metalness: 0.8 }), [0, boss ? 0.05 : 0.04, 0]));
77:   sword.add(m(new THREE.CylinderGeometry(0.04, 0.045, 0.35, 6), mat('#2b2020'), [0, boss ? -0.13 : -0.12, 0]));
78:   sword.position.set(0, -0.7, 0.02);
79:   sword.rotation.x = Math.PI;
80:   rig.rightArm.add(sword);
81:   rig.sword = sword;
82:   // crown for boss
83:   if (boss) {
84:     const crown = new THREE.Group();
85:     crown.position.y = 0.18;
86:     for (let i = 0; i < 5; i++) {
87:       const a = (i / 5) * Math.PI * 2;
88:       crown.add(m(new THREE.ConeGeometry(0.05, 0.25, 4), mat('#c39b52', { metalness: 0.85, roughness: 0.28 }), [Math.cos(a) * 0.16, 0.1, Math.sin(a) * 0.16]));
89:     }
90:     crown.add(m(new THREE.TorusGeometry(0.17, 0.018, 4, 16), mat('#c39b52', { metalness: 0.9, roughness: 0.2 }), [0, 0, 0], [Math.PI / 2, 0, 0]));
91:     rig.head.add(crown);
92:   }
93:   group.add(actor);
94:   group.userData = { type: 'enemy', kind: type, actor, rig, boss, pal, phase: 0 };
95:   return group;
96: }
