98: function createWraith(region, elite = false) {
99:   const pal = REGION_ENEMY[region] || REGION_ENEMY.valdoria;
100:   const group = new THREE.Group();
101:   const body = new THREE.Group();
102:   group.add(body);
103:   const cloth = mat(pal.dark, { transparent: true, opacity: 0.9, side: THREE.DoubleSide, roughness: 0.95 });
104:   const cloth2 = mat(pal.cloth, { transparent: true, opacity: 0.85, side: THREE.DoubleSide });
105:   const glow = new THREE.MeshBasicMaterial({ color: pal.glow, transparent: true, opacity: 0.8, blending: THREE.AdditiveBlending });
106:   const eye = new THREE.MeshBasicMaterial({ color: pal.eye, transparent: true, opacity: 0.95, blending: THREE.AdditiveBlending });
107:   body.add(m(new THREE.ConeGeometry(0.55, 1.8, 7, 1, true), cloth, [0, 1.0, 0]));
108:   body.add(m(new THREE.ConeGeometry(0.42, 1.35, 7, 1, true), cloth2, [0, 1.15, 0.05], [0, 0.3, 0]));
109:   body.add(m(new THREE.SphereGeometry(0.26, 12, 9), cloth, [0, 1.9, 0.02]));
110:   body.add(m(new THREE.SphereGeometry(0.2, 10, 8), mat('#0c0b11'), [0, 1.87, 0.14], [0, 0, 0], [1, 1.1, 0.55]));
111:   body.add(m(new THREE.SphereGeometry(0.03, 6, 4), eye, [-0.07, 1.91, 0.31]));
112:   body.add(m(new THREE.SphereGeometry(0.03, 6, 4), eye, [0.07, 1.91, 0.31]));
113:   body.add(m(new THREE.TorusGeometry(0.34, 0.012, 4, 20), glow, [0, 1.9, 0.02], [Math.PI / 2, 0, 0]));
114:   for (let i = 0; i < 5; i++) {
115:     const a = (i / 5) * Math.PI * 2;
116:     body.add(m(new THREE.ConeGeometry(0.04, 0.45, 4), cloth2, [Math.cos(a) * 0.28, 0.35, Math.sin(a) * 0.28], [Math.sin(a) * 0.4, 0, Math.cos(a) * 0.4]));
117:   }
118:   if (elite) {
119:     body.add(m(new THREE.TorusGeometry(0.5, 0.018, 4, 28), glow, [0, 0.5, 0], [Math.PI / 2, 0, 0]));
120:     body.scale.setScalar(1.2);
121:   }
122:   group.userData = { type: 'enemy', kind: 'wraith', actor: body, boss: false, pal, phase: 0, elite };
123:   return group;
124: }
