126: function createGolem(region, elite = false) {
127:   const pal = REGION_ENEMY[region] || REGION_ENEMY.valdoria;
128:   const group = new THREE.Group();
129:   const body = new THREE.Group();
130:   group.add(body);
131:   const rock = mat(pal.metal, { roughness: 0.98, flat: true });
132:   const rockDark = mat(pal.dark, { roughness: 1, flat: true });
133:   const glow = new THREE.MeshBasicMaterial({ color: pal.glow, transparent: true, opacity: 0.85, blending: THREE.AdditiveBlending });
134:   body.add(m(new THREE.DodecahedronGeometry(0.65, 0), rock, [0, 1.0, 0], [0, 0.4, 0], [1.1, 1.2, 0.8]));
135:   body.add(m(new THREE.DodecahedronGeometry(0.36, 0), rockDark, [0, 1.75, 0], [0.2, 0, 0]));
136:   body.add(m(new THREE.BoxGeometry(0.15, 0.08, 0.05), glow, [-0.12, 1.78, 0.32]));
137:   body.add(m(new THREE.BoxGeometry(0.15, 0.08, 0.05), glow, [0.12, 1.78, 0.32]));
138:   for (const s of [-1, 1]) {
139:     body.add(m(new THREE.DodecahedronGeometry(0.24, 0), rock, [s * 0.75, 1.1, 0], [0, 0, s * 0.3], [1, 1.4, 1]));
140:     body.add(m(new THREE.DodecahedronGeometry(0.2, 0), rockDark, [s * 0.42, 0.35, 0]));
141:     body.add(m(new THREE.BoxGeometry(0.08, 0.65, 0.08), glow, [s * 0.55, 0.9, 0.1], [0, 0, s * 0.4]));
142:   }
143:   for (let i = 0; i < 4; i++) body.add(m(new THREE.ConeGeometry(0.08, 0.3, 4), glow, [0, 1.3 + i * 0.1, 0.42], [0, 0, 0]));
144:   if (elite) body.scale.setScalar(1.25);
145:   group.userData = { type: 'enemy', kind: 'golem', actor: body, boss: false, pal, phase: 0, elite };
146:   return group;
147: }
