149: export function createEnemyMesh(type, region, elite = false, boss = false) {
150:   if (type === 'wraith') return createWraith(region, elite);
151:   if (type === 'golem') return createGolem(region, elite);
152:   return createHumanoid(type, region, boss);
153: }
