155: export class Enemy {
156:   constructor({ type, region, x, z, elite = false, boss = false, chapter = 0, name, id, y = 0, bossType = null }) {
157:     this.id = id || `enemy-${Math.random().toString(36).slice(2, 8)}`;
158:     this.type = type;
159:     this.region = region;
160:     this.elite = elite;
161:     this.boss = boss;
162:     this.bossType = bossType;
163:     this.name = name || (boss ? 'Guardián' : type === 'wraith' ? 'Espectro de Ceniza' : type === 'golem' ? 'Gólem del Velo' : 'Corrupto');
164:     this.level = 1 + chapter * 3 + (elite ? 2 : 0) + (boss ? 5 : 0);
165:     const scale = 1 + chapter * 0.55;
166:     const baseHp = type === 'wraith' ? 42 : type === 'golem' ? 88 : 62;
167:     this.maxHp = Math.round((baseHp + (elite ? 40 : 0) + (boss ? 420 : 0)) * scale);
168:     this.hp = this.maxHp;
169:     this.damage = (type === 'wraith' ? 9 : type === 'golem' ? 14 : 11) * (1 + chapter * 0.32) * (elite ? 1.3 : 1) * (boss ? 1.45 : 1);
170:     this.speed = (type === 'wraith' ? 3.1 : type === 'golem' ? 2.2 : 3.6) * (boss ? 0.95 : 1);
171:     this.radius = boss ? 1.15 : type === 'golem' ? 0.8 : 0.55;
172:     this.aggro = boss ? 24 : type === 'wraith' ? 15 : 13;
173:     this.attackRange = type === 'wraith' ? 9 : boss ? 3.8 : 2.4;
174:     this.xp = Math.round((elite ? 42 : boss ? 280 : 18) * (1 + chapter * 0.55));
175:     this.mesh = createEnemyMesh(type, region, elite, boss);
176:     this.mesh.position.set(x, y, z);
177:     this.mesh.userData.enemy = this;
178:     this.spawn = { x, z };
179:     this.state = 'idle';
180:     this.stateTimer = 0;
181:     this.attackCooldown = 1.2 + Math.random();
182:     this.attackIndex = 0;
183:     this.stagger = 0;
184:     this.hitFlash = 0;
185:     this.deadTime = 0;
186:     this.phase = 0;
187:     this.wanderAngle = Math.random() * Math.PI * 2;
188:     this.wanderTimer = 0;
189:     this.active = false;
190:     this.telegraph = null;
191:     this.facing = Math.random() * Math.PI * 2;
192:     this.animPhase = 0;
193:     this.lastDamageSource = null;
194:     this.captureThreshold = 0.25;
195:     this.capturable = false;
196:     this.isBoss = boss;
197:   }
198: 
199:   get alive() { return this.state !== 'dead'; }
200:   get hpRatio() { return clamp(this.hp / this.maxHp, 0, 1); }
201: 
202:   update(dt, game) {
203:     if (this.state === 'dead') {
204:       this.deadTime += dt;
205:       this.mesh.position.y -= dt * 0.25;
206:       this.mesh.rotation.z += dt * 0.25;
207:       this.mesh.traverse((o) => {
208:         if (o.isMesh && o.material) {
209:           o.material.transparent = true;
210:           o.material.opacity = Math.max(0, 1 - this.deadTime * 0.65);
211:         }
212:       });
213:       if (this.deadTime > 1.8 && this.mesh.parent) game.scene.remove(this.mesh);
214:       return;
215:     }
216:     const player = game.player;
217:     const px = player.position.x, pz = player.position.z;
218:     const dist = Math.hypot(px - this.mesh.position.x, pz - this.mesh.position.z);
219:     this.active = this.active || dist < this.aggro;
220:     this.attackCooldown -= dt;
221:     this.hitFlash = Math.max(0, this.hitFlash - dt);
222:     this.animPhase += dt * (this.state === 'chase' ? this.speed * 1.8 : 1.2);
223:     if (this.stagger > 0) {
224:       this.stagger -= dt;
225:       this.state = 'stagger';
226:       this.updateVisual(dt, game, 0);
227:       if (this.stagger <= 0) this.state = 'chase';
228:       return;
229:     }
230: 
231:     if (this.state === 'idle') {
232:       this.wanderTimer -= dt;
233:       if (this.wanderTimer <= 0) {
234:         this.wanderTimer = 2 + Math.random() * 3;
235:         this.wanderAngle = Math.random() * Math.PI * 2;
236:       }
237:       if (dist < this.aggro) {
238:         this.state = 'chase';
239:         game.onEnemyAggro?.(this);
240:       } else {
241:         const tx = this.spawn.x + Math.cos(this.wanderAngle) * 1.5;
242:         const tz = this.spawn.z + Math.sin(this.wanderAngle) * 1.5;
243:         if (Math.hypot(tx - this.mesh.position.x, tz - this.mesh.position.z) > 0.5) {
244:           this.moveTowards(tx, tz, this.speed * 0.22, dt, game);
245:         }
246:         this.updateVisual(dt, game, 0.2);
247:         return;
248:       }
249:     }
250: 
251:     if (this.state === 'chase') {
252:       if (dist > this.aggro * 1.8) {
253:         this.state = 'idle';
254:         this.updateVisual(dt, game, 0);
255:         return;
256:       }
257:       this.faceTowards(px, pz, dt, 7);
258:       if (this.attackCooldown <= 0 && dist <= this.attackRange) {
259:         this.state = 'windup';
260:         this.stateTimer = this.boss ? 0.65 : 0.55;
261:         this.attackIndex++;
262:         game.audio.arrow?.();
263:         this.showTelegraph(game, this.boss ? 4.5 : this.attackRange + 0.5);
264:       } else {
265:         const stopDistance = this.type === 'wraith' ? 6.5 : this.attackRange * 0.78;
266:         if (dist > stopDistance) this.moveTowards(px, pz, this.speed, dt, game);
267:         else if (this.type === 'wraith') this.strafe(dt, game);
268:         this.updateVisual(dt, game, 1);
269:       }
270:     } else if (this.state === 'windup') {
271:       this.stateTimer -= dt;
272:       this.faceTowards(px, pz, dt, 5);
273:       this.updateVisual(dt, game, 0.1);
274:       if (this.stateTimer <= 0) {
275:         this.strike(game, dist);
276:         this.state = 'recover';
277:         this.stateTimer = this.boss ? 0.9 : 0.65;
278:         this.attackCooldown = this.boss ? 1.0 + Math.random() * 0.8 : 1.5 + Math.random();
279:       }
280:     } else if (this.state === 'recover') {
281:       this.stateTimer -= dt;
282:       this.updateVisual(dt, game, 0);
283:       if (this.stateTimer <= 0) this.state = 'chase';
284:     }
285: 
286:     // boss phase
287:     if (this.boss && this.phase === 0 && this.hpRatio < 0.55) {
288:       this.phase = 1;
289:       this.speed *= 1.22;
290:       this.damage *= 1.18;
291:       game.onBossPhase?.(this);
292:     }
293:   }
294: 
295:   moveTowards(tx, tz, speed, dt, game) {
296:     const dx = tx - this.mesh.position.x, dz = tz - this.mesh.position.z;
297:     const d = Math.hypot(dx, dz);
298:     if (d < 0.01) return;
299:     const nx = dx / d, nz = dz / d;
300:     let mx = this.mesh.position.x + nx * speed * dt;
301:     let mz = this.mesh.position.z + nz * speed * dt;
302:     for (const c of game.world.colliders) {
303:       const dx2 = mx - c.x, dz2 = mz - c.z;
304:       const dd = Math.hypot(dx2, dz2);
305:       if (dd < c.r + this.radius * 0.7) {
306:         const push = (c.r + this.radius * 0.7 - dd) / Math.max(dd, 0.001);
307:         mx += dx2 * push;
308:         mz += dz2 * push;
309:       }
310:     }
311:     const maxR = game.world.bounds;
312:     if (Math.hypot(mx, mz) > maxR) {
313:       const k = maxR / Math.hypot(mx, mz);
314:       mx *= k; mz *= k;
315:     }
316:     this.mesh.position.x = mx;
317:     this.mesh.position.z = mz;
318:     this.mesh.position.y = game.world.heightAt(mx, mz);
319:   }
320: 
321:   strafe(dt, game) {
322:     const a = Math.atan2(game.player.position.x - this.mesh.position.x, game.player.position.z - this.mesh.position.z);
323:     const side = this.attackIndex % 2 ? 1 : -1;
324:     this.moveTowards(this.mesh.position.x + Math.cos(a) * side * 4, this.mesh.position.z - Math.sin(a) * side * 4, this.speed * 0.5, dt, game);
325:   }
326: 
327:   faceTowards(tx, tz, dt, speed) {
328:     const target = Math.atan2(tx - this.mesh.position.x, tz - this.mesh.position.z);
329:     this.facing = dampAngle(this.facing, target, speed, dt);
330:     this.mesh.rotation.y = this.facing;
331:   }
332: 
333:   showTelegraph(game, radius) {
334:     const color = this.boss ? '#ff5d4e' : this.type === 'wraith' ? '#c28bff' : '#ff9a62';
335:     const geo = new THREE.RingGeometry(0.25, radius, 40);
336:     const material = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.45, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending });
337:     const ring = new THREE.Mesh(geo, material);
338:     ring.rotation.x = -Math.PI / 2;
339:     ring.position.set(this.mesh.position.x, game.world.heightAt(this.mesh.position.x, this.mesh.position.z) + 0.08, this.mesh.position.z);
340:     game.scene.add(ring);
341:     this.telegraph = { mesh: ring, life: this.boss ? 0.65 : 0.55, maxLife: this.boss ? 0.65 : 0.55, radius };
342:   }
343: 
344:   strike(game, dist) {
345:     const player = game.player;
346:     const d = dist2D(this.mesh.position, player.position);
347:     if (this.type === 'wraith') {
348:       const dir = new THREE.Vector3(player.position.x - this.mesh.position.x, 0, player.position.z - this.mesh.position.z).normalize();
349:       game.spawnEnemyProjectile({
350:         x: this.mesh.position.x, y: this.mesh.position.y + 1.45, z: this.mesh.position.z,
351:         dir, damage: this.damage * 0.85, color: this.boss ? '#ff8a62' : '#c79bff', speed: 10,
352:         radius: 0.45,
353:       });
354:       game.audio.arrow();
355:     } else if (this.boss) {
356:       if (this.attackIndex % 3 === 0) {
357:         game.spawnShockwave({ x: this.mesh.position.x, z: this.mesh.position.z, radius: 5.4, damage: this.damage * 1.25, color: '#ff7b5e', delay: 0.18 });
358:       } else if (this.attackIndex % 3 === 1) {
359:         // dash
360:         const dx = player.position.x - this.mesh.position.x, dz = player.position.z - this.mesh.position.z;
361:         const len = Math.hypot(dx, dz) || 1;
362:         const tx = this.mesh.position.x + dx / len * 4.4;
363:         const tz = this.mesh.position.z + dz / len * 4.4;
364:         game.spawnSlashTrail(this.mesh.position, this.facing, '#ff7b5e', 1.7);
365:         this.mesh.position.x = tx; this.mesh.position.z = tz;
366:         this.mesh.position.y = game.world.heightAt(tx, tz);
367:         if (Math.hypot(player.position.x - tx, player.position.z - tz) < 2.8) game.damagePlayer(this.damage * 1.1, this);
368:         game.shake(0.3);
369:       } else {
370:         for (let i = -1; i <= 1; i++) {
371:           const a = this.facing + i * 0.3;
372:           game.spawnEnemyProjectile({
373:             x: this.mesh.position.x, y: this.mesh.position.y + 1.8, z: this.mesh.position.z,
374:             dir: new THREE.Vector3(Math.sin(a), 0, Math.cos(a)), damage: this.damage * 0.7, color: '#ff9a62', speed: 9, radius: 0.55,
375:           });
376:         }
377:       }
378:       game.audio.bossRoar?.();
379:     } else if (d < this.attackRange + 0.7) {
380:       game.damagePlayer(this.damage, this);
381:       game.spawnSlashTrail(this.mesh.position, this.facing, this.elite ? '#ffb35c' : '#c49bff', 1.1);
382:     }
383:     if (this.telegraph) {
384:       game.scene.remove(this.telegraph.mesh);
