  const q = this.quests[this.regionId];
  if (!q || q.bossDefeated || q.stage < 2) return;
  if (this.boss && this.boss.alive) return;
  const trigger = this.world?.bossTrigger;
  if (!trigger) return;
  if (dist2D(this.player.position, trigger) > trigger.r) return;
  this.spawnBoss();
}

