  const data = BOSS_DATA[this.regionId];
  if (!data) return;
  const t = this.world.bossTrigger;
  const y = this.world.heightAt(t.x, t.z);
  const boss = new Enemy({
    type: data.type,
    region: this.regionId,
    x: t.x,
    z: t.z,
